
    // ============================================================
    // ELECTRON: ПРИНУДИТЕЛЬНЫЙ ДЕСКТОПНЫЙ РЕЖИМ (Task 131)
    // ============================================================
    // Проблема: при уменьшении окна десктопного приложения ниже 1024px
    // media-запросы CSS и isDesktop() переключали интерфейс в мобильный
    // вид. В десктопном приложении это не нужно.
    //
    // Решение: если страница запущена в Electron (определяем по User-Agent),
    // приложение ВСЕГДА работает в десктопном режиме при любом размере окна:
    //   1) window.matchMedia для width-запросов отвечает так, будто окно
    //      бесконечно широкое: (min-width: N) — всегда true,
    //      (max-width: N) — всегда false. Запросы без width-условий
    //      (prefers-color-scheme и т.п.) проходят без изменений;
    //   2) media-условия в уже разобранных CSS-таблицах переписываются:
    //      (min-width: 1024px) -> all      (десктопные стили — всегда)
    //      (max-width: 1023px) -> not all  (мобильные стили — никогда)
    //      Обход рекурсивный: вложенные @media-блоки тоже обрабатываются.
    //
    // Почему User-Agent, а не window.__isElectron: флаг ставится main.js
    // на dom-ready — ПОЗЖЕ выполнения скриптов страницы, а решение о
    // десктопном режиме нужно сразу, до первого рендера.
    var IS_ELECTRON = /Electron/i.test(navigator.userAgent || '');

    if (IS_ELECTRON) {
        (function () {
            'use strict';

            // Ранний флаг для остального кода (main.js продублирует его на dom-ready)
            try { window.__isElectron = true; } catch (e) {}

            var _origMatchMedia = window.matchMedia.bind(window);

            // Все (min|max)-width условия в media-запросе
            var _WIDTH_COND_RE = /(min-width|max-width)\s*:\s*[\d.]+\s*(?:px|em|rem)\s*/gi;

            // Вычислить запрос так, будто окно бесконечно широкое.
            // null — если width-условий нет (запрос не про ширину).
            function _evalAsWideViewport(query) {
                var found = false;
                var result = true;
                var m;
                _WIDTH_COND_RE.lastIndex = 0;
                while ((m = _WIDTH_COND_RE.exec(query)) !== null) {
                    found = true;
                    if (m[1].toLowerCase() === 'max-width') result = false;
                }
                return found ? result : null;
            }

            // Статичный аналог MediaQueryList: состояние никогда не меняется,
            // поэтому слушатели change — заглушки (перехода в мобильный режим нет)
            function _StaticMQL(query, matches) {
                this.media = query;
                this.matches = matches;
                this.onchange = null;
            }
            _StaticMQL.prototype.addListener = function () {};
            _StaticMQL.prototype.removeListener = function () {};
            _StaticMQL.prototype.addEventListener = function () {};
            _StaticMQL.prototype.removeEventListener = function () {};
            _StaticMQL.prototype.dispatchEvent = function () { return false; };

            window.matchMedia = function (query) {
                var wide = _evalAsWideViewport(String(query || ''));
                if (wide === null) return _origMatchMedia(query); // не width-запрос
                return new _StaticMQL(query, wide);
            };

            // --- CSS: переписать media-условия в разобранных таблицах стилей ---

            function _norm(s) { return String(s || '').replace(/\s+/g, ''); }

            function _walkMediaRules(rules, fallbackCss) {
                for (var i = 0; i < rules.length; i++) {
                    var r = rules[i];
                    if (!r) continue;
                    var isMedia = (typeof CSSMediaRule !== 'undefined') && (r instanceof CSSMediaRule);
                    if (isMedia) {
                        var cond = _norm(r.media && r.media.mediaText);
                        var isDesktopBlock = cond.indexOf('min-width:1024px') !== -1;
                        var isMobileBlock = cond.indexOf('max-width:1023px') !== -1;
                        if (isDesktopBlock || isMobileBlock) {
                            var target = isDesktopBlock ? 'all' : 'not all';
                            try {
                                r.media.mediaText = target;
                            } catch (e) { /* см. fallback ниже */ }
                            // Проверить, применилась ли замена условия
                            if (_norm(r.media && r.media.mediaText) !== _norm(target)) {
                                // Fallback: мутация не сработала (неожиданно для Chromium).
                                // Для десктопного блока — собрать содержимое в буфер:
                                // оно будет добавлено отдельным <style> без условий.
                                if (isDesktopBlock && r.cssRules) {
                                    for (var k = 0; k < r.cssRules.length; k++) {
                                        fallbackCss.push(r.cssRules[k].cssText);
                                    }
                                }
                                // Мобильный блок в fallback не копируем: его правила
                                // продолжат действовать только ниже 1024px, а буфер
                                // десктопных правил в конце документа перекроет их
                            }
                        }
                    }
                    // Рекурсия во вложенные правила (в т.ч. вложенные @media)
                    if (r.cssRules && r.cssRules.length) _walkMediaRules(r.cssRules, fallbackCss);
                }
            }

            function _forceDesktopCss() {
                try {
                    var fallbackCss = [];
                    var sheets = Array.prototype.slice.call(document.styleSheets);
                    for (var s = 0; s < sheets.length; s++) {
                        var rules = null;
                        try { rules = sheets[s].cssRules; } catch (e) { rules = null; }
                        if (rules && rules.length) _walkMediaRules(rules, fallbackCss);
                    }
                    // Fallback-стили добавляются только если какая-то мутация не прошла
                    if (fallbackCss.length) {
                        var old = document.getElementById('electronForceDesktopCss');
                        if (old && old.parentNode) old.parentNode.removeChild(old);
                        var st = document.createElement('style');
                        st.id = 'electronForceDesktopCss';
                        st.textContent = '/* Electron: принудительные десктопные стили (fallback) */\n' + fallbackCss.join('\n');
                        (document.head || document.documentElement).appendChild(st);
                    }
                } catch (e) { /* CSS-часть не критична: JS-часть уже работает */ }
            }

            // Основной <style> в <head> уже разобран к этому моменту — применяем сразу
            _forceDesktopCss();
            // Повтор после полной загрузки и с задержкой — страховка от поздно
            // добавленных стилей (операция идемпотентна)
            window.addEventListener('load', _forceDesktopCss);
            setTimeout(_forceDesktopCss, 1500);
        })();
    }


    // ============================================================
    // Task 147: ГРАФИКИ — модуль только десктопа. Код графиков
    // полностью вынесен в charts-desktop.js (мобильная PWA не
    // содержит ни байта логики графиков). В Electron — динамическая
    // загрузка модуля: он инъектирует CSS, страницу page-charts,
    // кнопку на КИП ИОС и сам модуль KipCharts, затем повторно
    // применяет фильтрацию ролей.
    // ============================================================
    if (IS_ELECTRON) {
        // Task 147: графики; Task 148: таблица приборов — модули только десктопа.
        // Мобильная PWA не содержит и не загружает эти файлы.
        ['charts-desktop.js', 'devices-table-desktop.js'].forEach(function (src) {
            var s = document.createElement('script');
            s.src = src;
            s.onerror = function () { console.warn('[desktop] ' + src + ' не загрузился'); };
            document.head.appendChild(s);
        });
    }

    // ============================================================
    // Task 149: ЕДИНЫЙ ПОИСК В ШАПКЕ (по образцу Кабельного журнала)
    // ============================================================
    // Иконка-кнопка справа от заголовка/крошек; по клику поле
    // разворачивается горизонтально влево. Ширина поля вычисляется
    // так, чтобы оно доходило до ТЕКСТА хлебных крошек (заголовка
    // страницы) с небольшим отступом — крошки не скрываются.
    // Повторный клик по иконке (или Esc/blur с пустым полем) —
    // сворачивает поле; текст запроса при закрытии сбрасывается.
    // ============================================================
    (function () {
        'use strict';

        var GAP_FROM_TITLE = 12;   // отступ поля от текста крошек, px
        var GAP_BTN_TO_INPUT = 8;  // зазор поле-кнопки, px

        // Пересчитать ширину и left открытого поля: от правого края
        // (самая левая кнопка шапки + зазор) влево до края текста
        // заголовка/крошек. Task 152: работает и для Кабельного журнала.
        function fitToTitle(input) {
            var header = input.closest('.page-inline-header');
            if (!header) return;
            var title = header.querySelector('.page-inline-header-title');
            if (!title) return;

            // Все координаты — в системе шапки (position: absolute
            // относительно .page-inline-header): left = X_вьюпорта - X_шапки
            var headerRect = header.getBoundingClientRect();

            // Правый край поля = самая ЛЕВАЯ кнопка шапки минус зазор.
            // Учитываем все кнопки-иконки: поиск, «Таблица» (Task 148),
            // cj-кнопки (Task 505: и значок печати), «Удалить все» на
            // Избранном (Task 164) — поле не должно наезжать ни на одну.
            var buttons = header.querySelectorAll('.dev-search-toggle-btn, .dev-table-toggle-btn, .cj-icon-btn-inline, .cj-add-btn-inline, .cj-print-btn-inline, .fav-header-clear-btn');
            var inputRight = headerRect.width; // fallback — правый край шапки
            buttons.forEach(function (b) {
                if (b === input) return;
                var br = b.getBoundingClientRect();
                if (br.width === 0) return; // скрытая (display:none)
                var bLeft = br.left - headerRect.left;
                if (bLeft < inputRight) inputRight = bLeft;
            });
            inputRight -= GAP_BTN_TO_INPUT;

            // Левая граница = конец ВИДИМОГО текста крошек/заголовка + отступ.
            // Крошки — <span>-ы в заголовке; берём последний span.
            // Обычный заголовок — текстовый узел: Range для точной ширины.
            // Task 153: на мобильном заголовок обрезается (overflow) —
            // берём min(конец текста, правый край контейнера заголовка
            // минус padding), чтобы поле не «съедало» весь заголовок:
            // текст остаётся видимым до начала поля.
            var textRight = 0;
            var spans = title.querySelectorAll('span');
            if (spans.length) {
                var last = spans[spans.length - 1];
                var tr = last.getBoundingClientRect();
                textRight = tr.right - headerRect.left;   // координата в системе шапки
            } else {
                try {
                    var range = document.createRange();
                    range.selectNodeContents(title);
                    var rects = range.getClientRects();
                    if (rects.length) textRight = rects[rects.length - 1].right - headerRect.left;
                } catch (e) {}
                // Видимая (не обрезанная) часть: clientWidth минус правый padding
                var titleRect = title.getBoundingClientRect();
                var titleLeft = titleRect.left - headerRect.left;
                var visibleRight = titleLeft + title.clientWidth;
                var csTitle = getComputedStyle(title);
                var padRight = parseFloat(csTitle.paddingRight) || 0;
                var visibleTextRight = visibleRight - padRight;
                if (visibleTextRight < textRight) textRight = visibleTextRight;
            }
            if (!textRight) textRight = Math.min(headerRect.width * 0.5, 260);

            // Ширина: от левого края (крошки + отступ) до правого края поля
            var left = textRight + GAP_FROM_TITLE;
            var width = inputRight - left;
            // Минимальная комфортная ширина поля
            var MIN_W = 150;
            if (width < MIN_W) {
                // Крошки/заголовок длинные — поле фиксированной ширины
                // от правого края; заголовок на мобильном обрезается
                // (ellipsis) — это уже текущее поведение шапки
                width = Math.min(220, Math.max(MIN_W, inputRight - 44));
                left = Math.max(44, inputRight - width);
            }
            input.style.left = left + 'px';
            input.style.right = 'auto';
            input.style.width = width + 'px';
            input.style.maxWidth = 'none';
            input.style.minWidth = '0';
        }

        // Открыть поле
        function openSearch(input, btn) {
            input.removeAttribute('hidden');
            // force reflow для анимации
            void input.offsetWidth;
            input.classList.add('search-open');
            btn.classList.add('active');
            fitToTitle(input);
            setTimeout(function () { try { input.focus(); } catch (e) {} }, 30);
        }

        // Закрыть поле (сброс запроса)
        function closeSearch(input, btn) {
            input.classList.remove('search-open');
            input.setAttribute('hidden', '');
            btn.classList.remove('active');
            if (input.value) {
                input.value = '';
                // Вызвать исходный oninput для сброса фильтра
                input.dispatchEvent(new Event('input', { bubbles: true }));
            }
        }

        // Делегированный клик по кнопкам-иконкам
        document.addEventListener('click', function (e) {
            var btn = e.target.closest ? e.target.closest('.dev-search-toggle-btn') : null;
            if (!btn) return;
            var inputId = btn.getAttribute('data-search-input');
            var input = document.getElementById(inputId);
            if (!input) return;
            if (input.classList.contains('search-open')) {
                closeSearch(input, btn);
            } else {
                openSearch(input, btn);
            }
        });

        // Esc — закрыть поиск на активном поле
        document.addEventListener('keydown', function (e) {
            if (e.key !== 'Escape') return;
            var input = document.activeElement;
            if (input && input.classList && input.classList.contains('dev-header-search') && input.classList.contains('search-open')) {
                var btn = document.getElementById(input.id + 'ToggleBtn');
                if (btn) closeSearch(input, btn);
            }
        });

        // При вводе — пересчитать ширину (крошки могли смениться,
        // например при фильтрации меняется подпись)
        document.addEventListener('input', function (e) {
            var input = e.target;
            if (input && input.classList && input.classList.contains('dev-header-search')
                && input.classList.contains('search-open')) {
                fitToTitle(input);
            }
        }, true);

        // Ресайз окна — подогнать открытое поле
        window.addEventListener('resize', function () {
            document.querySelectorAll('.dev-header-search.search-open').forEach(fitToTitle);
        });


        // Task 156: счётчик результатов поиска — строка «Найдено: N из M»
        // над списком при активном поиске. Вызывается из рендеров списков
        // после отрисовки; без поискового запроса — удаляет счётчик.
        window.kipRenderSearchCounter = function (listEl, found, total, query) {
            if (!listEl) return;
            var old = null;
            for (var i = 0; i < listEl.children.length; i++) {
                if (listEl.children[i].classList && listEl.children[i].classList.contains('kip-search-counter')) {
                    old = listEl.children[i];
                    break;
                }
            }
            if (old) old.remove();
            if (!query) return; // без поиска счётчик не показываем
            var div = document.createElement('div');
            div.className = 'kip-search-counter';
            div.textContent = 'Найдено: ' + found + ' из ' + total;
            listEl.insertBefore(div, listEl.firstChild);
        };

        // Task 154: свернуть все раскрытые поиски (вызывается при
        // смене страницы). Запрос сбрасывается с перерендером списка,
        // чтобы вернувшийся пользователь видел полный список.
        window.kipCollapseSearch = function () {
            document.querySelectorAll('.dev-header-search.search-open').forEach(function (input) {
                var btn = document.getElementById((input.getAttribute('data-toggle-btn') || input.id) + 'ToggleBtn');
                if (!btn) {
                    // fallback: кнопка по data-search-input
                    btn = document.querySelector('.dev-search-toggle-btn[data-search-input="' + input.id + '"]');
                }
                if (input.classList.contains('cj-header-search')) return; // cj теперь тоже общий, но на всякий случай
                input.classList.remove('search-open');
                input.setAttribute('hidden', '');
                if (btn) btn.classList.remove('active');
                if (input.value) {
                    input.value = '';
                    input.dispatchEvent(new Event('input', { bubbles: true }));
                }
            });
        };
    })();

    // ======================== ИГРА САПЁР ========================
    let msCols = 9, msRows = 9, msMines = 10;
    let msCurrentDiff = 'easy';    // Task 192: активная сложность
    let msLayoutWasDesktop = null; // Task 192: ориентация поля при прошлом рендере
    let msBoard = [], msRevealed = [], msFlagged = [], msGameOver = false, msFirstClick = true;
    let msTimerInterval = null, msSeconds = 0;
    let msLongPressTimer = null, msLongPressFired = false;

    const msDifficulties = {
        easy: { cols: 9, rows: 9, mines: 10 },
        medium: { cols: 9, rows: 16, mines: 25 },
        hard: { cols: 9, rows: 28, mines: 45 }
    };

    // Task 192: десктопный лейаут (>= 1024px) — игровые поля
    // горизонтальные; на мобильном/планшете — вертикальные, как раньше
    function msIsDesktopLayout() {
        return window.innerWidth >= 1024;
    }

    // Task 192: эффективные размеры поля — на десктопе medium/hard
    // разворачиваются горизонтально (16x9, 28x9), easy остаётся квадратом
    function msEffectiveDims(diff) {
        const d = msDifficulties[diff] || msDifficulties.easy;
        if (msIsDesktopLayout() && d.rows > d.cols) {
            return { cols: d.rows, rows: d.cols, mines: d.mines };
        }
        return { cols: d.cols, rows: d.rows, mines: d.mines };
    }

    // Task 192: подпись сложности в селекторе — «ширина x высота»
    // текущей ориентации: на десктопе «16x9» / «28x9», на мобильном «9x16» / «9x28»
    function msDiffLabel(diff) {
        const d = msDifficulties[diff];
        if (!d) return '';
        const w = msIsDesktopLayout() ? Math.max(d.cols, d.rows) : d.cols;
        const h = msIsDesktopLayout() ? Math.min(d.cols, d.rows) : d.rows;
        return w + 'x' + h;
    }

    // Task 192: обновить подписи сложностей в селекторе под ориентацию
    function msUpdateDiffLabels() {
        const sel = document.getElementById('msDiffSelect');
        if (!sel) return;
        Object.keys(msDifficulties).forEach(function (k) {
            const opt = sel.querySelector('option[value="' + k + '"]');
            if (opt) opt.textContent = msDiffLabel(k);
        });
    }

    function msSetDifficulty(diff) {
        if (!msDifficulties[diff]) return;
        msCurrentDiff = diff;
        const sel = document.getElementById('msDiffSelect');
        if (sel) sel.value = diff;
        msInit();
    }

    function msInit() {
        // Task 192: размеры поля зависят от ориентации (десктоп — горизонталь)
        const dims = msEffectiveDims(msCurrentDiff);
        msCols = dims.cols; msRows = dims.rows; msMines = dims.mines;
        msLayoutWasDesktop = msIsDesktopLayout();
        msBoard = []; msRevealed = []; msFlagged = [];
        msGameOver = false; msFirstClick = true; msSeconds = 0;
        if (msTimerInterval) { clearInterval(msTimerInterval); msTimerInterval = null; }
        document.getElementById('msTimer').textContent = '000';
        document.getElementById('msMineCount').textContent = msMines;
        document.getElementById('msFaceBtn').textContent = '😊';
        document.getElementById('msOverlay').style.display = 'none';

        for (let r = 0; r < msRows; r++) {
            msBoard[r] = []; msRevealed[r] = []; msFlagged[r] = [];
            for (let c = 0; c < msCols; c++) {
                msBoard[r][c] = 0; msRevealed[r][c] = false; msFlagged[r][c] = false;
            }
        }
        msUpdateDiffLabels();    // Task 192: подписи под ориентацию
        msApplyContainerWidth(); // Task 192: ширина панели под поле
        msMigrateResults();      // Task 193: разовый перенос побед из старого ключа
        msRenderAchievements();  // Task 193: лучшие результаты по времени
        msUpdateHint();          // Task 192: подсказка под устройство (мышь/тач)
        msRender();
    }

    function msPlaceMines(safeR, safeC) {
        let placed = 0;
        while (placed < msMines) {
            let r = Math.floor(Math.random() * msRows);
            let c = Math.floor(Math.random() * msCols);
            if (msBoard[r][c] === -1) continue;
            if (Math.abs(r - safeR) <= 1 && Math.abs(c - safeC) <= 1) continue;
            msBoard[r][c] = -1;
            placed++;
        }
        for (let r = 0; r < msRows; r++) {
            for (let c = 0; c < msCols; c++) {
                if (msBoard[r][c] === -1) continue;
                let count = 0;
                for (let dr = -1; dr <= 1; dr++) {
                    for (let dc = -1; dc <= 1; dc++) {
                        let nr = r + dr, nc = c + dc;
                        if (nr >= 0 && nr < msRows && nc >= 0 && nc < msCols && msBoard[nr][nc] === -1) count++;
                    }
                }
                msBoard[r][c] = count;
            }
        }
    }

    function msCalcCellSize(colsParam) {
        // Task 192: количество колонок можно передать явно (для тестов и
        // расчёта ширины панели); по умолчанию — активные msCols
        const cols = (typeof colsParam === 'number' && colsParam > 0) ? colsParam : msCols;
        const isDesktop = window.innerWidth >= 1024; // Task 191: десктопный лейаут
        const containerPad = 32;  // ms-container: padding 10px*2 + margin
        const boardPad = window.innerWidth <= 400 ? 8 : 16; // ms-board padding 4px*2 or 8px*2
        const gapSize = window.innerWidth <= 400 ? 1 : 2;
        // Task 191: на десктопе scroll-spacer скрыт (не нужен для мыши)
        const scrollSpace = isDesktop ? 0 : 36;
        // Task 191: базовая ширина — реальная ширина страницы (на десктопе она
        // может быть уже окна из-за открытой detail-панели), с fallback на окно
        let baseW = window.innerWidth;
        const msPage = document.getElementById('page-minesweeper');
        if (msPage && msPage.clientWidth > 0) baseW = msPage.clientWidth;
        const availW = baseW - containerPad - boardPad - scrollSpace;
        let cellSz = Math.floor((availW - (cols - 1) * gapSize) / cols);
        // Task 191: на десктопе ограничиваем клетку сверху (40px), иначе поле
        // растягивается почти на весь экран и выглядит гигантским
        if (isDesktop && cellSz > 40) cellSz = 40;
        return Math.max(cellSz, 20); // minimum 20px for tappability
    }

    // Task 192: ширина панели игры на десктопе — под фактическую ширину
    // горизонтального поля при клетке 40px (9x9 → 520px, 16x9 → ~710px,
    // 28x9 → ~1225px). На мобильном инлайн-ширина сбрасывается — там панель
    // и так на всю ширину экрана.
    function msApplyContainerWidth() {
        const cont = document.querySelector('#page-minesweeper .ms-container');
        if (!cont) return;
        if (msIsDesktopLayout()) {
            const gapSize = 2;
            // клетка 40px + гэпы + паддинги доски (8px*2 + border 1px*2) и панели (16px*2)
            const w = msCols * 40 + (msCols - 1) * gapSize + 18 + 32;
            cont.style.maxWidth = Math.max(w, 520) + 'px';
        } else {
            cont.style.maxWidth = '';
        }
    }

    // Task 192: подсказка управления под устройство: на десктопе флаг —
    // правый клик мышью, на тач-устройстве — долгое нажатие
    function msUpdateHint() {
        const hint = document.querySelector('#page-minesweeper .ms-hint');
        if (!hint) return;
        hint.textContent = msIsDesktopLayout()
            ? 'Клик — открыть клетку · Правый клик — поставить флаг'
            : 'Нажмите — открыть клетку · Долгое нажатие — поставить флаг';
    }

    function msRender() {
        let board = document.getElementById('msBoard');
        const cellSize = msCalcCellSize();
        const fontSize = cellSize <= 24 ? 10 : cellSize <= 28 ? 12 : 14;
        const gapSize = window.innerWidth <= 400 ? 1 : 2;
        board.style.gridTemplateColumns = `repeat(${msCols}, ${cellSize}px)`;
        board.style.gap = gapSize + 'px';
        board.innerHTML = '';
        for (let r = 0; r < msRows; r++) {
            for (let c = 0; c < msCols; c++) {
                let cell = document.createElement('div');
                cell.className = 'ms-cell';
                cell.dataset.r = r; cell.dataset.c = c;
                cell.style.width = cellSize + 'px';
                cell.style.height = cellSize + 'px';
                cell.style.fontSize = fontSize + 'px';

                if (msRevealed[r][c]) {
                    cell.classList.add('ms-cell-revealed');
                    if (msBoard[r][c] === -1) {
                        cell.classList.add(msGameOver ? 'ms-cell-mine-hit' : 'ms-cell-mine');
                        cell.innerHTML = '<span class="ms-mine-icon" style="font-size:' + Math.round(cellSize * 0.55) + 'px">●</span>';
                    } else if (msBoard[r][c] > 0) {
                        cell.classList.add('ms-num-' + msBoard[r][c]);
                        cell.textContent = msBoard[r][c];
                    }
                } else if (msFlagged[r][c]) {
                    cell.classList.add('ms-cell-hidden', 'ms-cell-flagged');
                    cell.innerHTML = '<span class="ms-flag-icon" style="font-size:' + Math.round(cellSize * 0.5) + 'px">⚑</span>';
                } else {
                    cell.classList.add('ms-cell-hidden');
                }

                // Unified pointer handling for mobile + desktop
                let msCellTouchFired = false;
                let msCellTouchTimer = null;

                cell.addEventListener('touchstart', function(e) {
                    msLongPressFired = false;
                    msCellTouchFired = true;
                    msLongPressTimer = setTimeout(() => {
                        msLongPressFired = true;
                        msToggleFlag(r, c);
                        if (navigator.vibrate) navigator.vibrate(30);
                    }, 400);
                }, { passive: true });

                cell.addEventListener('touchend', function(e) {
                    if (msLongPressTimer) { clearTimeout(msLongPressTimer); msLongPressTimer = null; }
                    if (!msLongPressFired && !msGameOver) {
                        msReveal(r, c);
                    }
                    e.preventDefault(); // prevent subsequent click event on mobile
                });

                cell.addEventListener('touchmove', function() {
                    if (msLongPressTimer) { clearTimeout(msLongPressTimer); msLongPressTimer = null; }
                    msCellTouchFired = false;
                }, { passive: true });

                // Mouse click for desktop — skip if touch already handled
                cell.addEventListener('click', function(e) {
                    if (msCellTouchFired) { msCellTouchFired = false; return; }
                    if (msGameOver) return;
                    msReveal(r, c);
                });

                cell.addEventListener('contextmenu', function(e) {
                    e.preventDefault();
                    if (msGameOver) return;
                    msToggleFlag(r, c);
                });

                board.appendChild(cell);
            }
        }
    }

    // Recalculate cell sizes on resize/orientation change
    window.addEventListener('resize', function() {
        const page = document.getElementById('page-minesweeper');
        if (!page || !page.classList.contains('active')) return;
        // Task 192: при переходе десктоп↔мобиль поле меняет ориентацию —
        // перезапускаем игру с новыми размерами (транспонировать живое поле
        // нельзя), иначе просто пересчитываем размер клеток
        if (msLayoutWasDesktop !== null && msIsDesktopLayout() !== msLayoutWasDesktop) {
            msInit();
        } else {
            msRender();
        }
    });

    function msReveal(r, c) {
        if (msGameOver || msRevealed[r][c] || msFlagged[r][c]) return;
        if (msFirstClick) {
            msFirstClick = false;
            msPlaceMines(r, c);
            msTimerInterval = setInterval(() => {
                msSeconds++;
                document.getElementById('msTimer').textContent = String(msSeconds).padStart(3, '0');
            }, 1000);
        }
        msRevealed[r][c] = true;
        if (msBoard[r][c] === -1) {
            msGameOver = true;
            msRevealAllMines();
            document.getElementById('msFaceBtn').textContent = '😵';
            if (msTimerInterval) { clearInterval(msTimerInterval); msTimerInterval = null; }
            msShowOverlay(false);
        } else if (msBoard[r][c] === 0) {
            msFloodReveal(r, c);
        }
        msRender();
        msCheckWin();
    }

    function msFloodReveal(r, c) {
        for (let dr = -1; dr <= 1; dr++) {
            for (let dc = -1; dc <= 1; dc++) {
                let nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr < msRows && nc >= 0 && nc < msCols && !msRevealed[nr][nc] && !msFlagged[nr][nc]) {
                    msRevealed[nr][nc] = true;
                    if (msBoard[nr][nc] === 0) msFloodReveal(nr, nc);
                }
            }
        }
    }

    function msToggleFlag(r, c) {
        if (msGameOver || msRevealed[r][c]) return;
        msFlagged[r][c] = !msFlagged[r][c];
        let flagCount = msFlagged.flat().filter(Boolean).length;
        document.getElementById('msMineCount').textContent = Math.max(0, msMines - flagCount);
        msRender();
        msCheckWin();
    }

    function msRevealAllMines() {
        for (let r = 0; r < msRows; r++) {
            for (let c = 0; c < msCols; c++) {
                if (msBoard[r][c] === -1) msRevealed[r][c] = true;
            }
        }
    }

    function msCheckWin() {
        if (msGameOver) return;
        let hiddenCount = 0;
        for (let r = 0; r < msRows; r++) {
            for (let c = 0; c < msCols; c++) {
                if (!msRevealed[r][c]) hiddenCount++;
            }
        }
        if (hiddenCount === msMines) {
            msGameOver = true;
            document.getElementById('msFaceBtn').textContent = '😎';
            if (msTimerInterval) { clearInterval(msTimerInterval); msTimerInterval = null; }
            // Auto-flag all mines
            for (let r = 0; r < msRows; r++) {
                for (let c = 0; c < msCols; c++) {
                    if (msBoard[r][c] === -1) msFlagged[r][c] = true;
                }
            }
            document.getElementById('msMineCount').textContent = '0';
            msRender();
            msShowOverlay(true);
        }
    }

    function msShowOverlay(won) {
        let overlay = document.getElementById('msOverlay');
        let text = document.getElementById('msGameOverText');
        let sub = document.getElementById('msGameOverSub');
        if (won) {
            text.textContent = '🎉 Победа!';
            text.style.color = '#4ac771';
            sub.textContent = 'Время: ' + msSeconds + ' сек';
        } else {
            text.textContent = '💥 Взрыв!';
            text.style.color = '#c74a4a';
            sub.textContent = 'Попробуйте ещё раз';
        }
        overlay.style.display = 'flex';
        // Task 193: фиксируем победу в счёте лучших результатов
        msRecordResult(won, msSeconds, msCurrentDiff);
        msRenderAchievements();
    }

    // ===== Task 193: счёт достижений — лучшие результаты по времени =====
    // (ранее Task 192 хранил три последних результата). В «лучшие»
    // попадают только победы — поражение не может быть лучшим
    // результатом. Список отсортирован по времени партии (быстрее —
    // выше) и ограничен тремя записями: медленная победа, не входящая
    // в топ-3, не вытесняет более быстрые. Хранится в localStorage
    // (в тестовом репо ключ автоматически получает префикс kip8test:
    // через isolateLocalStorage). При первом запуске победы из старого
    // ключа msRecentResults (Task 192) переносятся в новый ключ
    // msBestResults, старый ключ удаляется.
    const MS_RESULTS_KEY = 'msBestResults';
    const MS_RESULTS_LEGACY_KEY = 'msRecentResults';
    const MS_RESULTS_MAX = 3;

    // Возвращает топ-3 побед по времени (лучшая — первая)
    function msLoadResults() {
        try {
            const raw = localStorage.getItem(MS_RESULTS_KEY);
            const arr = raw ? JSON.parse(raw) : [];
            if (!Array.isArray(arr)) return [];
            return arr
                .filter(function (r) { return r && r.won && typeof r.time === 'number'; })
                .sort(function (a, b) { return a.time - b.time || (a.ts || 0) - (b.ts || 0); })
                .slice(0, MS_RESULTS_MAX);
        } catch (e) { return []; }
    }

    // Сохраняет только победы, отсортированные по времени, максимум 3
    function msSaveResults(arr) {
        try {
            const wins = (Array.isArray(arr) ? arr : [])
                .filter(function (r) { return r && r.won && typeof r.time === 'number'; })
                .sort(function (a, b) { return a.time - b.time || (a.ts || 0) - (b.ts || 0); })
                .slice(0, MS_RESULTS_MAX);
            localStorage.setItem(MS_RESULTS_KEY, JSON.stringify(wins));
        } catch (e) { /* приватный режим — счёт просто не сохранится */ }
    }

    // Записывает завершённую партию. В топ попадают только победы —
    // чем меньше время, тем выше место. Возвращает итоговый список.
    function msRecordResult(won, seconds, diff) {
        const arr = msLoadResults();
        if (won) {
            arr.push({
                won: true,
                time: Math.max(0, seconds | 0),
                diff: msDifficulties[diff] ? diff : msCurrentDiff,
                ts: Date.now()
            });
        }
        msSaveResults(arr);
        return msLoadResults();
    }

    // Task 193: разовая миграция — переносит победы из старого ключа
    // «последних результатов» (Task 192) в новый «лучших результатов»
    // и удаляет старый ключ. Поражения не переносятся; существующий
    // новый счёт не затирается. Вызывается из msInit().
    function msMigrateResults() {
        try {
            const legacyRaw = localStorage.getItem(MS_RESULTS_LEGACY_KEY);
            if (legacyRaw === null) return;
            let legacy = [];
            try { legacy = JSON.parse(legacyRaw) || []; } catch (e) { legacy = []; }
            if (!Array.isArray(legacy)) legacy = [];
            const wins = legacy.filter(function (r) {
                return r && r.won && typeof r.time === 'number';
            });
            if (wins.length && localStorage.getItem(MS_RESULTS_KEY) === null) {
                msSaveResults(wins);
            }
            localStorage.removeItem(MS_RESULTS_LEGACY_KEY);
        } catch (e) { /* миграция не критична */ }
    }

    // Рендер счёта: 3 слота — лучшие победы по времени (🥇🥈🥉),
    // пустые слоты приглушены. Бейдж — рекордное время.
    function msRenderAchievements() {
        const row = document.getElementById('msAchRow');
        if (!row) return;
        const results = msLoadResults();
        const medals = ['🥇', '🥈', '🥉'];
        const score = document.getElementById('msAchScore');
        if (score) {
            if (results.length) {
                score.textContent = 'рекорд ' + results[0].time + ' с';
                score.style.display = '';
            } else {
                score.style.display = 'none';
            }
        }
        let html = '';
        for (let i = 0; i < MS_RESULTS_MAX; i++) {
            const r = results[i];
            if (r) {
                html += '<div class="ms-ach-slot win">' +
                    '<span class="ms-ach-icon">' + medals[i] + '</span>' +
                    '<span class="ms-ach-diff">' + msDiffLabel(r.diff) + '</span>' +
                    '<span class="ms-ach-time">' + r.time + ' с</span></div>';
            } else {
                html += '<div class="ms-ach-slot empty">' +
                    '<span class="ms-ach-icon">·</span>' +
                    '<span class="ms-ach-diff">—</span>' +
                    '<span class="ms-ach-time">—</span></div>';
            }
        }
        row.innerHTML = html;
    }

    // ===== СЕКРЕТНЫЕ КНОПКИ (САПЁР + ТЕЛЕФОННЫЙ СПРАВОЧНИК) =====
    let secretTapCount = 0;
    let secretTapTimer = null;
    const SECRET_TAP_THRESHOLD = 2;
    let secretTouchHandled = false;
    const SECRET_BUTTON_IDS = ['minesweeperBtn', 'phonebookBtn'];
    function secretTapHandler() {
        secretTapCount++;
        document.querySelector('.header-title').classList.add('hint-pulse');
        setTimeout(() => document.querySelector('.header-title').classList.remove('hint-pulse'), 200);
        clearTimeout(secretTapTimer);
        secretTapTimer = setTimeout(() => { secretTapCount = 0; }, 1500);
        if (secretTapCount >= SECRET_TAP_THRESHOLD) {
            secretTapCount = 0;
            clearTimeout(secretTapTimer);
            // Все секретные кнопки открываются одним жестом (toggle)
            const firstBtn = document.getElementById(SECRET_BUTTON_IDS[0]);
            const willReveal = !firstBtn.classList.contains('revealed');
            SECRET_BUTTON_IDS.forEach(id => {
                const btn = document.getElementById(id);
                if (!btn) return;
                if (willReveal) {
                    btn.classList.add('revealed');
                } else {
                    btn.classList.remove('revealed');
                }
            });
            if (navigator.vibrate) {
                navigator.vibrate(willReveal ? [50,50,100] : [30,30,30]);
            }
            if (willReveal && firstBtn) {
                firstBtn.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    }
    // Register both touch and click for the header title
    (function() {
        let headerEl = document.querySelector('.header-title');
        if (!headerEl) return;
        let touchFired = false;
        headerEl.addEventListener('touchend', function(e) {
            touchFired = true;
            secretTapHandler();
            e.preventDefault();
        });
        headerEl.addEventListener('click', function() {
            if (touchFired) { touchFired = false; return; }
            secretTapHandler();
        });
    })();

    // ===== Десктоп-бренд в верхнем баре: 1 тап = на главную, 2 тапа = секретные разделы =====
    // Task 159 (v426): заменили логотип+текст на LED-кнопку как в мобильной версии
    (function() {
        let brandEl = document.getElementById('desktopBrandBtn');
        if (!brandEl) return;
        let tapCount = 0;
        let tapTimer = null;
        let touchFired = false;
        const TAP_DELAY = 300; // мс окно для двойного тапа

        function handleBrandTap() {
            tapCount++;
            // Визуальная обратная связь (как в мобильной версии)
            brandEl.classList.add('hint-pulse');
            setTimeout(() => brandEl.classList.remove('hint-pulse'), 200);
            clearTimeout(tapTimer);

            if (tapCount >= 2) {
                // Двойной тап → открыть секретные разделы
                tapCount = 0;
                clearTimeout(tapTimer);
                secretTapHandler();
            } else {
                // Одиночный тап → отложенный переход на главную (даём шанс на 2-й тап)
                tapTimer = setTimeout(() => {
                    tapCount = 0;
                    navigateTo('dashboard');
                }, TAP_DELAY);
            }
        }

        brandEl.addEventListener('touchend', function(e) {
            touchFired = true;
            handleBrandTap();
            e.preventDefault();
        });
        brandEl.addEventListener('click', function(e) {
            if (touchFired) { touchFired = false; return; }
            handleBrandTap();
        });
        // Клавиатурная доступность: Enter/Space = одиночный тап (на главную)
        brandEl.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                navigateTo('dashboard');
            }
        });
    })();

    // ===== ТЕЛЕФОННЫЙ СПРАВОЧНИК (ООО ПО "ТОКЕМ") =====
    let pbData = null;          // распарсенный JSON
    let pbFlat = [];            // плоский массив: {section, position, name, phone}
    let pbLoaded = false;

    // === Избранные контакты и пользовательские примечания ===
    // Хранение в localStorage. ID контакта = section + '|' + name + '|' + phone
    // (уникален в пределах справочника).
    let pbFavorites = {};       // {id: true}
    let pbNotes = {};           // {id: "текст примечания"}
    let pbFilterFavOnly = false; // показывать только избранные

    const PB_FAV_KEY = 'kip8test_phonebook_favorites';
    const PB_NOTES_KEY = 'kip8test_phonebook_notes';

    function pbMakeId(item) {
        // ID строится из header + group + subgroup + position + name + phone для уникальности.
        return (item.header || '') + '|' + (item.group || '') + '|' + (item.subgroup || '') + '|' +
               (item.position || '') + '|' + (item.name || '') + '|' + (item.phone || '');
    }
    function pbLoadFavorites() {
        try {
            const raw = localStorage.getItem(PB_FAV_KEY);
            pbFavorites = raw ? JSON.parse(raw) : {};
        } catch (e) { pbFavorites = {}; }
    }
    function pbSaveFavorites() {
        try { localStorage.setItem(PB_FAV_KEY, JSON.stringify(pbFavorites)); } catch (e) {}
    }
    function pbLoadNotes() {
        try {
            const raw = localStorage.getItem(PB_NOTES_KEY);
            pbNotes = raw ? JSON.parse(raw) : {};
        } catch (e) { pbNotes = {}; }
    }
    function pbSaveNotes() {
        try { localStorage.setItem(PB_NOTES_KEY, JSON.stringify(pbNotes)); } catch (e) {}
    }
    function pbIsFavorite(id) {
        return pbFavorites[id] === true;
    }
    function pbGetNote(id) {
        return pbNotes[id] || '';
    }
    function pbGetFavoritesCount() {
        return Object.keys(pbFavorites).filter(k => pbFavorites[k] === true).length;
    }

    // Очистка "фантомных" записей в избранном и примечаниях.
    // При изменении структуры pbMakeId (например, при добавлении поля subgroup)
    // старые ключи в localStorage больше не соответствуют реальным контактам.
    // Эта функция удаляет все записи, ID которых не найден в pbFlat,
    // и сохраняет очищенные данные обратно в localStorage.
    // Возвращает количество удалённых записей.
    function pbCleanupStaleFavorites() {
        if (!pbFlat || pbFlat.length === 0) return { fav: 0, notes: 0 };
        // Построить множество валидных ID
        const validIds = new Set(pbFlat.map(item => pbMakeId(item)));
        let favRemoved = 0;
        let notesRemoved = 0;
        // Очистить pbFavorites
        for (const key of Object.keys(pbFavorites)) {
            if (!validIds.has(key)) {
                delete pbFavorites[key];
                favRemoved++;
            }
        }
        // Очистить pbNotes
        for (const key of Object.keys(pbNotes)) {
            if (!validIds.has(key)) {
                delete pbNotes[key];
                notesRemoved++;
            }
        }
        // Сохранить обратно, если что-то изменилось
        if (favRemoved > 0) pbSaveFavorites();
        if (notesRemoved > 0) pbSaveNotes();
        if (favRemoved > 0 || notesRemoved > 0) {
            console.log('[phonebook] Очистка устаревших записей: избранное −' + favRemoved + ', примечания −' + notesRemoved);
        }
        return { fav: favRemoved, notes: notesRemoved };
    }

    // Нормализация строки для сравнения (lowercase, без лишних пробелов)
    function pbNorm(s) {
        return (s || '').toString().toLowerCase().replace(/\s+/g, ' ').trim();
    }
    // Экранирование HTML
    function pbEsc(s) {
        return (s || '').toString()
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }
    // Подсветка совпадения: обёртывает все вхождения query в <mark>
    function pbMark(text, query) {
        const safe = pbEsc(text);
        if (!query) return safe;
        const q = pbNorm(query);
        if (!q) return safe;
        // Экранируем query для RegExp
        const qEsc = q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        // Сравниваем по нормализованной строке, но сохраняем оригинальный регистр
        const normText = (text || '').toString();
        const regex = new RegExp(qEsc, 'gi');
        let result = '';
        let lastIdx = 0;
        let m;
        while ((m = regex.exec(normText)) !== null) {
            const start = m.index;
            const end = start + m[0].length;
            // Экранируем кусок до совпадения
            result += pbEsc(normText.slice(lastIdx, start));
            // Совпадение — в <mark>
            result += '<mark>' + pbEsc(normText.slice(start, end)) + '</mark>';
            lastIdx = end;
            // Защита от зацикливания при пустом match
            if (m.index === regex.lastIndex) regex.lastIndex++;
        }
        result += pbEsc(normText.slice(lastIdx));
        return result;
    }

    // Версия кэша phonebook в localStorage. При изменении структуры данных —
    // инкрементировать, чтобы старый кэш автоматически сбросился.
    const PB_CACHE_VERSION = 'v3-header-group-subgroup';

    async function pbLoad() {
        if (pbLoaded) return pbData;
        try {
            // Сначала пытаемся загрузить свежие данные из сети (NetworkFirst).
            // Cache-busting: ?v=timestamp обходит HTTP-кэш и SW Cache.
            // cache: 'no-store' — гарантированно не используем HTTP-кэш браузера.
            const bust = '?v=' + Date.now();
            const resp = await fetch('data/phonebook.json' + bust, { cache: 'no-store' });
            if (!resp.ok) throw new Error('HTTP ' + resp.status);
            pbData = await resp.json();
            // Сохраняем в localStorage как резервный кэш для офлайна
            try {
                localStorage.setItem('kip8test_phonebook_cache', JSON.stringify(pbData));
            } catch (e) {}
            pbFlatten();
            pbLoaded = true;
            return pbData;
        } catch (e) {
            console.warn('Phonebook load from network failed, trying cache:', e);
            // Офлайн — берём из localStorage
            try {
                const cached = localStorage.getItem('kip8test_phonebook_cache');
                if (cached) {
                    pbData = JSON.parse(cached);
                    pbFlatten();
                    pbLoaded = true;
                    console.log('[phonebook] Используется кэш localStorage (офлайн)');
                    return pbData;
                }
            } catch (e2) {}
            return null;
        }
    }

    function pbFlatten() {
        pbFlat = [];
        if (!pbData || !pbData.sections) return;
        for (const header of Object.keys(pbData.sections)) {
            for (const item of pbData.sections[header]) {
                pbFlat.push({
                    header: header,
                    group: item.group || null,
                    subgroup: item.subgroup || null,
                    position: item.position || '',
                    name: item.name || '',
                    phone: item.phone || '',
                });
            }
        }
    }

    function pbRender() {
        const list = document.getElementById('pbList');
        const info = document.getElementById('pbInfo');
        if (!list || !info) return;

        const query = pbNorm((document.getElementById('pbSearchInput')?.value || '').trim());

        // Обновить счётчик на кнопке фильтра
        pbUpdateFilterButton();

        if (!pbLoaded) {
            list.innerHTML = '';
            info.textContent = 'Загрузка…';
            return;
        }

        // Фильтрация: по поиску + по избранным (если включён фильтр)
        let filtered = pbFlat.slice();
        if (pbFilterFavOnly) {
            filtered = filtered.filter(item => pbIsFavorite(pbMakeId(item)));
        }
        if (query) {
            filtered = filtered.filter(item =>
                pbNorm(item.name).includes(query) ||
                pbNorm(item.position).includes(query) ||
                pbNorm(item.phone).includes(query) ||
                pbNorm(item.header).includes(query) ||
                (item.group && pbNorm(item.group).includes(query)) ||
                (item.subgroup && pbNorm(item.subgroup).includes(query))
            );
        }

        // Группировка по header'ам (верхний уровень) с сохранением порядка
        const groupedByHeader = {};
        for (const item of filtered) {
            if (!groupedByHeader[item.header]) groupedByHeader[item.header] = [];
            groupedByHeader[item.header].push(item);
        }

        // Инфо
        let infoParts = [];
        const headerCount = Object.keys(groupedByHeader).length;
        if (pbFilterFavOnly) {
            infoParts.push('Избранные: ' + filtered.length + ' ' + pbPlural(filtered.length, ['запись', 'записи', 'записей']));
        } else if (query) {
            infoParts.push('Найдено: ' + filtered.length + ' ' + pbPlural(filtered.length, ['запись', 'записи', 'записей']) +
                           ' в ' + headerCount + ' ' + pbPlural(headerCount, ['организации', 'организациях', 'организациях']));
        } else {
            infoParts.push('Всего: ' + pbFlat.length + ' ' + pbPlural(pbFlat.length, ['запись', 'записи', 'записей']) +
                           ' · ' + Object.keys(pbData.sections).length + ' организаций');
            const favCount = pbGetFavoritesCount();
            if (favCount > 0) {
                infoParts.push(' · избранное: ' + favCount);
            } else {
                infoParts.push(' · тапните по организации или отделу, чтобы раскрыть');
            }
        }
        info.textContent = infoParts.join('');

        // Режим: есть поисковый запрос ИЛИ фильтр избранных → все секции раскрыты
        const forceExpand = query || pbFilterFavOnly;
        if (forceExpand) {
            list.classList.add('searching');
        } else {
            list.classList.remove('searching');
        }

        // Рендер
        if (filtered.length === 0) {
            if (pbFilterFavOnly && !query) {
                list.innerHTML = '<div class="pb-empty">Нет избранных контактов.<br>Нажмите на ★ рядом с контактом, чтобы добавить его сюда.</div>';
            } else {
                list.innerHTML = '<div class="pb-empty">Ничего не найдено.<br>Попробуйте изменить запрос.</div>';
            }
            return;
        }

        let html = '';
        for (const header of Object.keys(pbData.sections)) {
            if (!groupedByHeader[header] || groupedByHeader[header].length === 0) continue;
            const items = groupedByHeader[header];
            const count = items.length;

            // В режиме поиска/фильтра — секция раскрыта. Иначе — сохраняем состояние.
            const isExpanded = forceExpand ? true : (pbExpandedSections[header] === true);
            html += '<div class="pb-section' + (isExpanded ? ' expanded' : '') + '" data-section="' + pbEsc(header) + '">';
            html += '<div class="pb-section-title" onclick="pbToggleSection(this)">';
            html += '<span class="pb-section-title-text">' + pbMark(header, query) + '</span>';
            html += '<span class="pb-section-title-count">' + count + '</span>';
            html += '<span class="pb-section-arrow"></span>';
            html += '</div>';
            html += '<div class="pb-section-body">';

            // Внутри секции — группировка по group (второй уровень) с сохранением порядка
            const groupedByGroup = {};
            const groupOrder = [];
            for (const item of items) {
                const g = item.group || null;
                if (!(g in groupedByGroup)) {
                    groupedByGroup[g] = [];
                    groupOrder.push(g);
                }
                groupedByGroup[g].push(item);
            }
            // Сортируем группы по алфавиту (null — в конце)
            groupOrder.sort((a, b) => {
                if (a === null) return 1;
                if (b === null) return -1;
                const va = a.toString().toLowerCase();
                const vb = b.toString().toLowerCase();
                if (va < vb) return -1;
                if (va > vb) return 1;
                return 0;
            });

            // Показываем подзаголовки групп, если есть хотя бы одна именованная группа
            const hasAnyNamedGroup = groupOrder.some(g => g !== null);
            const showGroupHeaders = groupOrder.length > 1 || hasAnyNamedGroup;

            // Глобальный счётчик карточек для зебра-фона
            let cardIndex = 0;

            for (const g of groupOrder) {
                if (showGroupHeaders) {
                    const groupLabel = g === null ? 'Без группы' : g;
                    const groupCount = groupedByGroup[g].length;
                    // Сворачиваемая подгруппа: data-subgroup = header + '|' + group
                    const subgroupKey = header + '|' + (g === null ? '' : g);
                    const sgExpanded = forceExpand ? true : (pbExpandedSubgroups[subgroupKey] === true);
                    html += '<div class="pb-subgroup' + (sgExpanded ? ' expanded' : '') + '" data-subgroup="' + pbEsc(subgroupKey) + '">';
                    html += '<div class="pb-subgroup-title" onclick="pbToggleSubgroup(this)">';
                    html += '<span class="pb-subgroup-title-text">' + pbMark(groupLabel, query) + '</span>';
                    html += '<span class="pb-subgroup-count">' + groupCount + '</span>';
                    html += '<span class="pb-subgroup-arrow"></span>';
                    html += '</div>';
                    html += '<div class="pb-subgroup-body">';
                }

                // Внутри группы — группировка по subgroup (третий уровень)
                const groupedBySubgroup = {};
                const subgroupOrder = [];
                for (const item of groupedByGroup[g]) {
                    const sg = item.subgroup || null;
                    if (!(sg in groupedBySubgroup)) {
                        groupedBySubgroup[sg] = [];
                        subgroupOrder.push(sg);
                    }
                    groupedBySubgroup[sg].push(item);
                }

                const hasAnySubgroup = subgroupOrder.some(sg => sg !== null);
                const showSubgroupHeaders = subgroupOrder.length > 1 || hasAnySubgroup;

                for (const sg of subgroupOrder) {
                    if (showSubgroupHeaders && sg !== null) {
                        const sgCount = groupedBySubgroup[sg].length;
                        html += '<div class="pb-subsubgroup">';
                        html += '<div class="pb-subsubgroup-title">' + pbMark(sg, query) +
                                '<span class="pb-subsubgroup-count">' + sgCount + '</span></div>';
                        html += '<div class="pb-subsubgroup-body">';
                    }
                    for (const item of groupedBySubgroup[sg]) {
                        const id = pbMakeId(item);
                        const isFav = pbIsFavorite(id);
                        const note = pbGetNote(id);
                        // Зебра: чётная/нечётная карточка
                        const zebraClass = (cardIndex % 2 === 0) ? ' pb-card-even' : ' pb-card-odd';
                        cardIndex++;
                        html += '<div class="pb-card' + zebraClass + '" data-id="' + pbEsc(id) + '">';
                        html += '<div class="pb-card-top">';
                        html += '<div class="pb-card-top-text">';
                        if (item.name) {
                            html += '<div class="pb-card-name">' + pbMark(item.name, query) + '</div>';
                        }
                        if (item.position) {
                            html += '<div class="pb-card-pos">' + pbMark(item.position, query) + '</div>';
                        }
                        if (item.phone) {
                            html += '<div class="pb-card-phone">' + pbMark(item.phone, query) + '</div>';
                        }
                        html += '</div>'; // .pb-card-top-text
                        // Кнопка-звёздочка
                        html += '<button type="button" class="pb-fav-btn' + (isFav ? ' fav-active' : '') + '" ' +
                                'aria-label="' + (isFav ? 'Убрать из избранного' : 'Добавить в избранное') + '" ' +
                                'onclick="pbToggleFavorite(this, event)">' +
                                '<svg viewBox="0 0 24 24" fill="' + (isFav ? 'currentColor' : 'none') + '" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg>' +
                                '</button>';
                        html += '</div>'; // .pb-card-top
                        // Примечание (если есть) — с кнопкой редактирования
                        if (note) {
                            html += '<div class="pb-note">' + pbEsc(note) +
                                    '<button type="button" class="pb-note-edit" aria-label="Редактировать примечание" onclick="pbEditNote(this)">' +
                                    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>' +
                                    '</button></div>';
                        } else {
                            html += '<button type="button" class="pb-note-add" onclick="pbEditNote(this)">' +
                                    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>' +
                                    'добавить примечание</button>';
                        }
                        html += '</div>'; // .pb-card
                    }
                    if (showSubgroupHeaders && sg !== null) {
                        html += '</div>'; // .pb-subsubgroup-body
                        html += '</div>'; // .pb-subsubgroup
                    }
                }

                if (showGroupHeaders) {
                    html += '</div>'; // .pb-subgroup-body
                    html += '</div>'; // .pb-subgroup
                }
            }
            html += '</div>'; // .pb-section-body
            html += '</div>'; // .pb-section
        }
        list.innerHTML = html;
    }

    // Обновить состояние кнопки "Только избранные" и счётчик
    function pbUpdateFilterButton() {
        const btn = document.getElementById('pbFilterFav');
        const label = document.getElementById('pbFilterFavLabel');
        if (!btn || !label) return;
        if (pbFilterFavOnly) {
            btn.classList.add('active');
        } else {
            btn.classList.remove('active');
        }
        const count = pbGetFavoritesCount();
        label.textContent = 'Избранные' + (count > 0 ? ': ' + count : '');
    }

    // Переключить фильтр "только избранные"
    function pbToggleFavFilter() {
        pbFilterFavOnly = !pbFilterFavOnly;
        if (navigator.vibrate) navigator.vibrate(25);
        // Сбросить раскрытые секции — в режиме фильтра они раскрываются автоматически
        pbExpandedSections = {};
        pbRender();
    }

    // Переключить избранное у контакта
    function pbToggleFavorite(btnEl, ev) {
        if (ev) { ev.stopPropagation(); ev.preventDefault(); }
        const card = btnEl.closest('.pb-card');
        if (!card) return;
        const id = card.getAttribute('data-id');
        if (!id) return;
        if (pbIsFavorite(id)) {
            delete pbFavorites[id];
            btnEl.classList.remove('fav-active');
            btnEl.setAttribute('aria-label', 'Добавить в избранное');
            // Убрать заливку звёздочки
            const svg = btnEl.querySelector('svg path');
            if (svg) svg.setAttribute('fill', 'none');
            if (navigator.vibrate) navigator.vibrate(20);
        } else {
            pbFavorites[id] = true;
            btnEl.classList.add('fav-active');
            btnEl.setAttribute('aria-label', 'Убрать из избранного');
            const svg = btnEl.querySelector('svg path');
            if (svg) svg.setAttribute('fill', 'currentColor');
            if (navigator.vibrate) navigator.vibrate([20, 30, 40]);
        }
        pbSaveFavorites();
        // Если включён фильтр избранных — пере-рендер (карточка может исчезнуть)
        if (pbFilterFavOnly) {
            pbRender();
        } else {
            pbUpdateFilterButton();
            // Обновить инфо-строку (там показывается счётчик избранного)
            pbRender();
        }
    }

    // Редактировать примечание (через prompt)
    function pbEditNote(btnEl) {
        const card = btnEl.closest('.pb-card');
        if (!card) return;
        const id = card.getAttribute('data-id');
        if (!id) return;
        const currentNote = pbGetNote(id);
        const newName = card.querySelector('.pb-card-name')?.textContent || 'этот контакт';
        const promptText = 'Примечание для: ' + newName + '\n\n(оставьте пустым, чтобы удалить)';
        kipPrompt(promptText, currentNote).then(function(newNote) {
            // null = отмена
            if (newNote === null) return;
            const trimmed = newNote.trim();
            if (trimmed) {
                pbNotes[id] = trimmed;
            } else {
                delete pbNotes[id];
            }
            pbSaveNotes();
            if (navigator.vibrate) navigator.vibrate(25);
            // Пере-рендер карточки (или всего списка — проще)
            pbRender();
        });
    }

    // Состояние раскрытых секций в обычном режиме (без поиска).
    // Хранит {sectionName: true}. При открытии новой — предыдущая закрывается.
    let pbExpandedSections = {};

    // Вспомогательная функция: прокрутить элемент к верхней части экрана,
    // учитывая высоту sticky-блока поиска (чтобы заголовок не перекрывался).
    function pbScrollToTop(el) {
        if (!el) return;
        const searchWrap = document.querySelector('.pb-search-wrap');
        const stickyHeight = searchWrap ? searchWrap.getBoundingClientRect().height : 0;
        const rect = el.getBoundingClientRect();
        // Текущая позиция прокрутки + смещение элемента от верха viewport - высота sticky - маленький отступ
        const targetY = window.scrollY + rect.top - stickyHeight - 8;
        window.scrollTo({ top: Math.max(0, targetY), behavior: 'auto' });
    }

    // Отложенная прокрутка с корректировкой после завершения анимации.
    // Анимация max-height длится ~400ms. Если прокрутить слишком рано,
    // позиция "уплывёт", потому что контент ещё растёт.
    // Стратегия:
    //   1. Мгновенная прокрутка через 2 кадра (requestAnimationFrame × 2) —
    //      убирает резкий скачок, позиция примерно правильная.
    //   2. Повторная корректировка через 450ms — после завершения анимации,
    //      когда финальная высота стабильна.
    function pbScrollToTopDelayed(el) {
        if (!el) return;
        // 1-я прокрутка: быстро, чтобы убрать скачок
        requestAnimationFrame(() => {
            requestAnimationFrame(() => {
                pbScrollToTop(el);
            });
        });
        // 2-я прокрутка: после завершения анимации max-height (0.4s = 400ms)
        setTimeout(() => {
            pbScrollToTop(el);
        }, 450);
    }

    // Обработчик клика по заголовку секции (аккордеон).
    function pbToggleSection(titleEl) {
        const list = document.getElementById('pbList');
        // В режиме поиска секции не сворачиваются (все раскрыты автоматически)
        if (list && list.classList.contains('searching')) return;

        const section = titleEl.closest('.pb-section');
        if (!section) return;
        const secName = section.getAttribute('data-section');
        if (!secName) return;

        const isExpanded = section.classList.contains('expanded');

        if (isExpanded) {
            // Закрыть текущую
            section.classList.remove('expanded');
            delete pbExpandedSections[secName];
            if (navigator.vibrate) navigator.vibrate(20);
        } else {
            // Закрыть ВСЕ остальные (аккордеон — только одна открытая)
            list.querySelectorAll('.pb-section.expanded').forEach(s => {
                s.classList.remove('expanded');
                const name = s.getAttribute('data-section');
                if (name) delete pbExpandedSections[name];
            });
            // Раскрыть текущую
            section.classList.add('expanded');
            pbExpandedSections[secName] = true;
            if (navigator.vibrate) navigator.vibrate(30);
            // Прокрутить заголовок секции к верхней части экрана.
            // Используем отложенную прокрутку с корректировкой после анимации.
            pbScrollToTopDelayed(section);
        }
    }

    // Состояние раскрытых подгрупп (второй уровень) в обычном режиме.
    // Ключ = header + '|' + group. Аккордеон: только одна открытая в пределах секции.
    let pbExpandedSubgroups = {};

    // Обработчик клика по заголовку подгруппы (второй уровень, аккордеон).
    function pbToggleSubgroup(titleEl) {
        const list = document.getElementById('pbList');
        // В режиме поиска подгруппы не сворачиваются (все раскрыты автоматически)
        if (list && list.classList.contains('searching')) return;

        const subgroup = titleEl.closest('.pb-subgroup');
        if (!subgroup) return;
        const sgKey = subgroup.getAttribute('data-subgroup');
        if (!sgKey) return;

        // Найти родительскую секцию, чтобы закрыть другие подгруппы только в её пределах
        const section = subgroup.closest('.pb-section');
        if (!section) return;

        const isExpanded = subgroup.classList.contains('expanded');

        if (isExpanded) {
            // Закрыть текущую
            subgroup.classList.remove('expanded');
            delete pbExpandedSubgroups[sgKey];
            if (navigator.vibrate) navigator.vibrate(15);
        } else {
            // Аккордеон: закрыть ВСЕ остальные подгруппы ВНУТРИ этой же секции
            section.querySelectorAll('.pb-subgroup.expanded').forEach(s => {
                s.classList.remove('expanded');
                const k = s.getAttribute('data-subgroup');
                if (k) delete pbExpandedSubgroups[k];
            });
            // Раскрыть текущую
            subgroup.classList.add('expanded');
            pbExpandedSubgroups[sgKey] = true;
            if (navigator.vibrate) navigator.vibrate(25);
            // Прокрутить заголовок подгруппы к верхней части экрана.
            // Используем отложенную прокрутку с корректировкой после анимации.
            pbScrollToTopDelayed(subgroup);
        }
    }

    // Простая функция плюарализации для русского языка
    function pbPlural(n, forms) {
        const n10 = n % 10;
        const n100 = n % 100;
        if (n10 === 1 && n100 !== 11) return forms[0];
        if (n10 >= 2 && n10 <= 4 && (n100 < 10 || n100 >= 20)) return forms[1];
        return forms[2];
    }

    // Инициализация при первом открытии страницы контактов
    function pbInit() {
        // Загрузить избранное и примечания из localStorage (всегда)
        pbLoadFavorites();
        pbLoadNotes();
        // Всегда перезагружаем данные из сети (cache-busting в pbLoad),
        // чтобы увидеть изменения из таблицы Google Sheets.
        // Очистка устаревших избранного будет выполнена после загрузки.
        pbLoaded = false;
        pbData = null;
        pbFlat = [];
        pbLoad().then(() => {
            // После загрузки данных — очистить устаревшие записи (старые ID
            // от предыдущих версий pbMakeId, которые больше не валидны)
            pbCleanupStaleFavorites();
            pbRender();
        });
    }

    // ===== ПРИБОРЫ (КИП ИОС) =====
    let devData = null;            // распарсенный JSON
    let devLoaded = false;
    let devFilterType = null;       // выбранный тип прибора (null = все)
    const DEV_CACHE_KEY = 'kip8test_devices_cache';
    const DEV_CACHE_VERSION = 'v1';
    const DEV_DEFAULT_LIMIT = 50;   // сколько карточек показывать изначально

    // Нормализация строки для поиска (без учёта регистра, лишних пробелов)
    function devNorm(s) {
        return (s || '').toString().toLowerCase().replace(/\s+/g, ' ').trim();
    }

    // ============================================================
    // Task 151: ГИБКИЙ ПОИСК (для всех списков: приборы, блокировки,
    // клапана, регуляторы, проекты)
    // Этап 1: по словам (AND) + нормализация + транслитерация
    //         (латиница <-> кириллица: «metran» находит «Метран»)
    // Этап 2: нечёткий fallback (Дамерау-Левенштейн, только если
    //         точных совпадений нет): 1 опечатка для слов >= 5 симв.,
    //         2 — для слов >= 9; расстояние считается слово-к-слову.
    // ============================================================

    // Транслитерация кириллица -> латиница (для сопоставления раскладок)
    var _TRANSLIT_RU2EN = {
        'а': 'a', 'б': 'b', 'в': 'v', 'г': 'g', 'д': 'd', 'е': 'e', 'ё': 'e',
        'ж': 'zh', 'з': 'z', 'и': 'i', 'й': 'i', 'к': 'k', 'л': 'l', 'м': 'm',
        'н': 'n', 'о': 'o', 'п': 'p', 'р': 'r', 'с': 's', 'т': 't', 'у': 'u',
        'ф': 'f', 'х': 'h', 'ц': 'c', 'ч': 'ch', 'ш': 'sh', 'щ': 'sch',
        'ъ': '', 'ы': 'y', 'ь': '', 'э': 'e', 'ю': 'yu', 'я': 'ya'
    };
    var _TRANSLIT_EN2RU = {
        'a': 'а', 'b': 'б', 'c': 'ц', 'd': 'д', 'e': 'е', 'f': 'ф', 'g': 'г',
        'h': 'х', 'i': 'и', 'j': 'й', 'k': 'к', 'l': 'л', 'm': 'м', 'n': 'н',
        'o': 'о', 'p': 'п', 'q': 'к', 'r': 'р', 's': 'с', 't': 'т', 'u': 'у',
        'v': 'в', 'w': 'в', 'x': 'х', 'y': 'ы', 'z': 'з'
    };

    // Разбить строку запроса/поля на нормализованные слова:
    // нижний регистр, ё->е, НЕ-буквенно-цифровые — разделители.
    function kipSearchWords(s) {
        var t = (s == null ? '' : String(s)).toLowerCase().replace(/ё/g, 'е');
        var raw = t.split(/[^a-zа-я0-9]+/);
        var words = [];
        for (var i = 0; i < raw.length; i++) {
            var w = raw[i];
            if (!w) continue;
            words.push(w);
        }
        return words;
    }

    // Транслитерация слова (в обе стороны: пробуем ru->en и en->ru,
    // запрос сопоставляется с полем по ОБЕИМ формам)
    function kipTranslit(s, map) {
        var out = '';
        for (var i = 0; i < s.length; i++) {
            var ch = s[i];
            out += (map[ch] !== undefined) ? map[ch] : ch;
        }
        return out;
    }

    // Дамерау-Левенштейн (расстояние с перестановками соседних символов)
    function kipEditDistance(a, b) {
        var la = a.length, lb = b.length;
        if (la === 0) return lb;
        if (lb === 0) return la;
        var INF = la + lb;
        var da = {}; // последняя позиция символа в a
        var d = [];
        for (var i = 0; i <= la + 1; i++) {
            d.push(new Array(lb + 2).fill(0));
        }
        d[0][0] = INF;
        for (var i = 0; i <= la; i++) {
            d[i + 1][0] = INF;
            d[i + 1][1] = i;
        }
        for (var j = 0; j <= lb; j++) {
            d[0][j + 1] = INF;
            d[1][j + 1] = j;
        }
        for (var i = 1; i <= la; i++) {
            var db = 0;
            for (var j = 1; j <= lb; j++) {
                var k1 = da[b[j - 1]] || 0;
                var k2 = db;
                var cost = (a[i - 1] === b[j - 1]) ? 0 : 1;
                if (cost === 0) db = j;
                d[i + 1][j + 1] = Math.min(
                    d[i][j] + cost,                        // замена
                    d[i + 1][j] + 1,                       // вставка
                    d[i][j + 1] + 1,                       // удаление
                    d[k1][k2] + (i - k1 - 1) + 1 + (j - k2 - 1) // перестановка
                );
            }
            da[a[i - 1]] = i;
        }
        return d[la + 1][lb + 1];
    }

    // Порог нечёткости по длине слова (Этап 2)
    function kipFuzzyThreshold(word) {
        var len = word.length;
        if (len >= 9) return 2;
        if (len >= 5) return 1;
        return 0; // короткие слова — только точное совпадение
    }

    // Совпадает ли слово запроса со словом поля (с учётом транслита и нечёткости)
    function kipWordMatches(qw, fw, allowFuzzy) {
        // Прямое сравнение
        if (qw === fw) return true;
        // Подстрока (слово поля начинается со слова запроса или содержит его)
        if (fw.indexOf(qw) !== -1) return true;
        // Транслитерация: qw (лат) vs fw (кир) и наоборот
        var qwAsRu = kipTranslit(qw, _TRANSLIT_EN2RU);
        var qwAsEn = kipTranslit(qw, _TRANSLIT_RU2EN);
        if (qwAsRu === fw || qwAsEn === fw) return true;
        if (fw.indexOf(qwAsRu) !== -1 || fw.indexOf(qwAsEn) !== -1) return true;
        // Нечёткость (Этап 2): только для достаточно длинных слов
        if (allowFuzzy) {
            var t = kipFuzzyThreshold(qw);
            if (t > 0 && fw.length >= 4) {
                if (kipEditDistance(qw, fw) <= t) return true;
                if (kipEditDistance(qwAsRu, fw) <= t) return true;
                if (kipEditDistance(qwAsEn, fw) <= t) return true;
            }
        }
        return false;
    }

    // Сопоставление всех слов запроса со словами haystack-строки.
    // Этап 1: точное (вкл. транслит); Этап 2 — если allowFuzzy.
    // Логика AND: каждое слово запроса должно найтись в haystack.
    function kipMatchAll(query, haystack, allowFuzzy) {
        var qWords = kipSearchWords(query);
        if (qWords.length === 0) return true;
        var hWords = kipSearchWords(haystack);
        for (var qi = 0; qi < qWords.length; qi++) {
            var qw = qWords[qi];
            var found = false;
            for (var hi = 0; hi < hWords.length && !found; hi++) {
                if (kipWordMatches(qw, hWords[hi], allowFuzzy)) found = true;
            }
            if (!found) return false;
        }
        return true;
    }

    // Главная функция поиска для списков: точный этап по всем записям,
    // затем (если ничего не нашлось и запрос не пуст) — нечёткий этап.
    // fieldGetter возвращает строку для поиска по записи.
    // Оптимизация: нормализованные слова записи кэшируются на самой
    // записи (item._kipSearchWords) — нормализация выполняется один
    // раз на запись, а не при каждом нажатии клавиши и в обоих этапах.
    var _kipSearchCache = new WeakMap();
    function kipHaystackWords(item, fieldGetter) {
        var cached = _kipSearchCache.get(item);
        if (cached !== undefined) return cached;
        var words = kipSearchWords(fieldGetter(item));
        // Предвычислить транслит-формы слов поля (для сопоставления
        // латинского запроса с кириллическим полем без повторных
        // транслитераций на каждое сравнение)
        var forms = [];
        for (var i = 0; i < words.length; i++) {
            var w = words[i];
            forms.push({ w: w, ru: kipTranslit(w, _TRANSLIT_EN2RU), en: kipTranslit(w, _TRANSLIT_RU2EN) });
        }
        // Task 155: склеенная форма записи (все слова без разделителей) —
        // для устойчивости к разным форматам разделителей: «8м/1»
        // найдёт и «8 м/1», и «8м-1», и «8м 1» и т.п.
        var glued = words.join('');
        var result = { forms: forms, glued: glued };
        _kipSearchCache.set(item, result);
        return result;
    }

    // Сопоставление слов запроса с предвычисленными формами слов записи.
    // Task 155: сначала «склеенная» проверка — весь запрос без разделителей
    // содержится в склеенной форме записи. Покрывает случаи, когда разделители
    // в данных и запросе различаются («8м/1» vs «8 м/1» vs «8м-1»), а также
    // слитые запросы («8м1»). Минимум 3 символа — от ложных срабатываний.
    function kipMatchForms(qWords, data, allowFuzzy) {
        var gluedQ = qWords.join('');
        if (gluedQ.length >= 3 && data.glued && data.glued.indexOf(gluedQ) !== -1) {
            return true;
        }
        var forms = data.forms;
        for (var qi = 0; qi < qWords.length; qi++) {
            var qw = qWords[qi];
            var qwRu = kipTranslit(qw, _TRANSLIT_EN2RU);
            var qwEn = kipTranslit(qw, _TRANSLIT_RU2EN);
            var found = false;
            // Task 155: однобуквенные/однозначные слова запроса («8», «м»)
            // сопоставляем ТОЛЬКО точным равенством со словом поля —
            // подстрока даёт шум («8» матчится в «8мм», «18», «80»...).
            // Составные запросы («8 м/1») покрывает glued-форма выше.
            var shortWord = qw.length <= 1;
            for (var hi = 0; hi < forms.length && !found; hi++) {
                var f = forms[hi];
                if (f.w === qw) { found = true; break; }
                if (!shortWord && f.w.indexOf(qw) !== -1) { found = true; break; }
                if (f.w === qwRu) { found = true; break; }
                if (!shortWord && f.w.indexOf(qwRu) !== -1) { found = true; break; }
                if (f.w === qwEn) { found = true; break; }
                if (!shortWord && f.w.indexOf(qwEn) !== -1) { found = true; break; }
                if (allowFuzzy) {
                    var t = kipFuzzyThreshold(qw);
                    if (t > 0 && f.w.length >= 4) {
                        if (kipEditDistance(qw, f.w) <= t ||
                            kipEditDistance(qwRu, f.w) <= t ||
                            kipEditDistance(qwEn, f.w) <= t) { found = true; break; }
                    }
                }
            }
            if (!found) return false;
        }
        return true;
    }

    function kipSearchFilter(items, query, fieldGetter) {
        var q = (query || '').toString().trim();
        if (!q) return items;
        var qWords = kipSearchWords(q);
        if (qWords.length === 0) return items;
        // Этап 1: точный (слова + нормализация + транслит)
        var exact = [];
        var fuzzyPool = [];
        for (var i = 0; i < items.length; i++) {
            var item = items[i];
            var forms = kipHaystackWords(item, fieldGetter);
            if (kipMatchForms(qWords, forms, false)) {
                exact.push(item);
            } else {
                fuzzyPool.push(item); // кандидаты для этапа 2 (формы уже кэшированы)
            }
        }
        if (exact.length > 0) return exact;
        // Этап 2: нечёткий (опечатки) — только когда точных нет
        var fuzzy = [];
        for (var j = 0; j < fuzzyPool.length; j++) {
            var forms2 = kipHaystackWords(fuzzyPool[j], fieldGetter);
            if (kipMatchForms(qWords, forms2, true)) fuzzy.push(fuzzyPool[j]);
        }
        return fuzzy;
    }

    // Экранирование HTML
    function devEsc(s) {
        return (s || '').toString()
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    // Подсветка совпадений в тексте
    function devMark(text, query) {
        const safe = devEsc(text);
        if (!query) return safe;
        const q = devNorm(query);
        if (!q) return safe;
        const qEsc = q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const normText = (text || '').toString();
        const regex = new RegExp(qEsc, 'gi');
        let result = '';
        let lastIdx = 0;
        let m;
        while ((m = regex.exec(normText)) !== null) {
            const start = m.index;
            const end = start + m[0].length;
            result += devEsc(normText.slice(lastIdx, start));
            result += '<mark>' + devEsc(normText.slice(start, end)) + '</mark>';
            lastIdx = end;
            if (m.index === regex.lastIndex) regex.lastIndex++;
        }
        result += devEsc(normText.slice(lastIdx));
        return result;
    }

    // Поля для отображения в карточке (порядок = как в карточке)
    const DEV_FIELDS = [
        { key: 'Предел измерения', label: 'Предел измерения', group: 1 },
        { key: 'Погрешность', label: 'Погрешность', group: 1 },
        { key: '__period__', label: 'Период ремонта', isCombined: true, group: 1 },
        { key: 'Оборудование', label: 'Оборудование', group: 2 },
        { key: 'Параметр', label: 'Параметр', group: 2 },
        { key: 'Место расположения', label: 'Место расположения', group: 2 },
        { key: 'Производство', label: 'Производство', group: 2 },
        { key: 'Позиция', label: 'Позиция', group: 3 },
        { key: '№ проекта', label: '№ проекта', group: 3 },
        { key: '№ СБС', label: '№ СБС', group: 3 },
        { key: '№ САР', label: '№ САР', group: 3 },
        { key: 'В перечне', label: 'В перечне', group: 3 },
        { key: 'В гр. ППР', label: 'В гр. ППР', group: 3 },
        { key: 'Технические характеристики', label: 'Тех. характеристики', group: 4 },
        { key: 'Примечания', label: 'Примечания', group: 4 },
        { key: 'Замечания', label: 'Замечания', group: 4 },
    ];

    let devImages = {};  // не используется (base64 встроены в devices.json)

    // SVG-заставка для приборов без картинки или при загрузке
    const DEV_PLACEHOLDER_SVG = 'data:image/svg+xml,' + encodeURIComponent(
        '<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100" viewBox="0 0 100 100">' +
        '<rect width="100" height="100" rx="12" fill="rgba(199,150,74,0.06)"/>' +
        '<circle cx="50" cy="50" r="32" fill="none" stroke="rgba(199,150,74,0.35)" stroke-width="2.5"/>' +
        '<text x="50" y="56" text-anchor="middle" font-family="sans-serif" font-size="16" font-weight="700" fill="rgba(199,150,74,0.5)">КИП</text>' +
        '</svg>'
    );

    // Task 134: заглушка-иконка для строк группировки БЕЗ картинок —
    // в стиле DEV_PLACEHOLDER_SVG (круг + «КИП»), но с пропорциями
    // миниатюры группы 100x82. Единый вид всех строк: фото или заглушка,
    // размер и рамка одинаковые.
    const GROUP_PLACEHOLDER_SVG = 'data:image/svg+xml,' + encodeURIComponent(
        '<svg xmlns="http://www.w3.org/2000/svg" width="100" height="82" viewBox="0 0 100 82">' +
        '<rect width="100" height="82" rx="12" fill="rgba(199,150,74,0.07)"/>' +
        '<circle cx="50" cy="41" r="27" fill="none" stroke="rgba(199,150,74,0.35)" stroke-width="2.5"/>' +
        '<text x="50" y="47" text-anchor="middle" font-family="sans-serif" font-size="15" font-weight="700" fill="rgba(199,150,74,0.5)">КИП</text>' +
        '</svg>'
    );

    // Task 136/137: делегированный обработчик ошибок загрузки фото
    // (карточки приборов и избранное). Битое фото (офлайн без кэша)
    // подменяется заглушкой DEV_PLACEHOLDER_SVG с корректными стилями
    // (класс -ph — квадратная, без обрезки). Capture-фаза: событие error
    // не всплывает, но захватывается на document — один обработчик
    // на все изображения, без инлайн-onerror в HTML каждой карточки.
    document.addEventListener('error', function (e) {
        var img = e.target;
        if (!img || img.tagName !== 'IMG') return;
        if (!img.classList || img.dataset.phApplied) return;
        if (img.classList.contains('dev-card-image')) {
            img.dataset.phApplied = '1';
            img.classList.add('dev-card-image-ph');
            img.src = DEV_PLACEHOLDER_SVG;
        } else if (img.classList.contains('fav-card-img')) {
            img.dataset.phApplied = '1';
            img.classList.add('fav-card-img-ph');
            img.src = DEV_PLACEHOLDER_SVG;
        }
    }, true);

    // Получить URL картинки для прибора.
    // Поддерживаемые форматы поля «Изображение»:
    //   1) base64 data URI (data:image/...) — встройка из старых JSON, используется напрямую.
    //   2) Google Drive share-ссылка (https://drive.google.com/file/d/ID/view?usp=...)
    //      — конвертируется через gdriveShareToDirect() в URL превью
    //      (drive.google.com/thumbnail?id=...&sz=w800).
    //   3) Прямой HTTPS-URL картинки — используется как есть.
    //   4) Пустое значение или неизвестный формат — SVG-заставка «КИП».
    function devGetImageUrl(dev) {
        const img = (dev['Изображение'] || '').trim();
        if (!img) return DEV_PLACEHOLDER_SVG;
        if (img.startsWith('data:image/')) return img;
        if (img.startsWith('http://') || img.startsWith('https://')) {
            const gdrive = gdriveShareToDirect(img);
            if (gdrive) return gdrive.thumb;
            return img;
        }
        return DEV_PLACEHOLDER_SVG;
    }

    async function devLoad() {
        if (devLoaded) return devData;
        try {
            const bust = '?v=' + Date.now();
            const resp = await fetch('data/devices.json' + bust, { cache: 'no-store' });
            if (!resp.ok) throw new Error('HTTP ' + resp.status);
            devData = await resp.json();
            // Сохраняем в localStorage
            try {
                localStorage.setItem('kip8test:' + DEV_CACHE_KEY, JSON.stringify(devData));
            } catch (e) {}
            devLoaded = true;
            return devData;
        } catch (e) {
            console.warn('Devices load from network failed, trying cache:', e);
            try {
                const cached = localStorage.getItem('kip8test:' + DEV_CACHE_KEY);
                if (cached) {
                    devData = JSON.parse(cached);
                    devLoaded = true;
                    console.log('[devices] Используется кэш localStorage (офлайн)');
                    return devData;
                }
            } catch (e2) {}
            return null;
        }
    }

    // Состояние: сколько карточек сейчас показано (для пагинации)
    let devVisibleCount = DEV_DEFAULT_LIMIT;

    function devRender() {
        const list = document.getElementById('devList');
        const info = document.getElementById('devInfo');
        if (!list || !info) return;

        const query = devNorm((document.getElementById('devSearchInput')?.value || '').trim());

        if (!devLoaded || !devData) {
            list.innerHTML = '';
            info.textContent = 'Загрузка…';
            return;
        }

        // Фильтрация
        // Исключаем служебную запись с ID=0 (содержит дату изменения перечня)
        let filtered = devData.devices.filter(d => {
            const id = d['ID'];
            return id !== 0 && id !== '0' && String(id ?? '').trim() !== '0';
        });
        // Task 140: Фильтр 4 — скрыть приборы, у которых «В гр. ППР» = «Нет»
        // (для ролей с ограниченным доступом к КИП ИОС, например ИТР ТОКЕМ).
        // Ранее применялся только в devRenderSorted — теперь и на основной странице.
        if (typeof KipAuth !== 'undefined' && KipAuth._hasRestrictedKipIos && KipAuth._hasRestrictedKipIos()) {
            filtered = filtered.filter(d => String(d['В гр. ППР'] || '').trim().toLowerCase() !== 'нет');
        }
        if (query) {
            // Task 151: гибкий поиск (слова AND + транслит + нечёткий fallback)
           var __searchTotal = filtered.length;
             filtered = kipSearchFilter(filtered, query, function (d) {
                return DEV_FIELDS.map(f => d[f.key] || '').join(' ');
            });
        }

        // Инфо
        info.textContent = '';

        if (filtered.length === 0) {
            list.innerHTML = '<div class="pb-empty">Ничего не найдено.<br>Попробуйте изменить запрос.</div>';
            return;
        }

        // Пагинация: показываем только первые devVisibleCount карточек
        const visible = filtered.slice(0, devVisibleCount);
        const remaining = filtered.length - visible.length;

        let html = '<div class="dev-list">';
        for (const dev of visible) {
            const devId = String(dev['ID'] ?? '');
            const name = dev['Наименование'] || '(без названия)';
            const type = dev['Тип'] || '';
            const number = dev['№ прибора'] || '';
            const place = dev['Место установки'] || '';
            const imgUrl = devGetImageUrl(dev);
            const finalImgUrl = imgUrl || DEV_PLACEHOLDER_SVG;
            // Task 136: заглушке — квадратные пропорции без обрезки
            const phCls = String(dev['Изображение'] || '').trim() ? '' : ' dev-card-image-ph';

            html += '<div class="dev-card" data-dev-id="' + devEsc(devId) + '">';
            html += '<div class="dev-card-header" onclick="devOpenDetail(\'' + devEsc(devId) + '\')">';
            html += '<div class="dev-card-header-inner">';
            html += '<div class="dev-card-image-wrap">';
            html += '<img class="dev-card-image' + phCls + '" src="' + devEsc(finalImgUrl) + '" alt="' + devEsc(name) + '" loading="lazy">';
            html += KipFav._cardFavBtnHtml(devId);
            html += '<div class="dev-card-name-overlay">' + devMark(name, query) + '</div>';
            html += '</div>'; // .dev-card-image-wrap
            html += '<div class="dev-card-text">';
            html += '<div class="dev-card-title">' + devMark(name, query) + '</div>';
            let subtitle = '';
            if (type) subtitle += type;
            if (number) subtitle += (subtitle ? ' · №' : '№') + number;
            if (place) subtitle += (subtitle ? ' · ' : '') + place;
            if (subtitle) {
                html += '<div class="dev-card-subtitle">' + devMark(subtitle, query) + '</div>';
            }
            html += '</div>'; // .dev-card-text
            html += '<div class="dev-card-info-block">';
            if (type) {
                html += '<div class="dev-card-info-row">' + devMark(type, query) + '</div>';
            }
            if (number) {
                html += '<div class="dev-card-info-row" style="color:#6aa6e0;font-weight:600;">№ ' + devMark(number, query) + '</div>';
            }
            if (place) {
                html += '<div class="dev-card-info-row">' + devMark(place, query) + '</div>';
            }
            html += '</div>'; // .dev-card-info-block
            html += '</div>'; // .dev-card-header-inner
            html += '</div>'; // .dev-card-header
            html += '</div>'; // .dev-card
        }
        html += '</div>'; // .dev-list
        // Кнопка "Показать ещё"
        if (remaining > 0) {
            html += '<div style="text-align:center; padding:12px;">';
            html += '<button type="button" class="pb-filter-btn" onclick="devShowMore()" style="border-color:rgba(199,150,74,0.35); background:rgba(199,150,74,0.06); color:#c7964a;">';
            html += 'Показать ещё ' + Math.min(50, remaining) + ' (осталось ' + remaining + ')';
            html += '</button>';
            html += '</div>';
        }
        list.innerHTML = html;
        kipRenderSearchCounter(list, filtered.length, __searchTotal, query);
        if (typeof KipFav !== 'undefined') KipFav.wrapDevCardsForFavSwipe();
    }

