    function cableRenderDetailInPanel() {
        if (typeof KipCableJournal === 'undefined' || !KipCableJournal._viewing) return;
        const row = KipCableJournal._viewing;
        const columns = KipCableJournal._columns || [];
        const bodyEl = document.getElementById('detailPanelBody');
        if (!bodyEl) return;
        const cableTitle = row.designation || ('Запись №' + (row.num || '?'));
        // Порядок полей — английские ключи, как в _renderViewPage
        const order = [
            { key: 'designation',   group: 1 },
            { key: 'start',         group: 1 },
            { key: 'end',           group: 1 },
            { key: 'section',       group: 1 },
            { key: 'mark_project',  group: 2 },
            { key: 'cores_project', group: 2 },
            { key: 'length_project',group: 2 },
            { key: 'mark_actual',   group: 3 },
            { key: 'cores_actual',  group: 3 },
            { key: 'length_actual', group: 3 },
            { key: 'department',    group: 4 },
            { key: 'purpose',       group: 4 },
            { key: 'project_no',    group: 4 },
            { key: 'added_at',      group: 4 }
        ];
        // Рендерим поля кабельной записи в detail-panel
        let html = '<div class="dev-detail-card">';
        html += '<div class="ticket-detail-title" style="margin-bottom:14px;">' + devEsc(cableTitle) + '</div>';
        for (const f of order) {
            const col = columns.find(function(c) { return c.key === f.key; });
            if (!col) continue;
            const val = row[f.key];
            const raw = (val === null || val === undefined || val === '') ? '' : String(val);
            if (raw === '' || raw === 'Нет данных') continue;
            let valStr = raw;
            if (f.key === 'length_project' || f.key === 'length_actual') {
                valStr = raw + ' м';
            } else if (f.key === 'added_at') {
                valStr = KipCableJournal._formatDate(raw);
            }
            const grpCls = f.group ? ' cj-view-group-' + f.group : '';
            html += '<div class="dev-card-row' + grpCls + '">';
            html += '<div class="dev-card-label">' + devEsc(col.label) + '</div>';
            html += '<div class="dev-card-value">' + devEsc(valStr) + '</div>';
            html += '</div>';
        }
        html += '</div>';
        bodyEl.innerHTML = html;
        // Кнопки правки/удаления — в нижний бар detail-panel-footer
        const footerEl = document.getElementById('detailPanelFooter');
        if (footerEl) {
            if (KipCableJournal._canEdit) {
                footerEl.innerHTML =
                    '<button type="button" class="detail-footer-btn detail-footer-btn-edit" onclick="KipCableJournal.openEdit()">Править</button>';
            } else {
                footerEl.innerHTML = '';
            }
        }
        // Открываем панель
        const panel = document.getElementById('detailPanel');
        if (panel) panel.classList.add('active');
        // Показываем полноэкранную строку breadcrumbs
        const bcBar = document.getElementById('detailBreadcrumbBar');
        if (bcBar) bcBar.classList.add('active');
        // Task 173: обновить кнопку поиска в строке крошек
        detailBarUpdateSearchBtn();
        // Breadcrumbs в заголовке detail-панели
        setDetailBreadcrumb('cable-journal-view', cableTitle, '', '');
    }

    function toggleSidebar() {
    let sidebar = document.getElementById('sidebar');
    let overlay = document.getElementById('sidebarOverlay');
    if (isDesktop()) {
        // На десктопе: закрываем sidebar (toggle)
        if (sidebar.classList.contains('desktop-open')) {
            sidebar.classList.remove('desktop-open');
            if (overlay) overlay.classList.remove('desktop-active');
        } else {
            sidebar.classList.add('desktop-open');
            if (overlay) overlay.classList.add('desktop-active');
        }
    } else {
        // На мобильном: стандартное поведение
        sidebar.classList.toggle('active');
        overlay.classList.toggle('active');
    }
}

    /** Десктоп: сворачивание/разворачивание sidebar */
    function toggleDesktopSidebar() {
        if (!isDesktop()) return; // Защита: на мобильном не выполняется
        const sidebar = document.getElementById('sidebar');
        const overlay = document.getElementById('sidebarOverlay');
        if (!sidebar) return;
        const isOpen = sidebar.classList.contains('desktop-open');
        if (isOpen) {
            sidebar.classList.remove('desktop-open');
            if (overlay) overlay.classList.remove('desktop-active');
        } else {
            sidebar.classList.add('desktop-open');
            if (overlay) overlay.classList.add('desktop-active');
        }
        // Закрытие sidebar при клике на overlay
        if (!isOpen && overlay) {
            overlay.onclick = function() {
                sidebar.classList.remove('desktop-open');
                overlay.classList.remove('desktop-active');
            };
        }
    }

    /** Инициализация десктопного sidebar — по умолчанию скрыт */
    function initDesktopSidebar() {
        if (!isDesktop()) return;
        // Sidebar скрыт по умолчанию — ничего не делаем
        // Обновляем активную вкладку в top bar
        updateDesktopTopBarTabs();
        // Переместить connection indicator в десктопный бар
        const ci = document.getElementById('connectionIndicator');
        const barRight = document.querySelector('.desktop-top-bar-right');
        if (ci && barRight && !barRight.contains(ci)) {
            barRight.appendChild(ci);
        }
        // Клик по рабочей области (contentArea) закрывает sidebar
        const contentArea = document.getElementById('contentArea');
        if (contentArea && !contentArea._desktopSidebarCloseHandler) {
            contentArea._desktopSidebarCloseHandler = true; // флаг, чтобы не вешать дважды
            contentArea.addEventListener('click', function(e) {
                const sidebar = document.getElementById('sidebar');
                if (sidebar && sidebar.classList.contains('desktop-open')) {
                    sidebar.classList.remove('desktop-open');
                    const overlay = document.getElementById('sidebarOverlay');
                    if (overlay) overlay.classList.remove('desktop-active');
                }
            });
        }
    }

    /** Обновление активной вкладки в десктопном верхнем баре */
    function updateDesktopTopBarTabs() {
        const activePage = document.querySelector('.page-content.active');
        const currentPage = activePage ? activePage.id.replace('page-', '') : '';
        document.querySelectorAll('.desktop-top-bar-tab').forEach(tab => {
            const tabPage = tab.getAttribute('data-page');
            // Проверяем, является ли текущая страница подразделом этой вкладки
            let isActive = false;
            if (tabPage === 'calculators') {
                isActive = ['calculators', 'calc-kipa', 'calc-electro', 'calc-geometry',
                    'converter', 'scale-signal', 'error-select', 'buoy-select',
                    'temp-sensors', 'temp-sensor-view', 'orifice-select', 'circuit-breaker',
                    'geo-circle', 'geo-ring', 'geo-cylinder', 'geo-horiz',
                    'geo-sphere', 'geo-cone'].includes(currentPage);
            } else if (tabPage === 'docs') {
                isActive = ['docs', 'devices-prod', 'devices-type', 'devices-name',
                    'device-detail', 'dev-group', 'lockouts-prod', 'lockout-detail',
                    'lock-group', 'valves-prod', 'valve-detail', 'valve-group',
                    'regulators-prod', 'regulator-detail', 'regulator-group',
                    'projects-prod', 'projects-status', 'project-detail', 'project-group', // Task 369
                    'cable-journal-edit', 'cable-journal-add', 'cable-journal-view',
                    'kip-ios', 'library-internal', 'library-electro',
                    'plan-114', 'exam-tickets', 'admin-users', 'admin-sessions',
                    'admin-logs', 'admin-stats'].includes(currentPage);
            }
            tab.classList.toggle('active', isActive);
        });
    }

// Аккордеон в боковом меню: при разворачивании группы — сворачиваем ранее раскрытую.
// Заголовок группы (title + count + arrow) сам является тогглером.
function toggleSidebarGroup(groupEl) {
    if (!groupEl) return;
    const isExpanded = groupEl.classList.contains('expanded');
    // Аккордеон: сворачиваем все остальные раскрытые группы
    document.querySelectorAll('.sidebar-group.expanded').forEach(el => {
        if (el !== groupEl) {
            el.classList.remove('expanded');
        }
    });
    // Тогглим текущую группу
    groupEl.classList.toggle('expanded', !isExpanded);
    // Вибрация для тактильного отклика
    if (navigator.vibrate) navigator.vibrate(15);
}

// Close sidebar when clicking outside
document.addEventListener('click', function(e) {
    let sidebar = document.getElementById('sidebar');
    let overlay = document.getElementById('sidebarOverlay');
    let menuBtn = document.getElementById('menuBtn');
    if (!sidebar || !overlay) return;
    if (sidebar.classList.contains('active')) {
        let clickedSidebar = sidebar.contains(e.target);
        let clickedMenuBtn = menuBtn && menuBtn.contains(e.target);
        if (!clickedSidebar && !clickedMenuBtn) {
            sidebar.classList.remove('active');
            overlay.classList.remove('active');
        }
    }
});

function showToast(msg, actionText, actionFn) {
    let t = document.getElementById('toast');
    let m = document.getElementById('toastMessage');
    let a = document.getElementById('toastAction');
    m.textContent = msg;
    if (actionText && actionFn) {
        a.textContent = actionText;
        a.style.display = 'inline';
        a.onclick = function() { t.classList.remove('show'); a.style.display = 'none'; a.onclick = null; actionFn(); };
    } else {
        a.style.display = 'none';
        a.onclick = null;
    }
    t.classList.add('show');
    if (navigator.vibrate) navigator.vibrate(50);
    clearTimeout(t._hideTimer);
    t._hideTimer = setTimeout(() => { t.classList.remove('show'); a.style.display = 'none'; a.onclick = null; }, 3000);
}

// ============================================================
// KipToast — алиас showToast (Task 282)
// ============================================================
// В коде модулей (WorkSchedule, Flowmeter, CableJournal) сообщения
// обратной связи исторически вызываются через KipToast.show(...)
// под guard'ами «typeof KipToast !== 'undefined'». До Task 282
// KipToast НИГДЕ не был определён — все ~100 вызовов молча
// подавлялись: ни ошибок валидации форм («Выберите сотрудника»),
// ни ошибок сервера («overlap», «sheet_not_found»), ни сообщений
// об успехе пользователь не видел. Заявка: «нажимаю добавить —
// и ничего не происходит». Алиас ведёт на реальную тост-систему
// (#toast / showToast). var на top-level (не const) — доступен
// всем модулям ниже по файлу и window.KipToast для консоли.
var KipToast = {
    show: function(msg) {
        showToast(msg === null || msg === undefined ? '' : String(msg));
    }
};

// ============================================================
// Кастомные диалоги kipConfirm / kipPrompt
// Заменяют нативные confirm()/prompt(), чтобы убрать
// «Подтвердите действие на bloknett-design.github.io»
// ============================================================

/** Получить или создать общий оверлей для кастомных диалогов. */
function _kipDialogOverlay() {
    let ov = document.getElementById('kipDialogOverlay');
    if (ov) return ov;
    ov = document.createElement('div');
    ov.id = 'kipDialogOverlay';
    ov.className = 'kip-dialog-overlay';
    document.body.appendChild(ov);
    return ov;
}

/** Закрыть диалог и вернуть результат. */
function _kipDialogClose(ov, resolve, value) {
    ov.classList.remove('active');
    setTimeout(function() { ov.innerHTML = ''; }, 250);
    resolve(value);
}

/**
 * Кастомный confirm-диалог.
 * @param {string} msg — текст вопроса
 * @param {object} [opts] — { danger: true } — красная кнопка OK;
 *   { title } — заголовок (по умолчанию «Подтвердите действие»);
 *   { okText } — надпись кнопки подтверждения (по умолчанию «OK»);
 *   { cancelText } — надпись кнопки отмены (по умолчанию «Отмена»);
 *   { altText } — Task 278: ТРЕТЬЯ кнопка выбора (между «Отмена» и
 *     OK) — при клике промис резолвится строкой 'alt'
 * @returns {Promise<boolean|string>} — true (OK) / false (отмена,
 *   Escape) / 'alt' (третья кнопка выбора)
 */
// Task 265: настройки заголовка/кнопок + клавиатура (Escape — отмена,
// Enter — подтверждение; если фокус на кнопке диалога — Enter жмёт её,
// а не глобальный обработчик). Повторное срабатывание защищено.
// Task 278: опция altText — альтернативная кнопка действия
// (диалог «Сформировать»: месяц или год). Обратная совместимость:
// без altText — прежние две кнопки, результат boolean.
function kipConfirm(msg, opts) {
    opts = opts || {};
    return new Promise(function(resolve) {
        var ov = _kipDialogOverlay();
        var dangerCls = opts.danger ? ' danger' : '';
        var title = (opts.title != null && String(opts.title)) || 'Подтвердите действие';
        var okText = (opts.okText != null && String(opts.okText)) || 'OK';
        var cancelText = (opts.cancelText != null && String(opts.cancelText)) || 'Отмена';
        var altText = (opts.altText != null && String(opts.altText)) || '';
        ov.innerHTML =
            '<div class="kip-dialog' + (altText ? ' with-alt' : '') + '">' +
                '<div class="kip-dialog-title">' + _kipDialogEsc(title) + '</div>' +
                '<div class="kip-dialog-msg">' + (msg || '').replace(/</g,'&lt;') + '</div>' +
                '<div class="kip-dialog-btns' + (altText ? ' with-alt' : '') + '">' +
                    '<button type="button" class="kip-dialog-btn kip-dialog-cancel">' + _kipDialogEsc(cancelText) + '</button>' +
                    (altText
                        ? '<button type="button" class="kip-dialog-btn kip-dialog-alt">' + _kipDialogEsc(altText) + '</button>'
                        : '') +
                    '<button type="button" class="kip-dialog-btn kip-dialog-ok' + dangerCls + '">' + _kipDialogEsc(okText) + '</button>' +
                '</div>' +
            '</div>';
        var settled = false;
        var onKey = function(e) {
            var t = e && e.target;
            var fromBtn = t && t.closest ? t.closest('.kip-dialog-btn') : null;
            if (e.key === 'Escape') done(false);
            else if (e.key === 'Enter' && !fromBtn) done(true);
        };
        var cleanup = function() {
            document.removeEventListener('keydown', onKey);
        };
        var done = function(value) {
            if (settled) return;
            settled = true;
            cleanup();
            _kipDialogClose(ov, resolve, value);
        };
        ov.querySelector('.kip-dialog-cancel').onclick = function() { done(false); };
        // Task 278: альтернативная кнопка (есть только при altText)
        var altBtn = altText ? ov.querySelector('.kip-dialog-alt') : null;
        if (altBtn) altBtn.onclick = function() { done('alt'); };
        ov.querySelector('.kip-dialog-ok').onclick = function() { done(true); };
        document.addEventListener('keydown', onKey);
        requestAnimationFrame(function() { ov.classList.add('active'); });
    });
}

/** Экранирование заголовка/надписей кнопок диалога (Task 265). */
function _kipDialogEsc(s) {
    return String(s === null || s === undefined ? '' : s)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

/**
 * Кастомный prompt-диалог.
 * @param {string} msg — подсказка
 * @param {string} [defaultVal] — значение по умолчанию
 * @returns {Promise<string|null>} — null при отмене
 */
function kipPrompt(msg, defaultVal) {
    return new Promise(function(resolve) {
        var ov = _kipDialogOverlay();
        var val = (defaultVal != null) ? String(defaultVal).replace(/"/g,'&quot;') : '';
        ov.innerHTML =
            '<div class="kip-dialog">' +
                '<div class="kip-dialog-title">Подтвердите действие</div>' +
                '<div class="kip-dialog-msg">' + (msg || '').replace(/</g,'&lt;') + '</div>' +
                '<input type="text" class="kip-dialog-input" value="' + val + '">' +
                '<div class="kip-dialog-btns">' +
                    '<button type="button" class="kip-dialog-btn kip-dialog-cancel">Отмена</button>' +
                    '<button type="button" class="kip-dialog-btn kip-dialog-ok">OK</button>' +
                '</div>' +
            '</div>';
        var inp = ov.querySelector('.kip-dialog-input');
        ov.querySelector('.kip-dialog-cancel').onclick = function() { _kipDialogClose(ov, resolve, null); };
        ov.querySelector('.kip-dialog-ok').onclick = function() { _kipDialogClose(ov, resolve, inp.value); };
        inp.addEventListener('keydown', function(e) {
            if (e.key === 'Enter') { _kipDialogClose(ov, resolve, inp.value); }
            if (e.key === 'Escape') { _kipDialogClose(ov, resolve, null); }
        });
        requestAnimationFrame(function() {
            ov.classList.add('active');
            inp.focus();
            inp.select();
        });
    });
}

    // ======================== КОНВЕРТЕРЫ (полные данные) ========================
    const unitData = {
        pressure: { units: { 'Pa':{label:'Па',factor:1}, 'kPa':{label:'кПа',factor:1000}, 'MPa':{label:'МПа',factor:1000000}, 'bar':{label:'бар',factor:100000}, 'mbar':{label:'мбар',factor:100}, 'atm':{label:'атм',factor:101325}, 'kgf_cm2':{label:'кгс/см²',factor:98066.5}, 'kgf_m2':{label:'кгс/м²',factor:9.80665}, 'mmHg':{label:'мм рт. ст.',factor:133.322}, 'PSI':{label:'PSI',factor:6894.757}, 'mmH2O':{label:'мм вод. ст.',factor:9.80665} } },
        flow: { units: { 'm3h':{label:'м³/ч',factor:1}, 'm3s':{label:'м³/с',factor:3600}, 'l_min':{label:'л/мин',factor:0.06}, 'l_s':{label:'л/с',factor:3.6}, 't_h':{label:'т/ч',factor:1}, 'kg_s':{label:'кг/с',factor:3.6}, 'kg_h':{label:'кг/ч',factor:0.001} } },
        mass: { units: { 'kg':{label:'кг',factor:1}, 'g':{label:'г',factor:0.001}, 'mg':{label:'мг',factor:0.000001}, 't':{label:'т',factor:1000}, 'lb':{label:'фунт',factor:0.453592}, 'oz':{label:'унция',factor:0.0283495}, } },
        length: { units: { 'm':{label:'м',factor:1}, 'km':{label:'км',factor:1000}, 'cm':{label:'см',factor:0.01}, 'mm':{label:'мм',factor:0.001}, 'um':{label:'мкм',factor:0.000001}, 'mi':{label:'миля',factor:1609.344}, 'ft':{label:'фут',factor:0.3048}, 'in':{label:'дюйм',factor:0.0254}, 'yd':{label:'ярд',factor:0.9144} } },
        density: { units: { 'kg_m3':{label:'кг/м³',factor:1}, 'g_cm3':{label:'г/см³',factor:1000}, 'g_l':{label:'г/л',factor:1}, 'kg_l':{label:'кг/л',factor:1000}, } },
        time: { units: { 's':{label:'секунда',factor:1}, 'ms':{label:'мс',factor:0.001}, 'min':{label:'минута',factor:60}, 'h':{label:'час',factor:3600}, 'd':{label:'сутки',factor:86400}, 'week':{label:'неделя',factor:604800}, 'month':{label:'месяц',factor:2592000}, 'year':{label:'год',factor:31536000} } },
        volume: { units: { 'm3':{label:'м³',factor:1}, 'l':{label:'литр',factor:0.001}, 'ml':{label:'мл',factor:0.000001}, 'cm3':{label:'см³',factor:0.000001}, 'gal':{label:'галлон US',factor:0.00378541}, 'bbl':{label:'баррель',factor:0.158987}, 'ft3':{label:'куб. фут',factor:0.0283168}, 'dm3':{label:'дм³',factor:0.001} } }
    };
    function parseLocaleNumber(s){ if(typeof s!=='string')s=String(s); return parseFloat(s.replace(',','.')); }

    // ============================================================
    // Валидация полей ввода (#12)
    // ============================================================
    // При невалидном значении поле подсвечивается красной рамкой
    // и под ним показывается подсказка. При исправлении — рамка
    // и подсказка исчезают.
    //
    // Использование:
    //   <input oninput="validateNumericField(this)" />
    //   <input oninput="validatePositiveField(this)" />
    //   <input oninput="validateField(this, val => val > 0, 'Должно быть > 0')" />
    // ============================================================

    // Универсальная функция валидации. Принимает элемент, функцию-предикат
    // (должна вернуть true, если значение валидно) и сообщение об ошибке.
    function validateField(input, isValid, errorMsg) {
        // Удаляем предыдущую подсказку, если была
        const existingMsg = input.parentElement.querySelector('.input-error-msg[data-for="' + input.id + '"]');
        if (existingMsg) existingMsg.remove();

        const raw = input.value.trim();
        if (raw === '') {
            // Пустое поле не считаем ошибкой — это будет проверено при submit
            input.classList.remove('input-error');
            return true;
        }

        const val = parseLocaleNumber(raw);
        const valid = isValid(val, raw);
        if (valid) {
            input.classList.remove('input-error');
        } else {
            input.classList.add('input-error');
            // Добавляем подсказку под полем
            const msg = document.createElement('span');
            msg.className = 'input-error-msg';
            msg.dataset.for = input.id;
            msg.textContent = errorMsg || 'Некорректное значение';
            // Вставляем после поля
            input.parentNode.insertBefore(msg, input.nextSibling);
        }
        return valid;
    }

    // Готовые валидаторы для типовых случаев
    function validateNumericField(input) {
        return validateField(input, (val) => !isNaN(val), 'Введите число');
    }
    function validatePositiveField(input) {
        return validateField(input, (val) => !isNaN(val) && val > 0, 'Должно быть положительным числом');
    }
    function validateNonNegativeField(input) {
        return validateField(input, (val) => !isNaN(val) && val >= 0, 'Должно быть неотрицательным числом');
    }
    function validateRangeField(input, min, max) {
        return validateField(input, (val) => !isNaN(val) && val >= min && val <= max,
            'Должно быть в диапазоне ' + min + '–' + max);
    }

    // Утилита: снять ошибку с поля (вызывается при успешном расчёте)
    function clearFieldError(input) {
        if (!input) return;
        input.classList.remove('input-error');
        const msg = input.parentElement.querySelector('.input-error-msg[data-for="' + input.id + '"]');
        if (msg) msg.remove();
    }

    // Утилита: проверить, есть ли ошибки валидации в контейнере
    // (например, в форме расчёта). Возвращает true, если есть ошибки.
    function hasValidationErrors(container) {
        if (!container) return false;
        return container.querySelectorAll('.input-error').length > 0;
    }
    // Форматирование числа с русской запятой и разделением разрядов
    // неразрывным пробелом: 1234567.89 → "1 234 567,89"
    // Соответствует ГОСТ-стилю и русской типографике.
    function formatNumber(n) {
        if (n===0) return '0';
        if (Math.abs(n)>=1e9||Math.abs(n)<0.00001&&n!==0) return n.toExponential(4).replace('.',',');
        let d=Math.abs(n)>=100?2:Math.abs(n)>=1?4:6;
        // Округляем до нужного числа знаков, затем заменяем точку на запятую
        let s = parseFloat(n.toFixed(d)).toString().replace('.',',');
        // Добавляем неразрывные пробелы между разрядами целой части
        // \u00A0 — неразрывный пробел (not \u0020), чтобы число не разрывалось
        // при переносе строки. Разделяем только целую часть (до запятой).
        const parts = s.split(',');
        parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, '\u00A0');
        return parts.join(',');
    }
function roundNumber(n) {
    if (n === 0) return '0';
    let absN = Math.abs(n);
    if (absN >= 1e9 || (absN < 0.00001 && n !== 0)) return n.toExponential(1).replace('.',',');
    // Round to 2 significant figures: keep first 2 digits, rest zeros
    let order = Math.floor(Math.log10(absN));
    let dp = 1 - order; // decimal places needed for 2 sig figs
    let s;
    if (dp < 0) {
        // Round to nearest 10^(-dp) for large numbers
        let factor = Math.pow(10, -dp);
        let result = Math.round(n / factor) * factor;
        s = result.toString().replace('.',',');
    } else {
        let result = parseFloat(n.toFixed(dp));
        s = result.toString().replace('.',',');
    }
    // Разделяем разряды целой части неразрывным пробелом
    const parts = s.split(',');
    parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, '\u00A0');
    return parts.join(',');
}
    function convertUnits(cat) { if (cat==='temp') { convertTemp(); return; } let d=unitData[cat]; let val=parseLocaleNumber(document.getElementById(`conv-${cat}-input`).value); let from=document.getElementById(`conv-${cat}-unit`).value; let resDiv=document.getElementById(`conv-${cat}-results`); let tableDiv=document.getElementById(`conv-${cat}-table`); if(tableDiv) tableDiv.style.display='none'; if(isNaN(val)) { resDiv.innerHTML='<p style="text-align:center;color:#c74a4a;font-size:14px;padding:16px;">Введите значение</p>'; return; } let base=val*d.units[from].factor; let html='<div class="converter-result-label-title">Результаты</div>'; let delay=0; for(let u in d.units){ if(u===from) continue; let v=base/d.units[u].factor; html+=`<div class="converter-result-item" style="animation-delay:${delay}ms;cursor:pointer;" onclick="showConverterTable('${cat}','${from}','${u}',${base})"><span class="converter-result-label">${d.units[u].label}</span><span class="converter-result-value">${formatNumber(v)} <span style="color:rgba(255,255,255,0.25);font-weight:400;font-size:0.85em;">(${roundNumber(v)})</span></span></div>`; delay+=40; } resDiv.innerHTML=html; }
    function convertTemp() { let val=parseLocaleNumber(document.getElementById('conv-temp-input').value); let from=document.getElementById('conv-temp-unit').value; let resDiv=document.getElementById('conv-temp-results'); let tableDiv=document.getElementById('conv-temp-table'); if(tableDiv) tableDiv.style.display='none'; if(isNaN(val)) { resDiv.innerHTML='<p style="text-align:center;color:#c74a4a;font-size:14px;padding:16px;">Введите значение</p>'; return; } let c=from==='C'?val:from==='F'?(val-32)*5/9:from==='K'?val-273.15:from==='R'?val*1.25:(val-491.67)*5/9; let tU={'C':{label:'°C',fn:z=>z},'F':{label:'°F',fn:z=>z*9/5+32},'K':{label:'K',fn:z=>z+273.15},'R':{label:'°R',fn:z=>z*0.8},'Ra':{label:'°Ra',fn:z=>(z+273.15)*9/5}}; let html='<div class="converter-result-label-title">Результаты</div>'; let delay=0; for(let u in tU){ if(u===from) continue; let v=tU[u].fn(c); html+=`<div class="converter-result-item" style="animation-delay:${delay}ms;cursor:pointer;" onclick="showTempTable('${from}','${u}',${c})"><span class="converter-result-label">${tU[u].label}</span><span class="converter-result-value">${formatNumber(v)} <span style="color:rgba(255,255,255,0.25);font-weight:400;font-size:0.85em;">(${roundNumber(v)})</span></span></div>`; delay+=40; } resDiv.innerHTML=html; }

