    let toLabel = tU[toUnit].label;
    let tableDiv = document.getElementById('conv-temp-table');

    let html = '<div class="converter-result-label-title">Таблица перевода: ' + fromLabel + ' → ' + toLabel + ' (шаг 5%)</div>';
