        'S':{name:'S (ТПП 10% Rh)',ranges:{class1:[[0,1100,'const',1.0],[1100,1600,'linear2',[1.0,0.003]]],class2:[[0,600,'const',1.5],[600,1600,'linear',0.0025]],class3:null}},
