    function removeKitDevice(idx) {
        let el = document.getElementById('kit_dev_' + idx);
        if (el) el.remove();
        renumberKitDevices();
        updateKitLimitMsg();
    }

    function renumberKitDevices() {
        let container = document.getElementById('kit_device_list');
        let devs = container.querySelectorAll('[id^="kit_dev_"]');
        devs.forEach((el, i) => {
            let row = el.firstElementChild;
            if (row) { let label = row.firstElementChild; if (label) label.textContent = 'Прибор ' + (i + 1); }
        });
    }

    function updateKitLimitMsg() {
        let container = document.getElementById('kit_device_list');
        let existing = container.querySelectorAll('[id^="kit_dev_"]');
        let msg = document.getElementById('kit_add_limit_msg');
        if (msg) msg.style.display = existing.length >= 5 ? 'block' : 'none';
    }

    function toggleKitDevFields(idx) {
        let p = 'kd_' + idx + '_';
        let form = document.getElementById(p + 'class_form').value;
        let groups = ['group_simple', 'group_circle', 'group_absolute'];
        groups.forEach(g => {
            let el = document.getElementById(p + g);
            if (el) el.style.display = 'none';
        });
        let clsWraps = ['cls_simple_wrap', 'cls_circle_wrap', 'cls_absolute_wrap'];
        clsWraps.forEach(w => {
            let el = document.getElementById(p + w);
            if (el) el.style.display = 'none';
        });
        let showMap = {'number': 'group_simple', 'circle': 'group_circle', 'absolute': 'group_absolute'};
        let clsMap = {'number': 'cls_simple_wrap', 'circle': 'cls_circle_wrap', 'absolute': 'cls_absolute_wrap'};
        let showEl = document.getElementById(p + showMap[form]);
        if (showEl) showEl.style.display = 'block';
        let clsEl = document.getElementById(p + clsMap[form]);
        if (clsEl) clsEl.style.display = 'block';
    }

    function toggleKitDevCustom(idx, type) {
        let p = 'kd_' + idx + '_';
        if (type === 'number') {
            let sel = document.getElementById(p + 'class_val');
            let inp = document.getElementById(p + 'class_val_custom');
            if (sel && inp) inp.style.display = sel.value === 'custom' ? 'block' : 'none';
        } else if (type === 'circle') {
            let sel = document.getElementById(p + 'class_val_c');
            let inp = document.getElementById(p + 'class_val_c_custom');
            if (sel && inp) inp.style.display = sel.value === 'custom' ? 'block' : 'none';
        }
    }

    function calcKitDeviceError(idx) {
        let p = 'kd_' + idx + '_';
        let devEl = document.getElementById('kit_dev_' + idx);
        if (!devEl) return null;
        let form = document.getElementById(p + 'class_form').value;
        let absErr, xNorm;
        try {
            if (form === 'number') {
                let clsVal = document.getElementById(p + 'class_val').value;
                let cls = clsVal === 'custom' ? parseLocaleNumber(document.getElementById(p + 'class_val_custom').value) : parseFloat(clsVal);
                let xmin = parseLocaleNumber(document.getElementById(p + 'xmin').value);
                let xmax = parseLocaleNumber(document.getElementById(p + 'xmax').value);
                if (isNaN(cls) || cls <= 0 || isNaN(xmin) || isNaN(xmax) || xmin >= xmax) return null;
                xNorm = (xmin === 0) ? Math.abs(xmax) : (xmax - xmin);
                absErr = (cls / 100) * xNorm;
            } else if (form === 'circle') {
                let clsVal = document.getElementById(p + 'class_val_c').value;
                let cls = clsVal === 'custom' ? parseLocaleNumber(document.getElementById(p + 'class_val_c_custom').value) : parseFloat(clsVal);
                let xcur = parseLocaleNumber(document.getElementById(p + 'x_current_c').value);
                if (isNaN(cls) || cls <= 0 || isNaN(xcur) || xcur === 0) return null;
                absErr = (cls / 100) * Math.abs(xcur);
            } else if (form === 'absolute') {
                let val = parseLocaleNumber(document.getElementById(p + 'abs_val').value);
                if (isNaN(val) || val <= 0) return null;
                absErr = val;
            }
        } catch(e) { return null; }
        let name = 'Прибор ' + idx;
        let resEl = document.getElementById(p + 'abs_result');
        if (resEl && absErr !== undefined) {
            resEl.innerHTML = '±Δ = ' + formatNumber(absErr);
            resEl.style.display = 'block';
        }
        return {idx: idx, name: name, absErr: absErr, form: form};
    }

    function calcErrorKit() {
        let devs = [];
        let container = document.getElementById('kit_device_list');
        let forms = container.querySelectorAll('[id^="kit_dev_"]');
        let allIdxs = [];
        forms.forEach((f, i) => {
            let m = f.id.match(/kit_dev_(\d+)/);
            if (m) allIdxs.push({idx: parseInt(m[1]), visualNum: i + 1});
        });
        for (let item of allIdxs) {
            let result = calcKitDeviceError(item.idx);
            if (result) { result.name = 'Прибор ' + item.visualNum; devs.push(result); }
        }
        if (devs.length === 0) { showToast('Добавьте хотя бы один прибор и заполните данные'); return; }
        let method = document.getElementById('kit_method').value;
        let totalAbs;
        let formulaText;
        if (method === 'geometric_plain') {
            let sumSq = 0;
            for (let d of devs) sumSq += d.absErr * d.absErr;
            totalAbs = Math.sqrt(sumSq);
            formulaText = 'Δ<sub>Σ</sub> = √(Δ₁² + Δ₂² + … + Δₙ²)';
        } else if (method === 'geometric') {
            let sumSq = 0;
            for (let d of devs) sumSq += d.absErr * d.absErr;
            totalAbs = 1.1 * Math.sqrt(sumSq);
            formulaText = 'Δ<sub>Σ</sub> = K·√(Δ₁² + Δ₂² + … + Δₙ²), K=1.1, P=0.95';
        } else {
            totalAbs = 0;
            for (let d of devs) totalAbs += d.absErr;
            formulaText = 'Δ<sub>Σ</sub> = Δ₁ + Δ₂ + … + Δₙ (арифметическое)';
        }
        let html = '<div class="converter-result-label-title">Результаты расчёта (комплект приборов)</div>';
        for (let d of devs) {
            html += '<div class="converter-result-item"><span class="converter-result-label">' + (d.name || 'Прибор ' + d.idx) + ': ±Δ</span><span class="converter-result-value" style="color:#4a8fc7;">± ' + formatNumber(d.absErr) + '</span></div>';
        }
        html += '<div class="converter-result-item"><span class="converter-result-label">Суммарная абс. погрешность (±Δ<sub>Σ</sub>)</span><span class="converter-result-value" style="color:#4ac771;">± ' + formatNumber(totalAbs) + '</span></div>';
        html += '<div class="converter-result-item" style="flex-direction:column;align-items:flex-start;gap:4px;"><span class="converter-result-label">Формула</span><span style="font-size:13px;color:rgba(140,180,210,0.9);line-height:1.5;">' + formulaText + '</span></div>';
        document.getElementById('errorKitResults').innerHTML = html;
        document.getElementById('errorKitResults').style.display = 'block';
        setTimeout(() => document.getElementById('errorKitResults').scrollIntoView({behavior:'smooth',block:'start'}), 100);
    }

    // Initialize kit page with 2 default devices
    (function(){ addKitDevice('number', '0.5', '0', '1.6'); addKitDevice('number', '0.25', '4', '20'); })();

    // ============================================================
    // Task 372: «Датчики температуры» — страница карточек и страница
    // датчика. Раньше тип датчика выбирался выпадающими списками
    // (temp_sensor_type / temp_rtd_type / temp_tc_type) прямо в форме
    // расчёта; теперь список датчиков — карточки на #page-temp-sensors,
    // а расчёт живёт на отдельной странице #page-temp-sensor-view.
    // ============================================================
    // Состояние: ключ выбранного датчика (см. getTempSensorCatalog).
    var tempSensorKey=null;
    // Карта типов термопар (имена как в бывшем select temp_tc_type)
    function getTcSensorMap(){
        // Task 373: добавлена ТХК (L) — хромель-копель (ГОСТ Р 8.585-2001)
        return {K:'ТХА (K)',J:'ТЖК (J)',T:'ТМК (T)',N:'ТНН (N)',E:'ТХКн (E)',L:'ТХК (L)',R:'ТПП (R)',S:'ТПП (S)',B:'ТПР (B)'};
    }
    // ============================================================
    // Task 373: TempFav — избранное датчиков температуры, по примеру
    // расходомеров хозрасчётных (FlowFav): отдельный localStorage-ключ,
    // звёздочка на карточке списка и в шапке страницы датчика, таб
    // «Избранные». Без drag-and-drop: порядок избранных = порядок
    // каталога (каталог фиксированный, в отличие от расходомеров).
    // ============================================================
    var TempFav={
        _STORAGE_KEY:'kip8_temp_fav_v1',
        _data:null,
        _load:function(){
            if(this._data!==null){return;}
            try{
                let raw=(typeof localStorage!=='undefined')?localStorage.getItem(this._STORAGE_KEY):null;
                this._data=raw?JSON.parse(raw):{};
            }catch(e){this._data={};}
        },
        _save:function(){
            try{localStorage.setItem(this._STORAGE_KEY,JSON.stringify(this._data||{}));}catch(e){}
        },
        has:function(key){this._load();return this._data.hasOwnProperty(String(key));},
        add:function(key){
            this._load();
            let k=String(key);
            if(this._data.hasOwnProperty(k)){return false;}
            this._data[k]=new Date().toISOString();
            this._save();
            return true;
        },
        remove:function(key){
            this._load();
            let k=String(key);
            if(!this._data.hasOwnProperty(k)){return false;}
            delete this._data[k];
            this._save();
            return true;
        },
        toggle:function(key){if(this.has(key)){this.remove(key);return false;}this.add(key);return true;},
        count:function(){this._load();return Object.keys(this._data).length;}
    };
    // Task 373: звёздочка на карточке списка (как flow-card-fav-btn)
    function toggleTempSensorFav(key){
        TempFav.toggle(key);
        if(typeof navigator!=='undefined'&&navigator.vibrate){navigator.vibrate(10);}
        renderTempSensorCards();
        updateTempSensorFavBtn();
    }
    // Task 373: звёздочка в шапке страницы датчика (как flowFavBtn)
    function toggleTempSensorFavFromView(){
        if(!tempSensorKey){return;}
        toggleTempSensorFav(tempSensorKey);
    }
    function updateTempSensorFavBtn(){
        let btn=document.getElementById('tempSensorFavBtn');
        if(!btn){return;}
        let isFav=tempSensorKey?TempFav.has(tempSensorKey):false;
        if(btn.classList){btn.classList.toggle('active',isFav);}
        btn.textContent=isFav?'★':'☆';
        btn.setAttribute('aria-label',isFav?'Убрать из избранного':'В избранное');
    }
    // Каталог всех датчиков температуры — источник карточек страницы
    // выбора, диапазонов НСХ и справочной информации. Порядок как в
    // бывших выпадающих списках: ТС (Cu → Pt), затем ТП (K…B),
    // Task 373: после ТХКн (E) — ТХК (L), хромель-копель.
    // Task 490: порядок ТП — парами для мобильных кнопок по две в
    // строке: ТХА (K)+ТХК (L) (заявка — вместе), затем ТЖК (J)+
    // ТМК (T), ТХКн (E)+ТНН (N), ТПП (R)+ТПП (S), ТПР (B).
    // Task 491: порядок ТС — парами ОДИНАКОВЫХ градуировок (заявка):
    // 50М+50М (α 0,00428 и 0,00426), 100М+100М, далее пары Task 490
    // без изменений: 50П+100П, Pt100+Pt1000.
    // Task 498 (заявка: «посмотри пределы измерения и скорректируй
    // неточности»): пределы НСХ каталога СВЕРЕНЫ с первоисточниками и
    // подтверждены — диапазоны НЕ менялись: ТС Cu (50М/100М, α 0,00428
    // и 0,00426) — −50…+200 °C (линейная формула НСХ меди R(t)=R₀(1+αt);
    // область обратного преобразования по ГОСТ 6651-2009, приложение Б);
    // ТС Pt (50П/100П/Pt100/Pt1000) — −200…+850 °C (таблицы А.1/А.2
    // ГОСТ 6651-2009 / IEC 60751); ТП — НИСТ ITS-90 (SRD 60) =
    // ГОСТ Р 8.585-2001: K −270…1372, J −210…1200, T −270…400,
    // N −270…1300, E −270…1000, L −200…800, R и S −50…1768,
    // B 0…1820 °C. Исправлена формула pt1391 ниже 0 °C (см.
    // calcRtdResistance, Task 498) — значения 100П/50П теперь точно
    // по таблице А.2.
    // Task 499 (заявка: «проверь у 50М (Cu50) α = 0,00428 °C⁻¹
    // диапазон, по моему −180…200 °C»): УТОЧНЕНО по ГОСТ 6651-2009 —
    // НСХ меди W100 = 1,428 задана формулой 5.2.3 «от минус 180 до
    // 0 °C» + линейной «от 0 до 200 °C», таблица А.3 начинается с
    // −180 °C (R = 20,53 Ом при R₀ = 100): диапазон каталога для
    // α = 0,00428 расширен до −180…+200, НСХ ниже 0 °C нелинейна —
    // см. calcCuResistance (Task 499). Медь W100 = 1,426 (α = 0,00426)
    // в ГОСТ представлена только обратной функцией (прил. Б.3,
    // −50…+200) — диапазон прежний. Pt и ТП — без изменений.
    function getTempSensorCatalog(){
        let rtd=getRtdSensorMap();
        let alphaTxt={pt1391:'α = 0,00391 (ГОСТ)',pt1385:'α = 0,00385 (IEC)'};
        let fmtR=function(v){return String(v).replace('-','−');};
        let list=[];
        ['cu50_1428','cu50_1426','cu100_1428','cu100_1426','pt50_1391','pt100_1391','pt100_1385','pt1000_1385'].forEach(function(k){
            let sd=rtd[k];
            if(!sd){return;}
            let isCu=sd.nsc==='cu';
            let alpha=isCu?('α = '+String(sd.alpha).replace('.',',')+' °C⁻¹'):alphaTxt[sd.nsc];
            // Task 499 (заявка: сверка диапазона 50М): медь W100 = 1,428
            // (α = 0,00428) — НСХ −180…+200 (таблица А.3 / формула 5.2.3
            // ГОСТ 6651-2009, заявка подтверждена); W100 = 1,426 —
            // прежние −50…+200 (в ГОСТ — только обратная функция, Б.3).
            let rng499=isCu?((Math.abs(sd.alpha-0.00428)<1e-9)?{min:-180,max:200}:{min:-50,max:200}):{min:-200,max:850};
            list.push({key:k,kind:'rtd',name:sd.name,meta:'R₀ = '+sd.r0+' Ом · '+alpha,range:rng499});
        });
        // Task 373: L — хромель-копель, диапазон НСХ −200…800 °C
        let tcm={K:{mat:'хромель-алюмель',r:[-270,1372]},J:{mat:'железо-константан',r:[-210,1200]},T:{mat:'медь-константан',r:[-270,400]},N:{mat:'никросил-нисил',r:[-270,1300]},E:{mat:'хромель-константан',r:[-270,1000]},L:{mat:'хромель-копель',r:[-200,800]},R:{mat:'платинородий-платина',r:[-50,1768]},S:{mat:'платинородий-платина',r:[-50,1768]},B:{mat:'платинородий-платинородий',r:[0,1820]}};
        ['K','L','J','T','E','N','R','S','B'].forEach(function(k){
            let m=tcm[k];
            list.push({key:'tc_'+k,kind:'tc',tc:k,name:getTcSensorMap()[k],meta:m.mat,range:{min:m.r[0],max:m.r[1]}});
        });
        return list;
    }
    // Поиск датчика в каталоге по ключу
    function tempSensorFindByKey(key){
        let found=null;
        getTempSensorCatalog().forEach(function(s){ if(s.key===key){found=s;} });
        return found;
    }
    // Task 373: состояние таба «Все / Избранные» страницы выбора
    var tempSensorsTab='all';
    // Рендер карточек на странице выбора. Task 373: перерисовывается при
    // КАЖДОМ вызове (звёзды избранного и активный таб меняются), в режиме
    // «Избранные» показывает только избранные датчики (заголовки пустых
    // групп скрыты), бейджи ТС/ТП убраны, звезда избранного — в правом
    // верхнем углу карточки (по примеру расходомеров хозрасчётных).
    // Task 490: имя/meta ТС делятся на спаны — на десктопе текст
    // прежний (спаны инлайн), на мобильном скрыты аналог в скобках
    // и R₀: на кнопке ТС остаются только градуировка и температурный
    // коэффициент (α), на кнопке ТП — наименование с градуировкой.
    // Task 492: (а) счётчики обновляются в ДВУХ местах — верхние табы
    // .ts-tabs (десктоп) и нижний бар #tsBottomBar (мобильный,
    // tsAllCountMob/tsFavCountMob); (б) класс ts-card-feat
    // (featured-оформление: рамка 2px + эффект выступа, CSS @media
    // ≤1023px) вешается на КНОПКИ В ИЗБРАННОМ (isFav) — Task 491
    // (популярные 50М/100М/ТХА (K)/ТХК (L)) отменён заявкой.
    function renderTempSensorCards(){
        let rtdBox=document.getElementById('tsRtdCards');
        let tcBox=document.getElementById('tsTcCards');
        if(!rtdBox||!tcBox){return;}
        let favMode=(tempSensorsTab==='fav');
        let fmtR=function(v){return String(v).replace('-','−');};
        let cat=getTempSensorCatalog();
        // счётчики в табах «Все / Избранные» (обновляются при каждом
        // рендере); Task 492: в ДВУХ экземплярах — верхние табы .ts-tabs
        // (десктоп ≥1024px) и нижний бар #tsBottomBar (мобильный ≤1023px)
        let allEl=document.getElementById('tsAllCount'),favEl=document.getElementById('tsFavCount');
        let allElMob=document.getElementById('tsAllCountMob'),favElMob=document.getElementById('tsFavCountMob');
        if(allEl){allEl.textContent=String(cat.length);}
        if(favEl){favEl.textContent=String(TempFav.count());}
        if(allElMob){allElMob.textContent=String(cat.length);}
        if(favElMob){favElMob.textContent=String(TempFav.count());}
        let rtdHtml='',tcHtml='',rtdShown=false,tcShown=false;
        cat.forEach(function(s){
            if(favMode&&!TempFav.has(s.key)){return;}
            let isFav=TempFav.has(s.key);
            // Task 490: имя ТС — «градуировка + аналог в скобках»;
            // на мобильном аналог скрыт (CSS .ts-card-name-analog),
            // на кнопке — только градуировка (50М, 100П, Pt100 …)
            let nameHtml=s.name;
            if(s.kind==='rtd'){
                let sp=String(s.name).indexOf(' (');
                if(sp>0){
                    nameHtml='<span class="ts-card-name-main">'+s.name.slice(0,sp)+'</span><span class="ts-card-name-analog">'+s.name.slice(sp)+'</span>';
                }
            }
            // Task 490: meta ТС — «R₀ · α»; на мобильном R₀ скрыт
            // (CSS .ts-card-r0), на кнопке — только температурный
            // коэффициент; у ТП (материал электродов) meta на
            // мобильном скрыта целиком
            let metaHtml=s.meta;
            if(s.kind==='rtd'){
                let sep=s.meta.indexOf(' · ');
                if(sep>0){
                    metaHtml='<span class="ts-card-r0">'+s.meta.slice(0,sep)+'</span><span class="ts-card-meta-sep"> · </span><span class="ts-card-alpha">'+s.meta.slice(sep+3)+'</span>';
                }
            }
            // Task 492: featured-оформление (класс ts-card-feat: рамка
            // 2px, градиент, эффект выступа — CSS @media ≤1023px) теперь
            // у КНОПОК В ИЗБРАННОМ (isFav; в режиме «Избранные» выделены
            // все показанные), а НЕ у популярных градуировок 50М/100М/
            // ТХА (K)/ТХК (L) — Task 491 отменён заявкой: их оформление
            // прежнее, крупный шрифт (CSS) — у ВСЕХ кнопок;
            // десктоп ≥1024px — стилей feat нет (класс в DOM безвреден)
            let feat=isFav;
            let card='<div class="ts-card'+(s.kind==='tc'?' ts-card-tc':'')+(feat?' ts-card-feat':'')+'" onclick="openTempSensor(\''+s.key+'\')" role="button" tabindex="0" aria-label="'+s.name+'">'
                +'<button type="button" class="ts-card-fav-btn'+(isFav?' active':'')+'" onclick="event.stopPropagation(); toggleTempSensorFav(\''+s.key+'\')" aria-label="'+(isFav?'Убрать из избранного':'В избранное')+'" title="'+(isFav?'Убрать из избранного':'В избранное')+'">'+(isFav?'★':'☆')+'</button>'
                +'<div class="ts-card-top"><span class="ts-card-name">'+nameHtml+'</span><i class="ts-card-arrow">›</i></div>'
                +'<div class="ts-card-meta">'+metaHtml+'</div>'
                +'<div class="ts-card-range">НСХ: '+fmtR(s.range.min)+'…'+fmtR(s.range.max)+' °C</div>'
                +'</div>';
            if(s.kind==='rtd'){rtdHtml+=card;rtdShown=true;}else{tcHtml+=card;tcShown=true;}
        });
        if(favMode&&!rtdShown&&!tcShown){
            rtdHtml='<div class="ts-empty-fav"><div class="ts-empty-fav-icon">☆</div><div class="ts-empty-fav-text">Нет избранных датчиков</div><div class="ts-empty-fav-hint">Перейдите во вкладку «Все»<br>и нажмите <span class="star">☆</span> на карточке</div></div>';
        }
        rtdBox.innerHTML=rtdHtml;
        tcBox.innerHTML=tcHtml;
        // в режиме «Избранные» скрываем заголовки пустых групп
        let rtdTitle=document.getElementById('tsRtdGroupTitle');
        let tcTitle=document.getElementById('tsTcGroupTitle');
        if(rtdTitle){rtdTitle.style.display=(!favMode||rtdShown)?'':'none';}
        if(tcTitle){tcTitle.style.display=(!favMode||tcShown)?'':'none';}
    }
    // Task 373: переключение таба «Все / Избранные» (setTab у расходомеров)
    function setTempSensorsTab(tab){
        if(tab!=='all'&&tab!=='fav'){return;}
        if(tempSensorsTab===tab){return;}
        tempSensorsTab=tab;
        if(typeof document.querySelectorAll==='function'){
            let btns=document.querySelectorAll('.ts-tab[data-ts-tab]');
            for(let i=0;i<btns.length;i++){
                let b=btns[i];
                let on=(b.getAttribute('data-ts-tab')===tab);
                b.classList.toggle('active',on);
                b.setAttribute('aria-selected',on?'true':'false');
            }
        }
        renderTempSensorCards();
    }
    // Открытие страницы датчика: карточка → #page-temp-sensor-view
    function openTempSensor(key){
        let sel=tempSensorFindByKey(key);
        if(!sel){showToast('Датчик не найден');return;}
        tempSensorKey=key;
        let title=document.getElementById('tempSensorViewTitle');
        // Task 498 (заявка): в баре страницы — ТОЛЬКО тип датчика:
        // ТС — «градуировка (аналог) α = … °C⁻¹» (например,
        // «50М (Cu50) α = 0,00428 °C⁻¹»; α различает одинаковые
        // градуировки 50М/100М), ТП — наименование («ТХА (K)»).
        // Пояснения «— термометр сопротивления»/«— термопара» убраны;
        // шрифт заголовка крупнее (CSS #tempSensorViewTitle, 21px).
        if(title){
            let t498=sel.name;
            if(sel.kind==='rtd'){
                let sd498=getRtdSensorMap()[sel.key]||{};
                if(sd498.nsc==='cu'){
                    t498+=' α = '+String(sd498.alpha).replace('.',',')+' °C⁻¹';
                }else if(sd498.nsc==='pt1391'){
                    t498+=' α = 0,00391 °C⁻¹';
                }else if(sd498.nsc==='pt1385'){
                    t498+=' α = 0,00385 °C⁻¹';
                }
            }
            title.textContent=t498;
        }
        // Task 495: чип типа датчика удалён из блока ввода — тип
        // датчика виден в заголовке страницы
        let mn=document.getElementById('temp_sensor_min'),mx=document.getElementById('temp_sensor_max'),st=document.getElementById('temp_sensor_step');
        if(mn){mn.value='0';}
        if(mx){mx.value='100';}
        if(st){st.value='10';}
        let res=document.getElementById('tempSensorResults');
        if(res){res.innerHTML='';res.style.display='none';}
        // Task 373: панель «Расчёт произвольных значений» (статичная,
        // над формой выбора) — подпись второго поля под тип датчика,
        // оба поля очищены
        let vLab=document.getElementById('tempQueryValLabel');
        let vInp=document.getElementById('tempQueryVal');
        let tInp=document.getElementById('tempQueryTemp');
        if(sel.kind==='rtd'){
            if(vLab){vLab.textContent='Сопротивление R(t), Ом';}
        }else{
            if(vLab){vLab.textContent='Термо-ЭДС E(t), мВ';}
        }
        if(tInp){tInp.value='';}
        if(vInp){vInp.value='';}
        // Task 499 (заявка: «подсказки диапазонов впиши непосредственно
        // в поля ввода, бледным текстом, вместо предложений-примеров»):
        // пределы НСХ датчика — ПЛЕЙСХОЛДЕРЫ полей произвольного расчёта
        // (бледный текст — прежнее CSS-правило плейсхолдеров полей,
        // Task 494): у температуры — в градусах Цельсия («−180…200 °C»,
        // целые, как на карточках каталога), у значения — в единицах
        // измерения датчика («10,2642…92,8 Ом» для ТС, мВ для ТП).
        // Прежние предложения-примеры и строки-подсказки под полями
        // (Task 498) удалены — информация теперь в самих полях.
        // Границы — из каталога (единый источник диапазонов), значения
        // для Ом/мВ — через НСХ (tempCalcForwardValue) на границах.
        let rng499=getTempSensorRange();
        let fmtI499=function(v){return String(v).replace('-','−');};
        let fmtM499=function(v){return formatNumber(v).replace('-','−');};
        if(tInp){tInp.placeholder=fmtI499(rng499.min)+'…'+fmtI499(rng499.max)+' °C';}
        if(vInp){
            let vmin499=tempCalcForwardValue(rng499.min);
            let vmax499=tempCalcForwardValue(rng499.max);
            if(vmin499!==null&&vmax499!==null&&isFinite(vmin499)&&isFinite(vmax499)){
                vInp.placeholder=fmtM499(vmin499)+'…'+fmtM499(vmax499)+' '+((sel.kind==='rtd')?'Ом':'мВ');
            }else{
                vInp.placeholder='';
            }
        }
        // Task 373: звезда избранного в шапке страницы датчика
        updateTempSensorFavBtn();
        let body=document.getElementById('tempSensorInfoBody');
        if(body){body.innerHTML=tempSensorInfoHtml(sel);}
        if(typeof navigator!=='undefined'&&navigator.vibrate){navigator.vibrate(10);}
        navigateTo('temp-sensor-view');
    }
    // Справочная информация на странице датчика (заявка Task 372):
    // блок остаётся в КАЖДОМ датчике, но в термометрах НЕТ информации
    // о термопарах, а в термопарах — о термометрах.
    function tempSensorInfoHtml(sel){
        let b='color:var(--conv-info-bold);';
        if(sel.kind==='rtd'){
            let sd=getRtdSensorMap()[sel.key]||{};
            return '<div style="margin-bottom:8px;"><b style="'+b+'">Тип:</b> Термопреобразователь сопротивления (ТС) — измеряет температуру по изменению электрического сопротивления чувствительного элемента.</div>'
                +'<div style="margin-bottom:8px;"><b style="'+b+'">Этот датчик:</b> '+(sd.name||sel.name)+'; R₀ = '+(sd.r0||'—')+' Ом; формула: '+(sd.formula||'—')+'; диапазон НСХ: '+sel.range.min+'…'+sel.range.max+' °C.</div>'
                +'<div style="margin-bottom:8px;"><b style="'+b+'">Формулы ТС:</b> медные (α = 0,00428): при t ≥ 0 — R(t) = R₀·(1 + α·t); при t < 0 — R(t) = R₀·[1 + A·t + B·t·(t+6,7 °C) + C·t³], A = 4,28·10⁻³, B = −6,2032·10⁻⁷, C = 8,5154·10⁻¹⁰ (ГОСТ 6651-2009, ф. 5.2.3); платиновые: R(t) = R₀·[1 + A·t + B·t² + C·(t−100)·t³] — член C добавляется ниже 0 °C.</div>'
                +'<div style="margin-bottom:8px;"><b style="'+b+'">Температурные коэффициенты:</b> Cu: α = 0,00428 °C⁻¹ (50М, 100М) или 0,00426 °C⁻¹; Pt: α = 0,00391 °C⁻¹ (50П, 100П, ГОСТ 6651-2009) или 0,00385 °C⁻¹ (IEC 60751).</div>'
                +'<div><b style="'+b+'">Нормативные документы:</b> ГОСТ 6651-2009 (ТС), IEC 60751 (Pt).</div>';
        }
        // Task 373: для ТХК (L) — отдельная строка НСХ: тип есть только в
        // ГОСТ Р 8.585-2001 (в МЭК 60584 и базе НИСТ SRD 60 его нет),
        // расчёт — аппроксимирующий полином по таблице стандарта.
        let nscLine;
        if(sel.tc==='L'){
            nscLine='<div style="margin-bottom:8px;"><b style="'+b+'">НСХ термопар:</b> стандартизированы ГОСТ Р 8.585-2001; тип ТХК (L) есть только в ГОСТ (в МЭК 60584 и базе НИСТ отсутствует); расчёт — аппроксимирующий полином по таблице стандарта: E(t) = Σ cᵢ·tⁱ.</div>';
        }else{
            nscLine='<div style="margin-bottom:8px;"><b style="'+b+'">НСХ термопар:</b> стандартизированы ГОСТ Р 8.585-2001; расчёт — полиномы НИСТ ITS-90 (SRD 60): E(t) = Σ cᵢ·tⁱ.</div>';
        }
        return '<div style="margin-bottom:8px;"><b style="'+b+'">Тип:</b> Термопара (ТП) — измеряет температуру по термо-ЭДС, возникающей в спае двух разнородных проводников (эффект Зеебека).</div>'
            +'<div style="margin-bottom:8px;"><b style="'+b+'">Этот датчик:</b> '+sel.name+'; электроды: '+sel.meta+'; диапазон НСХ: '+sel.range.min+'…'+sel.range.max+' °C; E(0 °C) = 0 мВ (опорный спай 0 °C).</div>'
            +nscLine
            +'<div style="margin-bottom:8px;"><b style="'+b+'">Наиболее распространённые типы:</b> ТХА (K), ТХК (L), ТЖК (J), ТМК (T), ТНН (N), ТХКн (E), ТПП (R), ТПП (S), ТПР (B).</div>'
            +'<div><b style="'+b+'">Нормативные документы:</b> ГОСТ Р 8.585-2001 (ТП).</div>';
    }
    function calcTempSensor(){
        // Task 372: датчик — из состояния страницы карточек (раньше —
        // выпадающие списки temp_sensor_type / temp_rtd_type / temp_tc_type)
        let sel=tempSensorFindByKey(tempSensorKey);
        if(!sel){showToast('Выберите датчик температуры');return;}
        let type=sel.kind;
        let tMin=parseLocaleNumber(document.getElementById('temp_sensor_min').value);
        let tMax=parseLocaleNumber(document.getElementById('temp_sensor_max').value);
        let step=parseLocaleNumber(document.getElementById('temp_sensor_step').value)||10;
        let resDiv=document.getElementById('tempSensorResults');
        if(isNaN(tMin)||isNaN(tMax)){showToast('Введите диапазон измерения');return;}
        if(tMin>=tMax){showToast('Минимум должен быть меньше максимума');return;}
        if(step<=0){step=10;}
        if(type==='rtd'){
            let rtdType=sel.key;
            // Task 371: карта типов ТС — общая с блоком
            // «Расчёт произвольных значений» (см. getRtdSensorMap)
            let sensorData=getRtdSensorMap();
            let sd=sensorData[rtdType];
            if(!sd){showToast('Неизвестный тип ТС');return;}
            let isCu=sd.nsc==='cu';
            let html=`<div class="converter-result-label-title">Результаты расчёта (ГОСТ 6651-2009)</div>`;
            html+=`<div class="converter-result-item"><span class="converter-result-label">Тип ТС</span><span class="converter-result-value">${sd.name}</span></div>`;
            html+=`<div class="converter-result-item"><span class="converter-result-label">Диапазон</span><span class="converter-result-value">${formatNumber(tMin)} … ${formatNumber(tMax)} °C</span></div>`;
            html+=`<div class="converter-result-item"><span class="converter-result-label">R₀ (при 0°C)</span><span class="converter-result-value">${sd.r0} Ом</span></div>`;
            html+=`<div class="converter-result-item"><span class="converter-result-label">Формула</span><span class="converter-result-value">${sd.formula}</span></div>`;
            // Task 374: кнопка «Копировать» над таблицей убрана (заявка);
            // отступ сверху 12px сохранён на самом заголовке
            html+=`<div class="converter-result-label-title" style="margin-top:12px;">Таблица значений (шаг ${formatNumber(step)}°C)</div>`;
            html+=`<div id="tempTableContainer" style="overflow-x:auto;border-radius:10px;border:1px solid rgba(255,255,255,0.05);"><table style="min-width:100%;width:100%;border-collapse:collapse;"><thead><tr style="background:rgba(22,27,34,0.7);"><th style="padding:10px 12px;font-size:13px;color:#4a8fc7;text-align:left;">t, °C</th><th style="padding:10px 12px;font-size:13px;color:#4ac771;text-align:left;">R(t), Ом</th></tr></thead><tbody>`;
            let start=Math.ceil(tMin/step)*step;
            let end=Math.floor(tMax/step)*step;
            if(start>tMax||end<tMin){start=tMin;end=tMax;}
            let row=0;
            for(let tc=start;tc<=end;tc+=step){
                let rv=isCu?calcCuResistance(tc,sd.r0,sd.alpha):calcRtdResistance(tc,sd.r0,sd.nsc);
                let bg=row%2?'rgba(22,27,34,0.4)':'rgba(13,17,23,0.4)';
                html+=`<tr style="background:${bg};"><td style="padding:8px 12px;font-size:14px;color:rgba(255,255,255,0.4);">${formatNumber(tc)}</td><td style="padding:8px 12px;font-size:14px;color:#4ac771;">${formatNumber(rv)}</td></tr>`;
                row++;
            }
            if(row===0){
                let rv=isCu?calcCuResistance(tMin,sd.r0,sd.alpha):calcRtdResistance(tMin,sd.r0,sd.nsc);
                html+=`<tr style="background:rgba(13,17,23,0.4);"><td style="padding:8px 12px;font-size:14px;color:rgba(255,255,255,0.4);">${formatNumber(tMin)}</td><td style="padding:8px 12px;font-size:14px;color:#4ac771;">${formatNumber(rv)}</td></tr>`;
            }
            html+=`</tbody></table></div>`;
            // Task 373: блок «Расчёт произвольных значений» перенесён НАД
            // форму выбора диапазона/шага (статичная панель в колонке
            // ввода) — из результатов удалён
            resDiv.innerHTML=html;
        } else {
            let tcType=sel.tc;
            let names=getTcSensorMap();
            let html=`<div class="converter-result-label-title">Результаты расчёта (ГОСТ Р 8.585-2001)</div>`;
            html+=`<div class="converter-result-item"><span class="converter-result-label">Тип термопары</span><span class="converter-result-value">${names[tcType]}</span></div>`;
            html+=`<div class="converter-result-item"><span class="converter-result-label">Диапазон</span><span class="converter-result-value">${formatNumber(tMin)} … ${formatNumber(tMax)} °C</span></div>`;
            html+=`<div class="converter-result-item"><span class="converter-result-label">E(0°C)</span><span class="converter-result-value">0,000 мВ</span></div>`;
            html+=`<div class="converter-result-item"><span class="converter-result-label">Формула</span><span class="converter-result-value">E = Σ cᵢ·tⁱ (полином НИСТ)</span></div>`;
            // Task 374: кнопка «Копировать» над таблицей убрана (заявка);
            // отступ сверху 12px сохранён на самом заголовке
            html+=`<div class="converter-result-label-title" style="margin-top:12px;">Таблица значений (шаг ${formatNumber(step)}°C)</div>`;
            html+=`<div id="tempTableContainer" style="overflow-x:auto;border-radius:10px;border:1px solid rgba(255,255,255,0.05);"><table style="min-width:100%;width:100%;border-collapse:collapse;"><thead><tr style="background:rgba(22,27,34,0.7);"><th style="padding:10px 12px;font-size:13px;color:#4a8fc7;text-align:left;">t, °C</th><th style="padding:10px 12px;font-size:13px;color:#4ac771;text-align:left;">E(t), мВ</th></tr></thead><tbody>`;
            let start=Math.ceil(tMin/step)*step;
            let end=Math.floor(tMax/step)*step;
            if(start>tMax||end<tMin){start=tMin;end=tMax;}
            let row=0;
            for(let tc=start;tc<=end;tc+=step){
                let ev=calcTcVoltage(tc,tcType);
                let bg=row%2?'rgba(22,27,34,0.4)':'rgba(13,17,23,0.4)';
                html+=`<tr style="background:${bg};"><td style="padding:8px 12px;font-size:14px;color:rgba(255,255,255,0.4);">${formatNumber(tc)}</td><td style="padding:8px 12px;font-size:14px;color:#4ac771;">${formatNumber(ev)}</td></tr>`;
                row++;
            }
            if(row===0){
                let ev=calcTcVoltage(tMin,tcType);
                html+=`<tr style="background:rgba(13,17,23,0.4);"><td style="padding:8px 12px;font-size:14px;color:rgba(255,255,255,0.4);">${formatNumber(tMin)}</td><td style="padding:8px 12px;font-size:14px;color:#4ac771;">${formatNumber(ev)}</td></tr>`;
            }
            html+=`</tbody></table></div>`;
            // Task 373: панель произвольных значений — статичная, над формой
            resDiv.innerHTML=html;
        }
        resDiv.style.display='block';
        setTimeout(()=>resDiv.scrollIntoView({behavior:'smooth',block:'start'}),100);
    }
    function calcRtdResistance(t,r0,nsc){
        if(nsc==='pt1385'){
            let A=3.9083e-3, B=-5.775e-7, C=-4.183e-12;
            if(t>=0){ return r0*(1+A*t+B*t*t); }
            else { return r0*(1+A*t+B*t*t+C*(t-100)*t*t*t); }
        } else if(nsc==='pt1391'){
            // Task 498 (заявка: сверка пределов и корректировка
            // неточностей): коэффициенты выровнены по таблице А.2
            // ГОСТ 6651-2009 (платина W100 = 1,391): A = 3,969·10⁻³,
            // B = −5,841·10⁻⁷; ниже 0 °C добавлен член C·(t−100)·t³
            // с C = −4,330·10⁻¹² (аналогично pt1385). Раньше ниже 0 °C
            // член C не учитывался, а B был округлён до −5,84·10⁻⁷
            // (A = 3,96847·10⁻³) — значения 100П/50П при отрицательных
            // температурах расходились с таблицей А.2: при −200 °C на
            // ~1,05 Ом (18,29 вместо 17,24), при −100 °C на ~0,09 Ом.
            // Контроль сверки с А.2 (R₀ = 100 Ом): −200 → 17,24;
            // −150 → 38,79; −100 → 59,64; −50 → 80,00; 0 → 100,00;
            // 70 → 127,50; 100 → 139,11; 850 → 395,16.
            let A=3.969e-3, B=-5.841e-7, C=-4.330e-12;
            if(t>=0){ return r0*(1+A*t+B*t*t); }
            else { return r0*(1+A*t+B*t*t+C*(t-100)*t*t*t); }
        }
        return r0;
    }
    // Task 499 (заявка: «проверь у 50М (Cu50) α = 0,00428 °C⁻¹
    // диапазон — по моему −180…200 °C»): НСХ меди W100 = 1,428 ниже
    // 0 °C НЕ линейна — формула 5.2.3 ГОСТ 6651-2009: R(t) =
    // R₀·[1 + A·t + B·t·(t+6,7 °C) + C·t³], A = 4,28·10⁻³ °C⁻¹,
    // B = −6,2032·10⁻⁷ °C⁻², C = 8,5154·10⁻¹⁰ °C⁻³ (при t ≥ 0 —
    // линейная R₀(1+At), формула 5.2.3/6). Контроль по таблице А.3
    // ГОСТ (R₀ = 100): −180 → 20,53; −170 → 25,10; −120 → 47,65;
    // −100 → 56,54; −50 → 78,46; 0 → 100,00. Раньше (линейная при
    // любой t) ниже 0 °C расходилась с ГОСТ: при −50 °C +0,14 Ом
    // (78,60 вместо 78,46), при −180 °C +2,43 Ом (22,96 вместо 20,53).
    // Медь W100 = 1,426 (α = 0,00426) в ГОСТ представлена только
    // обратной функцией (прил. Б.3, −50…+200) — для неё НСХ
    // остаётся линейной, ветка ГОСТ не применяется.
    function calcCuResistance(t,r0,alpha){
        // Task 499: ветка формулы 5.2.3 — только α = 0,00428 и t < 0
        if(t<0 && Math.abs(alpha-0.00428)<1e-9){
            let A=4.28e-3, B=-6.2032e-7, C=8.5154e-10;
            return r0*(1+A*t+B*t*(t+6.7)+C*t*t*t);
        }
        return r0*(1+alpha*t);
    }
    function calcTcVoltage(t,type){
        // Все коэффициенты — NIST ITS-90 (SRD 60), в мВ.
        // Полином: E(t) = c0 + c1·t + c2·t² + ... + cn·t^n
        // Коэффициенты записаны от низших степеней к высшим (c0, c1, c2, ...).
        // Источник: NIST Standard Reference Database 60, версия 2.0
        let mv=0;
        if(type==='K'){
            if(t<0){
                let c=[0,3.9450128025e-2,2.3622373598e-5,-3.2858906784e-7,-4.9904828777e-9,-6.7509059173e-11,-5.7410327428e-13,-3.1088872894e-15,-1.0451609365e-17,-1.9889266878e-20,-1.6322697487e-23];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            } else {
                let c=[-1.7600413686e-2,3.8921204975e-2,1.8558770032e-5,-9.9457592874e-8,3.1840945719e-10,-5.6072844889e-13,5.6075059059e-16,-3.2020720003e-19,9.7151147152e-23,-1.2104721275e-26];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
                mv+=1.185976e-1*Math.exp(-1.183432e-4*Math.pow(t-1.269686e2,2));
            }
        } else if(type==='J'){
            if(t>=0){
                let c=[0,5.0381187815e-2,3.0475836930e-5,-8.5681066720e-8,1.3228195295e-10,-1.7052958337e-13,2.0948090697e-16,-1.2538395336e-19,1.5631725697e-23];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            } else {
                let c=[0,5.0381187815e-2,3.0475836930e-5,-8.5681066720e-8,1.3228195295e-10,-1.7052958337e-13,2.0948090697e-16,-1.2538395336e-19,1.5631725697e-23];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            }
        } else if(type==='T'){
            // T (медь-константан): диапазоны -270..0°C и 0..400°C
            if(t>=0){
                // NIST ITS-90, диапазон 0..400°C (9 коэффициентов, степени 0..8)
                let c=[0, 3.8748106364e-2, 3.3292227880e-5, 2.0618243404e-7, -2.1882256846e-9, 1.0996880928e-11, -3.0815758772e-14, 4.5479135290e-17, -2.7512901673e-20];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            } else {
                // NIST ITS-90, диапазон -270..0°C (15 коэффициентов, степени 0..14)
                let c=[0, 3.8748106364e-2, 4.4194434347e-5, 1.1844323105e-7, 2.0032973554e-8, 9.0138019559e-10, 2.2651156593e-11, 3.6071154205e-13, 3.8493939883e-15, 2.8213521925e-17, 1.4251594779e-19, 4.8768662286e-22, 1.0795539270e-24, 1.3945027062e-27, 7.9795153927e-31];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            }
        } else if(type==='N'){
            // N (никросил-нисил): диапазоны -270..0°C и 0..1300°C
            if(t>=0){
                // NIST ITS-90, диапазон 0..1300°C (11 коэффициентов, степени 0..10)
                let c=[0, 2.5929394601e-2, 1.5710141880e-5, 4.3825627237e-8, -2.5261169794e-10, 6.4311819339e-13, -1.0063471519e-15, 9.9745338992e-19, -6.0863245607e-22, 2.0849229339e-25, -3.0682196151e-29];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            } else {
                // NIST ITS-90, диапазон -270..0°C (9 коэффициентов, степени 0..8)
                let c=[0, 2.6159105962e-2, 1.0957484228e-5, -9.3841111554e-8, -4.6412039759e-11, -2.6303357716e-12, -2.2653438003e-14, -7.6089300791e-17, -9.3419667835e-20];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            }
        } else if(type==='E'){
            // E (хромель-константан): диапазоны -270..0°C и 0..1000°C
            if(t>=0){
                // NIST ITS-90, диапазон 0..1000°C (11 коэффициентов, степени 0..10)
                let c=[0, 5.8665508710e-2, 4.5032275582e-5, 2.8908407212e-8, -3.3056896652e-10, 6.5024403270e-13, -1.9197495504e-16, -1.2536600497e-18, 2.1489217569e-21, -1.4388041782e-24, 3.5960899481e-28];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            } else {
                // NIST ITS-90, диапазон -270..0°C (14 коэффициентов)
                let c=[0, 5.8665508708e-2, 4.5410977124e-5, -7.7998048686e-7, -2.5800160843e-8, -5.9452583057e-10, -9.3214058667e-12, -1.0287605534e-13, -8.0370123621e-16, -4.3979497391e-18, -1.6414776355e-20, -3.9673619516e-23, -5.5827328721e-26, -3.4657842013e-29];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            }
        } else if(type==='L'){
            // Task 373: ТХК (L) — хромель-копель, ГОСТ Р 8.585-2001
            // (−200…800 °C). В базе НИСТ (SRD 60) и МЭК 60584 этого типа
            // НЕТ — полиномы аппроксимации подобраны по таблице стандарта
            // (два диапазона, точность лучше 0,001 мВ). Контрольные точки:
            // E(−100)=−5,641; E(100)=6,862; E(500)=40,299; E(800)=66,466 мВ.
            if(t>=0){
                let c=[4.0535830849e-6, 6.3307953909e-2, 6.0231773449e-5, -8.0885846926e-8, 1.0111986656e-10, -4.7710783920e-14, -2.2894088054e-16, 4.1439904615e-19, -2.0259856006e-22];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            } else {
                let c=[1.8620992536e-5, 6.3326208351e-2, 6.0355654401e-5, -8.2356261044e-8, 8.5085309858e-13, -7.0918273232e-13, -1.9410086265e-15];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            }
        } else if(type==='R'){
            // R (платинородий-платина 13%): 3 диапазона
            if(t>=1064.18){
                // NIST ITS-90, диапазон 1064.18..1664.5°C
                let c=[2.9515792532e0, -2.5206125133e-3, 1.5956450187e-5, -7.6408594758e-9, 2.0530529102e-12, -2.9335966817e-16];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            } else if(t>=-50){
                // NIST ITS-90, диапазон -50..1064.18°C (10 коэффициентов)
                let c=[0, 5.2896172977e-3, 1.3916658978e-5, -2.3885569302e-8, 3.5691600106e-11, -4.6234766630e-14, 5.0077744103e-17, -3.7310588619e-20, 1.5771648237e-23, -2.8103862525e-27];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            }
        } else if(type==='S'){
            // S (платинородий-платина 10%): 3 диапазона
            if(t>=1064.18){
                // NIST ITS-90, диапазон 1064.18..1664.5°C (5 коэффициентов)
                let c=[1.3290044409e0, 3.3450931134e-3, 6.5480519282e-6, -1.6485625921e-9, 1.2998960517e-14];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            } else if(t>=-50){
                // NIST ITS-90, диапазон -50..1064.18°C (9 коэффициентов)
                // ВАЖНО: ранее здесь был баг — c1=5.4e-6 вместо 5.4e-3
                let c=[0, 5.4031330863e-3, 1.2593428974e-5, -2.3247796869e-8, 3.2202882304e-11, -3.3146519639e-14, 2.5574425179e-17, -1.2506887139e-20, 2.7144317615e-24];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            }
        } else if(type==='B'){
            // B (платинородий-платинородий 30%/6%): 2 диапазона, начинается с 0°C
            if(t>=630.615){
                // NIST ITS-90, диапазон 630.615..1820°C (9 коэффициентов)
                let c=[-3.8938168621e0, 2.8571747470e-2, -8.4885104785e-5, 1.5785280164e-7, -1.6835344864e-10, 1.1109794013e-13, -4.4515431033e-17, 9.8975640821e-21, -9.3791330289e-25];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            } else {
                // NIST ITS-90, диапазон 0..630.615°C (7 коэффициентов)
                let c=[0, -2.4650818346e-4, 5.9040421171e-6, -1.3257931636e-9, 1.5668291901e-12, -1.6944529240e-15, 6.2990347094e-19];
                let p=1; for(let i=0;i<c.length;i++){ mv+=c[i]*p; p*=t; }
            }
        }
        return mv;
    }

    // Task 371: блок «Расчёт произвольных значений» на странице
    // «Датчики температуры» — под таблицей значений, по примеру
    // раздела «Шкала-сигнал»: живой двусторонний расчёт
    // t ↔ R(t) (ТС) / t ↔ E(t) (ТП) при вводе в любое поле.
    // Карта типов ТС вынесена из calcTempSensor() для переиспользования.
    function getRtdSensorMap(){
        return {
            cu50_1428:{r0:50,alpha:0.00428,name:'50М (Cu50)',nsc:'cu',formula:'R(t) = R₀(1 + 0,00428·t) при t ≥ 0; при t < 0 по ГОСТ 6651-2009 (ф. 5.2.3): R₀[1 + At + Bt(t+6,7 °C) + Ct³]'},
            cu100_1428:{r0:100,alpha:0.00428,name:'100М (Cu100)',nsc:'cu',formula:'R(t) = R₀(1 + 0,00428·t) при t ≥ 0; при t < 0 по ГОСТ 6651-2009 (ф. 5.2.3): R₀[1 + At + Bt(t+6,7 °C) + Ct³]'},
            cu50_1426:{r0:50,alpha:0.00426,name:'50М (Cu50)',nsc:'cu',formula:'R(t) = R₀(1 + 0,00426·t)'},
            cu100_1426:{r0:100,alpha:0.00426,name:'100М (Cu100)',nsc:'cu',formula:'R(t) = R₀(1 + 0,00426·t)'},
            pt50_1391:{r0:50,name:'50П (Pt50)',nsc:'pt1391',formula:'R(t) = R₀[1 + At + Bt² + C(t−100)t³] при t<0; A=3,969·10⁻³, B=−5,841·10⁻⁷, C=−4,330·10⁻¹²'},
            pt100_1391:{r0:100,name:'100П (Pt100)',nsc:'pt1391',formula:'R(t) = R₀[1 + At + Bt² + C(t−100)t³] при t<0; A=3,969·10⁻³, B=−5,841·10⁻⁷, C=−4,330·10⁻¹²'},
            pt100_1385:{r0:100,name:'Pt100 (IEC)',nsc:'pt1385',formula:'R(t) = R₀[1 + At + Bt² + C(t−100)t³], IEC 60751 / ГОСТ 6651-2009'},
            pt1000_1385:{r0:1000,name:'Pt1000 (IEC)',nsc:'pt1385',formula:'R(t) = R₀[1 + At + Bt² + C(t−100)t³], IEC 60751 / ГОСТ 6651-2009'}
        };
    }
    // Task 373: функция tempCustomCalcHtml УДАЛЕНА — панель «Расчёт
    // произвольных значений» стала статичной разметкой страницы датчика
    // ( ts-calc-panel над формой выбора диапазона/шага ); подписи полей
    // под тип датчика задаёт openTempSensor().
    // Task 371/372: диапазоны НСХ по типу датчика — границы применимости
    // формул (и проверка введённых произвольных значений). Task 372:
    // единый источник диапазонов — каталог getTempSensorCatalog();
    // датчик берётся из состояния страницы карточек.
    function getTempSensorRange(){
        let sel=tempSensorFindByKey(tempSensorKey);
        if(sel){ return {min:sel.range.min,max:sel.range.max}; }
        return {min:-50,max:200};
    }
    // Task 371/372: прямое значение по температуре ВЫБРАННОГО датчика
    // (R(t) для ТС, E(t) для ТП) — как queryFromScaleLive читает поля живьём
    function tempCalcForwardValue(t){
        let sel=tempSensorFindByKey(tempSensorKey);
        if(!sel){return null;}
        if(sel.kind==='rtd'){
            let sd=getRtdSensorMap()[sel.key];
            if(!sd){return null;}
            return sd.nsc==='cu'?calcCuResistance(t,sd.r0,sd.alpha):calcRtdResistance(t,sd.r0,sd.nsc);
        }
        return calcTcVoltage(t,sel.tc);
    }
    // Task 371: температура по значению R/E — обращение монотонной
    // характеристики НСХ бисекцией (аналитически не обращается:
    // у Pt ниже 0°C член C, у ТП — полиномы высоких степеней)
    function tempCalcInvertValue(v){
        let rng=getTempSensorRange();
        let f=function(t){return tempCalcForwardValue(t);};
        let vmin=f(rng.min),vmax=f(rng.max);
        if(v===null||isNaN(v)||v<vmin-1e-9||v>vmax+1e-9){return null;}
        let lo=rng.min,hi=rng.max;
        for(let i=0;i<80;i++){
            let mid=(lo+hi)/2;
            if(f(mid)<v){lo=mid;}else{hi=mid;}
        }
        return (lo+hi)/2;
    }
    // Task 496 (заявка): в блоке произвольного расчёта кнопка подтверждения
    // («Готово»/Enter) мобильной клавиатуры ЗАКРЫВАЕТ клавиатуру, а не
    // перескакивает на следующее поле: у поля температуры был
    // enterkeyhint="next" (кнопка «Далее» вела в поле значения) — оба поля
    // переведены на enterkeyhint="done", Enter гасится и снимает фокус
    // (preventDefault + blur: клавиатура закрывается и на iOS, где «done»
    // сам по себе клавиатуру не убирает, и на Android). ВАЖНО:
    // stopPropagation — ППР-поля выходят из ГЛОБАЛЬНОГО обработчика
    // Enter/Next («логичный переход между полями», document keydown):
    // без него после blur событие всплывает, глобальный handler ставит
    // фокус в следующее поле и клавиатура не закрывается. Глобальный
    // переход в остальных блоках — без изменений. Живой двусторонний
    // расчёт по oninput (Task 371) не меняется.
    function tempQueryEnterBlur(e, el){
        if(!e){return;}
        if(e.key==='Enter'||e.keyCode===13){
            e.preventDefault();
            if(e.stopPropagation){e.stopPropagation();}
            if(el&&typeof el.blur==='function'){el.blur();}
        }
    }
    // Task 502 (заявка): Enter в полях произвольных значений
    // «Шкала-сигнал» — ЗАКРЫВАЕТ клавиатуру (blur), а НЕ переходит на
    // следующее поле: обёртка над tempQueryEnterBlur (Task 496) —
    // preventDefault + stopPropagation, глобальный Enter/Next
    // (переход к следующему полю) не срабатывает.
    function scaleQueryEnterBlur(e, el){ tempQueryEnterBlur(e, el); }
    // Task 371: живой расчёт «температура → R/E» (ввод в поле температуры)
    function tempQueryFromTemp(){
        let tEl=document.getElementById('tempQueryTemp');
        let vEl=document.getElementById('tempQueryVal');
        if(!tEl||!vEl){return;}
        let t=parseLocaleNumber(tEl.value);
        if(isNaN(t)){vEl.value='';return;}
        let rng=getTempSensorRange();
        if(t<rng.min||t>rng.max){
            vEl.value='';
            showToast('Температура вне диапазона НСХ ('+formatNumber(rng.min)+' … '+formatNumber(rng.max)+' °C)');
            return;
        }
        let val=tempCalcForwardValue(t);
        if(val===null){vEl.value='';return;}
        vEl.value=formatNumber(val);
    }
    // Task 371: живой расчёт «R/E → температура» (ввод в поле значения)
    function tempQueryFromValue(){
        let tEl=document.getElementById('tempQueryTemp');
        let vEl=document.getElementById('tempQueryVal');
        if(!tEl||!vEl){return;}
        let v=parseLocaleNumber(vEl.value);
        if(isNaN(v)){tEl.value='';return;}
        // Task 372: единица — по выбранному датчику (карточка), а не select
        let selQ=tempSensorFindByKey(tempSensorKey);
        let unit=(selQ&&selQ.kind==='rtd')?'Ом':'мВ';
        let rng=getTempSensorRange();
        let f=function(t){return tempCalcForwardValue(t);};
        let vmin=f(rng.min),vmax=f(rng.max);
        if(v<vmin-1e-9||v>vmax+1e-9){
            tEl.value='';
            showToast('Значение вне диапазона НСХ ('+formatNumber(vmin)+' … '+formatNumber(vmax)+' '+unit+')');
            return;
        }
        let t=tempCalcInvertValue(v);
        if(t===null){tEl.value='';return;}
        tEl.value=formatNumber(t);
    }

    // DOMContentLoaded
    
    // Автоматический выключатель — адаптирован для КИП, АСУ ТП, малой мощности, 12-36 В
    const cbCableDataKip = {
        cu: {
            0.5: { Ik: 11, Imax: 6, desc: 'сигнальные цепи, датчики' },
            0.75: { Ik: 15, Imax: 10, desc: '4-20 мА, термопары, ТС' },
            1.0: { Ik: 17, Imax: 10, desc: 'питание 24 В DC, клапана' },
            1.5: { Ik: 23, Imax: 16, desc: 'группа приборов 220 В' },
            2.5: { Ik: 30, Imax: 25, desc: 'силовая линия, щит' },
            4: { Ik: 41, Imax: 32, desc: 'щит питания АСУ ТП' },
            6: { Ik: 50, Imax: 40, desc: 'главный ввод' }
        },
        al: {
            0.5: { Ik: 8, Imax: 4, desc: 'не рекомендуется для КИП' },
            0.75: { Ik: 11, Imax: 6, desc: 'не рекомендуется для КИП' },
            1.0: { Ik: 13, Imax: 10, desc: 'временные линии' },
            1.5: { Ik: 17, Imax: 10, desc: 'освещение' },
            2.5: { Ik: 23, Imax: 16, desc: 'силовая линия' },
            4: { Ik: 30, Imax: 25, desc: 'щит' },
            6: { Ik: 38, Imax: 32, desc: 'главный ввод' }
        }
    };
    const cbStandardSeriesKip = [0.5, 1, 2, 3, 4, 6, 8, 10, 13, 16, 20, 25, 32, 40, 50, 63];
    const cbConsumerProfiles = {
        kip_resistive: { cosphi: 1.0, inrush: 1.0, desc: 'активная нагрузка' },
        kip_inductive: { cosphi: 0.7, inrush: 3.0, desc: 'клапана, реле, соленоиды' },
        asutp_controller: { cosphi: 0.95, inrush: 1.2, desc: 'контроллер + модули' },
        asutp_actuator: { cosphi: 0.75, inrush: 5.0, desc: 'исполнительные механизмы' },
        mixed: { cosphi: 0.85, inrush: 2.0, desc: 'смешанная нагрузка' },
        custom: { cosphi: null, inrush: null, desc: 'пользовательские параметры' }
    };
    const cbSupplyProfiles = {
        ac220: { U: 220, type: 'AC', desc: '~220 В' },
        dc24: { U: 24, type: 'DC', desc: '=24 В' },
        dc12: { U: 12, type: 'DC', desc: '=12 В' },
        dc36: { U: 36, type: 'DC', desc: '=36 В' },
        ac24: { U: 24, type: 'AC', desc: '~24 В' },
        ac36: { U: 36, type: 'AC', desc: '~36 В' },
        custom: { U: null, type: null, desc: 'своё' }
    };
    function getCbCableDataKip(lineType, customSection, customMaterial) {
        let preset = {
            signal_0_75: { mat: 'cu', sec: 0.75 },
            power_1_0: { mat: 'cu', sec: 1.0 },
            power_1_5: { mat: 'cu', sec: 1.5 },
            power_2_5: { mat: 'cu', sec: 2.5 }
        };
        let mat = lineType === 'custom' ? customMaterial : preset[lineType].mat;
        let sec = lineType === 'custom' ? parseLocaleNumber(customSection) : preset[lineType].sec;
        return { material: mat, section: sec, data: cbCableDataKip[mat][sec] };
    }
    function nearestCbStandardKip(val) {
        for (let i = 0; i < cbStandardSeriesKip.length; i++) {
            if (cbStandardSeriesKip[i] >= val) return cbStandardSeriesKip[i];
        }
        return cbStandardSeriesKip[cbStandardSeriesKip.length - 1];
    }
    function updateCbForm() {
        let loadType = document.getElementById('cb_load_type').value;
        document.getElementById('cb_power_block').style.display = loadType === 'power' ? 'block' : 'none';
        document.getElementById('cb_current_block').style.display = loadType === 'current' ? 'block' : 'none';
        let supply = document.getElementById('cb_supply_type').value;
        document.getElementById('cb_custom_voltage_block').style.display = supply === 'custom' ? 'block' : 'none';
    }
    function updateCbCosPhi() {
        let consumer = document.getElementById('cb_consumer_type').value;
        document.getElementById('cb_custom_cosphi_block').style.display = consumer === 'custom' ? 'block' : 'none';
    }
    function updateCbCableTable() {
        let lineType = document.getElementById('cb_line_type').value;
        document.getElementById('cb_custom_cable').style.display = lineType === 'custom' ? 'block' : 'none';
    }
    function calcCircuitBreaker() {
        let supplyType = document.getElementById('cb_supply_type').value;
        let loadType = document.getElementById('cb_load_type').value;
        let consumerType = document.getElementById('cb_consumer_type').value;
        let lineType = document.getElementById('cb_line_type').value;
        let curve = document.getElementById('cb_curve').value;
        let deviceCount = parseInt(document.getElementById('cb_device_count').value) || 1;
        let customSection = document.getElementById('cb_cable_section') ? document.getElementById('cb_cable_section').value : '0.75';
        let customMaterial = document.getElementById('cb_cable_material') ? document.getElementById('cb_cable_material').value : 'cu';

        // Supply profile
        let supply = cbSupplyProfiles[supplyType];
        let U;
        if (supplyType === 'custom') {
            U = parseLocaleNumber(document.getElementById('cb_custom_voltage').value);
            if (isNaN(U) || U <= 0) { showToast('Введите напряжение питания'); return; }
        } else {
            U = supply.U;
        }

        // Consumer profile
        let consumer = cbConsumerProfiles[consumerType];
        let cosphi, inrush;
        if (consumerType === 'custom') {
            cosphi = parseLocaleNumber(document.getElementById('cb_custom_cosphi').value);
            inrush = parseLocaleNumber(document.getElementById('cb_inrush_factor').value);
            if (isNaN(cosphi) || cosphi <= 0 || cosphi > 1) { showToast('cos φ должен быть 0,1…1,0'); return; }
            if (isNaN(inrush) || inrush < 1) { showToast('Кпуск ≥ 1,0'); return; }
        } else {
            cosphi = consumer.cosphi;
            inrush = consumer.inrush;
        }

        // Calculate current
        let Icalc;
        if (loadType === 'power') {
            let P = parseLocaleNumber(document.getElementById('cb_power').value);
            let unitMult = parseLocaleNumber(document.getElementById('cb_power_unit').value);
            if (isNaN(P) || P <= 0) { showToast('Введите мощность'); return; }
            P = P * unitMult * deviceCount;
            Icalc = P / (U * cosphi);
        } else {
            Icalc = parseLocaleNumber(document.getElementById('cb_current').value);
            if (isNaN(Icalc) || Icalc <= 0) { showToast('Введите ток'); return; }
            Icalc = Icalc * deviceCount;
        }

        // Cable data
        let cable = getCbCableDataKip(lineType, customSection, customMaterial);
        let In_min = Icalc * 1.25; // Запас 25% для КИП
        let Ina = nearestCbStandardKip(In_min);
        let Ina_inrush = nearestCbStandardKip(Icalc * inrush / (curve === 'B' ? 3 : curve === 'C' ? 5 : curve === 'D' ? 10 : 2));
        if (Ina_inrush > Ina) Ina = Ina_inrush;

        let warning = '';
        if (Ina > cable.data.Imax) {
            warning = `Выбранный автомат ${formatNumber(Ina)} А превышает допустимый ток для кабеля ${formatNumber(cable.section)} мм² (${formatNumber(cable.data.Imax)} А). Увеличьте сечение кабеля.`;
        }
        if (Ina < 0.5) {
            warning += (warning ? '<br>' : '') + `Расчётный ток ${formatNumber(Icalc)} А очень мал. Рекомендуется применять предохранители или защиту в составе БП.`;
        }

        let Pmax = Ina * U * cosphi;
        let I_inrush = Icalc * inrush;

        let html = '<div class="converter-result-label-title">Результаты расчёта (КИП и А / АСУ ТП)</div>';
        html += `<div class="converter-result-item"><span class="converter-result-label">Напряжение питания</span><span class="converter-result-value">${supplyType === 'custom' ? (document.getElementById('cb_custom_voltage_type').value === 'dc' ? '=' : '~') + formatNumber(U) + ' В' : supply.desc}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Тип нагрузки</span><span class="converter-result-value">${consumer.desc}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">cos φ / Кпуск</span><span class="converter-result-value">${formatNumber(cosphi)} / ${formatNumber(inrush)}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Расчётный ток Iр</span><span class="converter-result-value">${formatNumber(Icalc)} А</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Пусковой ток Iпуск</span><span class="converter-result-value">${formatNumber(I_inrush)} А</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Кабель</span><span class="converter-result-value">${cable.material === 'cu' ? 'медь' : 'алюминий'} ${formatNumber(cable.section)} мм² · ${formatNumber(cable.data.Imax)} А · ${cable.data.desc}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Макс. автомат для кабеля</span><span class="converter-result-value">${formatNumber(cable.data.Imax)} А</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Рекомендуемый автомат</span><span class="converter-result-value" style="color:#4ac771; font-size:14px;">${curve}${formatNumber(Ina)}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Макс. мощность</span><span class="converter-result-value">${formatNumber(Pmax)} Вт (${formatNumber(Pmax/1000)} кВт)</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Количество приборов</span><span class="converter-result-value">${deviceCount} шт.</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Формула</span><span class="converter-result-value">I = P/(U·cos φ) · Кзапаса 1,25</span></div>`;

        if (warning) {
            html += `<div class="warning-banner" style="margin:10px 0 0;"><div class="warning-icon"><svg viewBox="0 0 24 24"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg></div><div class="warning-banner-content"><div class="warning-banner-title">Рекомендации</div><div class="warning-banner-desc">${warning}</div></div></div>`;
        }

        document.getElementById('cbResults').innerHTML = html;
        document.getElementById('cbResults').style.display = 'block';
        setTimeout(() => document.getElementById('cbResults').scrollIntoView({ behavior: 'smooth', block: 'start' }), 100);
    }

    // ===== СУЖАЮЩЕЕ УСТРОЙСТВО (ДИАФРАГМА) — вспомогательные функции =====
    const opAlphaCoefficients = {
        orifice: { A: 0.5959, B: 0.0312, C: -0.1840, D: 0.0390 },
        nozzle: { A: 0.9965, B: 0.0105, C: -0.0420, D: 0.0085 },
        venturi: { A: 0.9840, B: 0.0050, C: -0.0150, D: 0.0030 }
    };
    const opThermalExpansion = {
        steel20: 11.9e-6,
        steel12x18h10t: 16.6e-6,
        steel15x5m: 11.5e-6,
        brass: 18.9e-6,
        bronze: 17.6e-6
    };
    function updateOpForm() {
        let type = document.getElementById('op_medium_type');
        if (type) {
            let gasParams = document.getElementById('op_gas_params');
            if (gasParams) gasParams.style.display = type.value === 'gas' ? 'block' : 'none';
        }
    }
    function updateOpDpForm() {
        let type = document.getElementById('op_dp_medium_type');
        if (type) {
            let gasParams = document.getElementById('op_dp_gas_params');
            if (gasParams) gasParams.style.display = type.value === 'gas' ? 'block' : 'none';
        }
    }
    function updateOpFlowForm() {
        let type = document.getElementById('op_flow_medium_type');
        if (type) {
            let gasParams = document.getElementById('op_flow_gas_params');
            if (gasParams) gasParams.style.display = type.value === 'gas' ? 'block' : 'none';
        }
    }
    function getOpAlpha(m, device) {
        let coeff = opAlphaCoefficients[device];
        return coeff.A + coeff.B * m + coeff.C * m * m + coeff.D * m * m * m;
    }
    function getOpEpsilon(m, dp_Pa, pressure_abs, kappa, medium) {
        if (medium !== 'gas') return 1.0;
        let tau = dp_Pa / pressure_abs;
        let eps = 1 - (0.41 + 0.35 * Math.pow(m, 1.5)) * tau / kappa;
        return eps < 0.9 ? 0.9 : eps;
    }
    function convertOpFlowToM3s(flow, unit, rho) {
        switch(unit) {
            case 'm3h': return flow / 3600;
            case 'm3s': return flow;
            case 'l_s': return flow / 1000;
            case 'kg_h': return flow / (3600 * rho);
            case 'kg_s': return flow / rho;
            case 't_h': return flow * 1000 / (3600 * rho);
            default: return flow / 3600;
        }
    }
    function convertOpDpToPa(dp, unit) {
        switch(unit) {
            case 'kPa': return dp * 1000;
            case 'Pa': return dp;
            case 'MPa': return dp * 1e6;
            case 'mmH2O': return dp * 9.80665;
            case 'mmHg': return dp * 133.322;
            case 'bar': return dp * 1e5;
            default: return dp * 1000;
        }
    }

    // ============================================================
    // Быстрый расчёт диафрагмы (#9)
    // ============================================================
    // Упрощённая формула для прикидочной оценки перепада давления
    // на стандартной диафрагме без полного расчёта по ГОСТ 26969-86.
    //
    // Формула: Δp = (ρ · Q²) / (2 · α² · β⁴ · A²)
    //   где:
    //     ρ — плотность среды, кг/м³
    //     Q — объёмный расход, м³/с
    //     α — коэффициент расхода (для стандартной диафрагмы ≈ 0.62)
    //     β — относительный диаметр (d/D), безразмерный
    //     A — площадь сечения трубы, м² = π·D²/4
    //
    // Возвращает перепад в Па. Для отображения конвертирует в кПа и мм вод.ст.
    // ============================================================

    // Дефолтные плотности для разных сред (при нормальных условиях)
    const OQ_DEFAULT_RHO = {
        water: 1000,    // кг/м³
        air: 1.293,     // кг/м³ при 0°C, 101.325 кПа
        steam: 0.590,   // кг/м³ (насыщенный пар при 100°C)
        gas: 0.800      // кг/м³ (приблизительно для природного газа)
    };

    // Обновление плотности при смене типа среды
    function updateOqMediumDefaults() {
        const medium = document.getElementById('oq_medium').value;
        const rhoInput = document.getElementById('oq_rho');
        if (rhoInput && OQ_DEFAULT_RHO[medium]) {
            rhoInput.value = OQ_DEFAULT_RHO[medium];
            clearFieldError(rhoInput);
        }
    }

    // Перевод расхода в м³/с (использует существующую convertOpFlowToM3s
    // с учётом плотности для массовых единиц)
    function oqFlowToM3s(flow, unit, rho) {
        // lmin → л/мин, нет в convertOpFlowToM3s — добавим обработку
        if (unit === 'lmin') {
            return flow / 60000;  // 1 л/мин = 0.001/60 м³/с
        }
        return convertOpFlowToM3s(flow, unit, rho);
    }

    // Главная функция быстрого расчёта
    function calcOrificeQuick() {
        const flow = parseLocaleNumber(document.getElementById('oq_flow').value);
        const flowUnit = document.getElementById('oq_flow_unit').value;
        const dPipe_mm = parseLocaleNumber(document.getElementById('oq_d_pipe').value);
        const beta = parseLocaleNumber(document.getElementById('oq_beta').value);
        const rho = parseLocaleNumber(document.getElementById('oq_rho').value);

        // Валидация
        if (isNaN(flow) || flow <= 0) { showToast('Введите расход'); return; }
        if (isNaN(dPipe_mm) || dPipe_mm <= 0) { showToast('Введите диаметр трубы'); return; }
        if (isNaN(beta) || beta <= 0 || beta >= 1) { showToast('β должно быть в диапазоне 0–1'); return; }
        if (isNaN(rho) || rho <= 0) { showToast('Введите плотность среды'); return; }

        // Проверяем ошибки валидации в форме
        if (hasValidationErrors(document.getElementById('page-orifice-quick'))) {
            showToast('Исправьте ошибки в полях');
            return;
        }

        // Константы
        const ALPHA = 0.62;  // коэффициент расхода для стандартной диафрагмы
        const dPipe_m = dPipe_mm / 1000;  // мм → м
        const area = Math.PI * dPipe_m * dPipe_m / 4;  // площадь трубы, м²

        // Перевод расхода в м³/с
        const q_m3s = oqFlowToM3s(flow, flowUnit, rho);

        // Расчёт перепада давления по упрощённой формуле
        // Δp = (ρ · Q²) / (2 · α² · β⁴ · A²)
        const dp_pa = (rho * q_m3s * q_m3s) / (2 * ALPHA * ALPHA * Math.pow(beta, 4) * area * area);

        // Диаметр диафрагмы (для справки)
        const d_orifice_mm = dPipe_mm * beta;

        // Перевод в удобные единицы
        const dp_kpa = dp_pa / 1000;
        const dp_mmh2o = dp_pa / 9.80665;
        const dp_bar = dp_pa / 1e5;

        // Скорость в трубе (для справки)
        const v_pipe = q_m3s / area;  // м/с

        // Формирование результата
        const mediumNames = {
            water: 'Вода',
            air: 'Воздух',
            steam: 'Пар (насыщенный)',
            gas: 'Природный газ'
        };
        const medium = document.getElementById('oq_medium').value;

        let html = '<div class="converter-result-label-title">Результаты прикидочного расчёта</div>';
        html += '<div class="converter-result-item"><span class="converter-result-label">Среда</span><span class="converter-result-value">' + mediumNames[medium] + '</span></div>';
        html += '<div class="converter-result-item"><span class="converter-result-label">Расход Q</span><span class="converter-result-value">' + formatNumber(flow) + ' ' + flowUnit + '</span></div>';
        html += '<div class="converter-result-item"><span class="converter-result-label">Объёмный расход (в СИ)</span><span class="converter-result-value">' + formatNumber(q_m3s) + ' м³/с</span></div>';
        html += '<div class="converter-result-item"><span class="converter-result-label">Диаметр трубы D</span><span class="converter-result-value">' + formatNumber(dPipe_mm) + ' мм</span></div>';
        html += '<div class="converter-result-item"><span class="converter-result-label">Относительный диаметр β</span><span class="converter-result-value">' + formatNumber(beta) + '</span></div>';
        html += '<div class="converter-result-item"><span class="converter-result-label">Диаметр диафрагмы d = β·D</span><span class="converter-result-value">' + formatNumber(d_orifice_mm) + ' мм</span></div>';
        html += '<div class="converter-result-item"><span class="converter-result-label">Скорость в трубе v</span><span class="converter-result-value">' + formatNumber(v_pipe) + ' м/с</span></div>';
        html += '<div class="converter-result-item" style="margin-top:10px; padding-top:10px; border-top:1px solid var(--card-border);"><span class="converter-result-label">Перепад Δp (Па)</span><span class="converter-result-value" style="color:#4ac771;">' + formatNumber(dp_pa) + ' Па</span></div>';
        html += '<div class="converter-result-item"><span class="converter-result-label">Перепад Δp (кПа)</span><span class="converter-result-value" style="color:#4ac771;">' + formatNumber(dp_kpa) + ' кПа</span></div>';
        if (dp_mmh2o < 100000) {
            html += '<div class="converter-result-item"><span class="converter-result-label">Перепад Δp (мм вод.ст.)</span><span class="converter-result-value" style="color:#4ac771;">' + formatNumber(dp_mmh2o) + ' мм вод.ст.</span></div>';
        }
        if (dp_bar > 0.001) {
            html += '<div class="converter-result-item"><span class="converter-result-label">Перепад Δp (бар)</span><span class="converter-result-value" style="color:#4ac771;">' + formatNumber(dp_bar) + ' бар</span></div>';
        }

        // Информация о формуле
        html += '<div style="margin-top:14px; padding:14px 18px; background:rgba(13,17,23,0.5); border-radius:10px; font-size:13px; color:rgba(255,255,255,0.45); line-height:1.6;">';
        html += '<b style="color:rgba(255,255,255,0.7);">Формула:</b> Δp = (ρ · Q²) / (2 · α² · β⁴ · A²)<br>';
        html += '<b style="color:rgba(255,255,255,0.7);">Параметры:</b> α = 0.62 (коэффициент расхода), A = π·D²/4 = ' + formatNumber(area) + ' м²<br>';
        html += '<b style="color:rgba(255,255,255,0.7);">Подставлено:</b> Δp = (' + formatNumber(rho) + ' · ' + formatNumber(q_m3s) + '²) / (2 · 0.62² · ' + formatNumber(beta) + '⁴ · ' + formatNumber(area) + '²) = ' + formatNumber(dp_pa) + ' Па';
        html += '</div>';

        // Предупреждение о точности
        html += '<div style="margin-top:10px; padding:12px 14px; background:rgba(199,150,74,0.10); border:1px solid rgba(199,150,74,0.25); border-radius:10px; font-size:12px; color:#c7964a; line-height:1.5;">';
        html += '<b>⚠ Прикидочный расчёт.</b> Результат — оценка. Для точного расчёта по ГОСТ 26969-86 используйте раздел «Перепад давления». Упрощённая формула не учитывает: температурные поправки, шероховатость трубы, сжимаемость газов, поправки на вязкость.';
        html += '</div>';

        const results = document.getElementById('oq_results');
        results.innerHTML = html;
        results.style.display = 'block';
        setTimeout(() => results.scrollIntoView({ behavior: 'smooth', block: 'start' }), 100);
    }
    function getOpThermalD(d20_mm, material, temp) {
        let alpha = opThermalExpansion[material] || 11.9e-6;
        return d20_mm / 1000 * (1 + alpha * (temp - 20));
    }

    // Расчёт перепада давления Δp по Q и d₂₀
    function calcOrificeDp() {
        let medium = document.getElementById('op_dp_medium_type').value;
        let d20_mm = parseLocaleNumber(document.getElementById('op_dp_d20').value);
        let pipeMat = document.getElementById('op_dp_pipe_material').value;
        let temp = parseLocaleNumber(document.getElementById('op_dp_temp').value);
        let flow = parseLocaleNumber(document.getElementById('op_dp_flow').value);
        let flowUnit = document.getElementById('op_dp_flow_unit').value;
        let d_plate_mm = parseLocaleNumber(document.getElementById('op_dp_d_plate').value);
        let rho = parseLocaleNumber(document.getElementById('op_dp_density').value);
        let nu_cSt = parseLocaleNumber(document.getElementById('op_dp_viscosity').value);
        let device = document.getElementById('op_dp_device_type').value;
        let plateMat = document.getElementById('op_dp_plate_material').value;
        let pressure = parseLocaleNumber(document.getElementById('op_dp_pressure').value) || 0;

        if (isNaN(d20_mm) || d20_mm <= 0) { showToast('Введите диаметр трубопровода'); return; }
        if (isNaN(flow) || flow <= 0) { showToast('Введите расход'); return; }
        if (isNaN(d_plate_mm) || d_plate_mm <= 0) { showToast('Введите диаметр диска'); return; }
        if (isNaN(rho) || rho <= 0) { showToast('Введите плотность'); return; }
        if (isNaN(nu_cSt) || nu_cSt <= 0) { showToast('Введите вязкость'); return; }
        if (d_plate_mm >= d20_mm) { showToast('Диаметр диска должен быть меньше диаметра трубы'); return; }

        let D = getOpThermalD(d20_mm, pipeMat, temp);
        let d = d_plate_mm / 1000 * (1 + (opThermalExpansion[plateMat] || 16.6e-6) * (temp - 20));
        let m = (d / D) * (d / D);
        let Q_m3s = convertOpFlowToM3s(flow, flowUnit, rho);
        let alpha = getOpAlpha(m, device);
        let kappa = medium === 'gas' ? (parseLocaleNumber(document.getElementById('op_dp_kappa').value) || 1.4) : 1.0;
        let Z = medium === 'gas' ? (parseLocaleNumber(document.getElementById('op_dp_z').value) || 1.0) : 1.0;
        let pressure_abs = pressure * 1e6 + 101325;

        let epsilon = getOpEpsilon(m, 25000, pressure_abs, kappa, medium);
        let dp_Pa;
        for (let iter = 0; iter < 20; iter++) {
            let denom = alpha * epsilon * (Math.PI * D * D / 4) * Math.sqrt(2 / rho) * m;
            dp_Pa = Math.pow(Q_m3s / denom, 2);
            let eps_new = getOpEpsilon(m, dp_Pa, pressure_abs, kappa, medium);
            if (Math.abs(eps_new - epsilon) < 0.0001) break;
            epsilon = eps_new;
        }

        let ReD = (4 * Q_m3s) / (Math.PI * D * nu_cSt * 1e-6);
        let dp_kPa = dp_Pa / 1000;
        let dp_mmH2O = dp_Pa / 9.80665;

        let warnings = [];
        if (m < 0.05) warnings.push('m < 0,05 — ниже рекомендуемого диапазона');
        if (m > 0.64) warnings.push('m > 0,64 — превышает рекомендуемый диапазон');
        if (ReD < 1e5) warnings.push('ReD < 10⁵ — возможна зависимость α от Re');
        if (dp_Pa > 0.25 * pressure_abs) warnings.push('Δp > 0,25·P — применение формулы ограничено');

        let deviceNames = { orifice: 'Диафрагма стандартная', nozzle: 'Сопло стандартное', venturi: 'Труба Вентури' };
        let html = '<div class="converter-result-label-title">Результаты расчёта Δp (РД 50-411-83)</div>';
        html += `<div class="converter-result-item"><span class="converter-result-label">Тип СУ</span><span class="converter-result-value">${deviceNames[device]}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Расход Q</span><span class="converter-result-value">${formatNumber(Q_m3s * 3600)} м³/ч</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Диаметр диска d₂₀</span><span class="converter-result-value">${formatNumber(d_plate_mm)} мм</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Относительное отверстие m</span><span class="converter-result-value">${formatNumber(m)}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Коэффициент расхода α</span><span class="converter-result-value">${formatNumber(alpha)}</span></div>`;
        if (medium === 'gas') {
            html += `<div class="converter-result-item"><span class="converter-result-label">Коэффициент расширения ε</span><span class="converter-result-value">${formatNumber(epsilon)}</span></div>`;
        }
        html += `<div class="converter-result-item"><span class="converter-result-label">Число ReD</span><span class="converter-result-value">${formatNumber(ReD)}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Перепад Δp</span><span class="converter-result-value" style="color:#4ac771; font-size:14px;">${formatNumber(dp_kPa)} кПа</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Перепад Δp</span><span class="converter-result-value">${formatNumber(dp_mmH2O)} мм вод.ст.</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Перепад Δp</span><span class="converter-result-value">${formatNumber(dp_Pa)} Па</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Формула</span><span class="converter-result-value">Δp = ρ/2 · [Q/(α·ε·(πD²/4)·m)]²</span></div>`;

        if (warnings.length > 0) {
            html += `<div class="warning-banner" style="margin:10px 0 0;"><div class="warning-icon"><svg viewBox="0 0 24 24"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg></div><div class="warning-banner-content"><div class="warning-banner-title">Рекомендации</div><div class="warning-banner-desc">${warnings.join('<br>')}</div></div></div>`;
        }

        document.getElementById('opResultsDp').innerHTML = html;
        document.getElementById('opResultsDp').style.display = 'block';
        setTimeout(() => document.getElementById('opResultsDp').scrollIntoView({ behavior: 'smooth', block: 'start' }), 100);
    }

    // Расчёт расхода Q по Δp и d₂₀
    function calcOrificeFlow() {
        let medium = document.getElementById('op_flow_medium_type').value;
        let d20_mm = parseLocaleNumber(document.getElementById('op_flow_d20').value);
        let pipeMat = document.getElementById('op_flow_pipe_material').value;
        let temp = parseLocaleNumber(document.getElementById('op_flow_temp').value);
        let dp = parseLocaleNumber(document.getElementById('op_flow_dp').value);
        let dpUnit = document.getElementById('op_flow_dp_unit').value;
        let d_plate_mm = parseLocaleNumber(document.getElementById('op_flow_d_plate').value);
        let rho = parseLocaleNumber(document.getElementById('op_flow_density').value);
        let nu_cSt = parseLocaleNumber(document.getElementById('op_flow_viscosity').value);
        let device = document.getElementById('op_flow_device_type').value;
        let plateMat = document.getElementById('op_flow_plate_material').value;
        let pressure = parseLocaleNumber(document.getElementById('op_flow_pressure').value) || 0;

        if (isNaN(d20_mm) || d20_mm <= 0) { showToast('Введите диаметр трубопровода'); return; }
        if (isNaN(dp) || dp <= 0) { showToast('Введите перепад давления'); return; }
        if (isNaN(d_plate_mm) || d_plate_mm <= 0) { showToast('Введите диаметр диска'); return; }
        if (isNaN(rho) || rho <= 0) { showToast('Введите плотность'); return; }
        if (isNaN(nu_cSt) || nu_cSt <= 0) { showToast('Введите вязкость'); return; }
        if (d_plate_mm >= d20_mm) { showToast('Диаметр диска должен быть меньше диаметра трубы'); return; }

        let D = getOpThermalD(d20_mm, pipeMat, temp);
        let d = d_plate_mm / 1000 * (1 + (opThermalExpansion[plateMat] || 16.6e-6) * (temp - 20));
        let m = (d / D) * (d / D);
        let dp_Pa = convertOpDpToPa(dp, dpUnit);
        let alpha = getOpAlpha(m, device);
        let kappa = medium === 'gas' ? (parseLocaleNumber(document.getElementById('op_flow_kappa').value) || 1.4) : 1.0;
        let Z = medium === 'gas' ? (parseLocaleNumber(document.getElementById('op_flow_z').value) || 1.0) : 1.0;
        let pressure_abs = pressure * 1e6 + 101325;
        let epsilon = getOpEpsilon(m, dp_Pa, pressure_abs, kappa, medium);

        let Q_m3s = alpha * epsilon * (Math.PI * D * D / 4) * Math.sqrt(2 * dp_Pa / rho) * m;
        let ReD = (4 * Q_m3s) / (Math.PI * D * nu_cSt * 1e-6);

        let warnings = [];
        if (m < 0.05) warnings.push('m < 0,05 — ниже рекомендуемого диапазона');
        if (m > 0.64) warnings.push('m > 0,64 — превышает рекомендуемый диапазон');
        if (ReD < 1e5) warnings.push('ReD < 10⁵ — возможна зависимость α от Re');
        if (dp_Pa > 0.25 * pressure_abs) warnings.push('Δp > 0,25·P — применение формулы ограничено');

        let deviceNames = { orifice: 'Диафрагма стандартная', nozzle: 'Сопло стандартное', venturi: 'Труба Вентури' };
        let html = '<div class="converter-result-label-title">Результаты расчёта Q (РД 50-411-83)</div>';
        html += `<div class="converter-result-item"><span class="converter-result-label">Тип СУ</span><span class="converter-result-value">${deviceNames[device]}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Перепад Δp</span><span class="converter-result-value">${formatNumber(dp_Pa / 1000)} кПа</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Диаметр диска d₂₀</span><span class="converter-result-value">${formatNumber(d_plate_mm)} мм</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Относительное отверстие m</span><span class="converter-result-value">${formatNumber(m)}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Коэффициент расхода α</span><span class="converter-result-value">${formatNumber(alpha)}</span></div>`;
        if (medium === 'gas') {
            html += `<div class="converter-result-item"><span class="converter-result-label">Коэффициент расширения ε</span><span class="converter-result-value">${formatNumber(epsilon)}</span></div>`;
        }
        html += `<div class="converter-result-item"><span class="converter-result-label">Число ReD</span><span class="converter-result-value">${formatNumber(ReD)}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Расход Q</span><span class="converter-result-value" style="color:#4ac771; font-size:14px;">${formatNumber(Q_m3s * 3600)} м³/ч</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Расход Q</span><span class="converter-result-value">${formatNumber(Q_m3s)} м³/с</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Расход Q</span><span class="converter-result-value">${formatNumber(Q_m3s * 1000)} л/с</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Массовый расход</span><span class="converter-result-value">${formatNumber(Q_m3s * rho * 3600)} кг/ч</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Формула</span><span class="converter-result-value">Q = α·ε·(πD²/4)·√(2Δp/ρ)·m</span></div>`;

        if (warnings.length > 0) {
            html += `<div class="warning-banner" style="margin:10px 0 0;"><div class="warning-icon"><svg viewBox="0 0 24 24"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg></div><div class="warning-banner-content"><div class="warning-banner-title">Рекомендации</div><div class="warning-banner-desc">${warnings.join('<br>')}</div></div></div>`;
        }

        document.getElementById('opResultsFlow').innerHTML = html;
        document.getElementById('opResultsFlow').style.display = 'block';
        setTimeout(() => document.getElementById('opResultsFlow').scrollIntoView({ behavior: 'smooth', block: 'start' }), 100);
    }

    // Расчёт диаметра диска d₂₀ по Q и Δp
    function calcOrificeDiameter() {
        let medium = document.getElementById('op_medium_type').value;
        let d20 = parseLocaleNumber(document.getElementById('op_d20').value);
        let dUnit = document.getElementById('op_d_unit').value;
        let pipeMat = document.getElementById('op_pipe_material').value;
        let temp = parseLocaleNumber(document.getElementById('op_temp').value);
        let flow = parseLocaleNumber(document.getElementById('op_flow').value);
        let flowUnit = document.getElementById('op_flow_unit').value;
        let flowMin = parseLocaleNumber(document.getElementById('op_flow_min').value);
        let pressure = parseLocaleNumber(document.getElementById('op_pressure').value);
        let rho = parseLocaleNumber(document.getElementById('op_density').value);
        let nu_cSt = parseLocaleNumber(document.getElementById('op_viscosity').value);
        let dp = parseLocaleNumber(document.getElementById('op_dp').value);
        let dpUnit = document.getElementById('op_dp_unit').value;
        let device = document.getElementById('op_device_type').value;
        let plateMat = document.getElementById('op_plate_material').value;

        if (isNaN(d20) || d20 <= 0) { showToast('Введите диаметр трубопровода'); return; }
        if (isNaN(flow) || flow <= 0) { showToast('Введите расход'); return; }
        if (isNaN(rho) || rho <= 0) { showToast('Введите плотность'); return; }
        if (isNaN(dp) || dp <= 0) { showToast('Введите перепад давления'); return; }
        if (isNaN(nu_cSt) || nu_cSt <= 0) { showToast('Введите вязкость'); return; }

        let D20_m = dUnit === 'mm' ? d20 / 1000 : d20;
        let Q_m3s = convertOpFlowToM3s(flow, flowUnit, rho);
        let dp_Pa = convertOpDpToPa(dp, dpUnit);
        let alpha_pipe = opThermalExpansion[pipeMat] || 11.9e-6;
        let alpha_plate = opThermalExpansion[plateMat] || 16.6e-6;
        let kt_pipe = 1 + alpha_pipe * (temp - 20);
        let kt_plate = 1 + alpha_plate * (temp - 20);
        let D = D20_m * kt_pipe;
        let coeff = opAlphaCoefficients[device];
        let kappa = medium === 'gas' ? (parseLocaleNumber(document.getElementById('op_kappa').value) || 1.4) : 1.0;
        let Z = medium === 'gas' ? (parseLocaleNumber(document.getElementById('op_z').value) || 1.0) : 1.0;
        let pressure_abs = pressure * 1e6 + 101325;

        let m = 0.25;
        let alpha, epsilon = 1.0;
        let Q_calc;
        let iter;
        for (iter = 0; iter < 50; iter++) {
            alpha = coeff.A + coeff.B * m + coeff.C * m * m + coeff.D * m * m * m;
            if (medium === 'gas') {
                let tau = dp_Pa / pressure_abs;
                epsilon = 1 - (0.41 + 0.35 * Math.pow(m, 1.5)) * tau / kappa;
                if (epsilon < 0.9) epsilon = 0.9;
            }
            Q_calc = alpha * epsilon * (Math.PI * D * D / 4) * Math.sqrt(2 * dp_Pa / rho) * m;
            let err = (Q_calc - Q_m3s) / Q_m3s;
            if (Math.abs(err) < 0.0001) break;
            m = m * (1 - err * 0.5);
            if (m < 0.02) m = 0.02;
            if (m > 0.70) m = 0.70;
        }

        let d = D * Math.sqrt(m);
        let d20_calc = d / kt_plate;
        let d_mm = d20_calc * 1000;
        let ReD = (4 * Q_m3s) / (Math.PI * D * nu_cSt * 1e-6);
        let ReD_min = ReD * (flowMin / flow);

        let warnings = [];
        if (m < 0.05) warnings.push('m < 0,05 — ниже рекомендуемого диапазона');
        if (m > 0.64) warnings.push('m > 0,64 — превышает рекомендуемый диапазон');
        if (ReD < 1e5) warnings.push('ReD < 10⁵ — возможна зависимость α от Re');
        if (d20_calc / D20_m > 0.8) warnings.push('d₂₀/D₂₀ > 0,8 — проверьте условия установки');
        if (flowMin / flow < 0.3) warnings.push('Qₘᵢₙ/Q < 0,3 — возможна недостаточная точность на малых расходах');

        let deviceNames = { orifice: 'Диафрагма стандартная', nozzle: 'Сопло стандартное', venturi: 'Труба Вентури' };
        let html = '<div class="converter-result-label-title">Результаты расчёта d₂₀ (РД 50-411-83)</div>';
        html += `<div class="converter-result-item"><span class="converter-result-label">Тип СУ</span><span class="converter-result-value">${deviceNames[device]}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Диаметр трубы D₂₀</span><span class="converter-result-value">${formatNumber(d20)} ${dUnit}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Рабочий диаметр D</span><span class="converter-result-value">${formatNumber(D * 1000)} мм</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Расход Q</span><span class="converter-result-value">${formatNumber(Q_m3s * 3600)} м³/ч</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Перепад Δp</span><span class="converter-result-value">${formatNumber(dp_Pa / 1000)} кПа</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Относительное отверстие m</span><span class="converter-result-value">${formatNumber(m)}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Коэффициент расхода α</span><span class="converter-result-value">${formatNumber(alpha)}</span></div>`;
        if (medium === 'gas') {
            html += `<div class="converter-result-item"><span class="converter-result-label">Коэффициент расширения ε</span><span class="converter-result-value">${formatNumber(epsilon)}</span></div>`;
        }
        html += `<div class="converter-result-item"><span class="converter-result-label">Число ReD (ном.)</span><span class="converter-result-value">${formatNumber(ReD)}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Число ReD (мин.)</span><span class="converter-result-value">${formatNumber(ReD_min)}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Диаметр отверстия d₂₀</span><span class="converter-result-value" style="color:#4ac771; font-size:14px;">${formatNumber(d_mm)} мм</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Отношение d₂₀/D₂₀</span><span class="converter-result-value">${formatNumber(d20_calc / D20_m)}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Итераций</span><span class="converter-result-value">${iter}</span></div>`;
        html += `<div class="converter-result-item"><span class="converter-result-label">Формула</span><span class="converter-result-value">Q = α·ε·(πD²/4)·√(2Δp/ρ)·m</span></div>`;

        if (warnings.length > 0) {
            html += `<div class="warning-banner" style="margin:10px 0 0;"><div class="warning-icon"><svg viewBox="0 0 24 24"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg></div><div class="warning-banner-content"><div class="warning-banner-title">Рекомендации</div><div class="warning-banner-desc">${warnings.join('<br>')}</div></div></div>`;
        }

        document.getElementById('opResultsDiameter').innerHTML = html;
        document.getElementById('opResultsDiameter').style.display = 'block';
        setTimeout(() => document.getElementById('opResultsDiameter').scrollIntoView({ behavior: 'smooth', block: 'start' }), 100);
    }

    document.addEventListener('DOMContentLoaded', function(){
        setSignalDefaults();
        setScaleDefaults();
        setLiquidDensity();
        updateBuoySignalUnit();
        if(document.getElementById('rtd_group')) updateRtdTypeOptions();
        if(document.getElementById('tc_type')) updateTcRanges();
        setCalibMethodOnForm();
        let firstActive=document.querySelector('.page-content.active');
        if(firstActive) { requestAnimationFrame(()=>firstActive.classList.add('visible')); updateBottomNavActive(firstActive.id.replace('page-','')); }
        let appHeader = document.querySelector('.app-header');
        if(appHeader && firstActive) appHeader.style.display = (firstActive.id === 'page-dashboard') ? 'block' : 'none';

        // Обработка location.hash при загрузке — для PWA shortcuts.
        // Если URL содержит #page-id (например, /kip8test/#exam-tickets),
        // открываем соответствующую страницу сразу.
        // Это позволяет manifest shortcuts работать.
        if (location.hash && location.hash.length > 1) {
            const hashPage = location.hash.substring(1);
            const target = document.getElementById('page-' + hashPage);
            if (target) {
                // Небольшая задержка, чтобы visible-класс успел примениться
                setTimeout(function() { navigateTo(hashPage, false); }, 50);
            }
        }

        // Обработка hashchange — если пользователь меняет хэш вручную
        // или через кнопку "назад" в браузере
        window.addEventListener('hashchange', function() {
            if (location.hash && location.hash.length > 1) {
                const hashPage = location.hash.substring(1);
                const target = document.getElementById('page-' + hashPage);
                if (target) {
                    const active = document.querySelector('.page-content.active');
                    if (active && active.id !== 'page-' + hashPage) {
                        navigateTo(hashPage, false);
                    }
                }
            }
        });

        // Запустить фоновый pre-cache картинок билетов при первой загрузке приложения.
        // loadTicketsData() загрузит JSON → вызовет precacheTicketImages() →
        // через requestIdleCallback фоном скачает все картинки через SW.
        // Это позволяет открывать билеты офлайн без необходимости сначала зайти в раздел.
        // Запускаем с задержкой 2с, чтобы не мешать первичной инициализации UI.
        setTimeout(function() {
            if (typeof loadTicketsData === 'function') {
                loadTicketsData().catch(function(e) {
                    console.warn('[precache] Не удалось запустить фоновый pre-cache:', e);
                });
            }
        }, 2000);

        // Запросить persistent storage — браузер не будет автоматически удалять
        // кэш SW (включая картинки билетов) при нехватке места на устройстве.
        // Особенно важно для TWA на Android — без этого через несколько недель
        // неактивности кэш может быть очищен системой.
        // Запрос делаем после короткой задержки, чтобы пользователь уже увидел UI.
        if (navigator.storage && navigator.storage.persist) {
            setTimeout(function() {
                navigator.storage.persist().then(function(persisted) {
                    if (persisted) {
                        console.log('[storage] Persistent storage активирован — кэш защищён от автоудаления');
                    } else {
                        console.log('[storage] Persistent storage не предоставлен (норма для некоторых браузеров)');
                    }
                }).catch(function(e) {
                    console.warn('[storage] Ошибка запроса persistent storage:', e);
                });
            }, 3000);
        }
    });

    // Theme toggle functionality
    function toggleTheme() {
        let currentTheme = localStorage.getItem('app-theme') || 'light';
        let newTheme = currentTheme === 'dark' ? 'light' : 'dark';
        document.documentElement.setAttribute('data-theme', newTheme);
        localStorage.setItem('app-theme', newTheme);
        updateThemeLabel();
        updateBuoyImages();
        updateLogoImage();
    }

    function updateThemeLabel() {
        let label = document.getElementById('themeLabel');
        if (label) {
            let currentTheme = document.documentElement.getAttribute('data-theme') || 'light';
            label.textContent = currentTheme === 'dark' ? 'Светлая тема' : 'Тёмная тема';
        }
    }

    function updateBuoyImages() {
        var isLight = document.documentElement.getAttribute('data-theme') === 'light';
        var buoyWithImg = document.getElementById('buoy-with-img');
        var buoyWithoutImg = document.getElementById('buoy-without-img');
        if (buoyWithImg) buoyWithImg.src = isLight ? 'images/buoy_with.png' : 'images/buoy_with_black.png';
        if (buoyWithoutImg) buoyWithoutImg.src = isLight ? 'images/buoy_without.png' : 'images/buoy_without_black.png';
    }

    function updateLogoImage() {
        var isLight = document.documentElement.getAttribute('data-theme') === 'light';
        var logoSrc = isLight ? 'images/logo.png' : 'images/logo_black.png';
        var logo = document.getElementById('headerLogo');
        if (logo) logo.src = logoSrc;
        var logoDesktop = document.getElementById('headerLogoDesktop');
        if (logoDesktop) logoDesktop.src = logoSrc;
    }

    // Apply saved theme on load
    (function() {
        let savedTheme = localStorage.getItem('app-theme') || 'light';
        document.documentElement.setAttribute('data-theme', savedTheme);
        // Перезапись UI (label, logos, buoy) выполняется в последнем
        // <script> блоке, когда все DOM-элементы уже существуют.
        // Здесь вызываем для элементов, которые уже разобраны к этому моменту.
        updateThemeLabel();
        updateBuoyImages();
        updateLogoImage();
    })();

    // Auto-detect system color scheme preference
    (function() {
        const saved = localStorage.getItem('app-theme');
        if (!saved) {
            const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
            document.documentElement.setAttribute('data-theme', prefersDark ? 'dark' : 'light');
            if (typeof updateThemeLabel === 'function') updateThemeLabel();
            if (typeof updateLogoImage === 'function') updateLogoImage();
        }
        // Listen for system theme changes
        window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', (e) => {
            if (!localStorage.getItem('app-theme')) {
                document.documentElement.setAttribute('data-theme', e.matches ? 'dark' : 'light');
                if (typeof updateThemeLabel === 'function') updateThemeLabel();
                if (typeof updateBuoyImages === 'function') updateBuoyImages();
                if (typeof updateLogoImage === 'function') updateLogoImage();
            }
        });
    })();

    // Haptic feedback on navigation and button presses
    document.addEventListener('click', function(e) {
        const target = e.target.closest('.nav-btn, .menu-btn, .bottom-nav-item, .converter-convert-btn, .scale-calc-btn, .query-btn, .header-btn, .ticket-cat-card, .ticket-item-header, .ticket-nav-btn, .ticket-a-img, .ticket-a-imglink, .ticket-img-overlay-close, .ticket-ref-link, .connection-indicator, .dashboard-quick-btn, .menu-btn-overflow, .dashboard-bottom-btn, .pin-sheet-action, .pin-sheet-cancel');
        if (target && navigator.vibrate) {
            navigator.vibrate(15);
        }
    });

    // ====== Custom Select Dropdown System ======
    (function() {
        // Container for all dropdown panels (appended to body to avoid z-index stacking issues)
        var dropdownContainer = document.createElement('div');
        dropdownContainer.id = 'cs-dropdown-container';
        dropdownContainer.style.cssText = 'position:fixed;top:0;left:0;width:0;height:0;z-index:99999;pointer-events:none;';
        document.body.appendChild(dropdownContainer);

        // Global click handler to close dropdowns when clicking outside
        document.addEventListener('click', function(e) {
            if (!e.target.closest('.cs-wrapper') && !e.target.closest('.cs-dropdown')) {
                closeAllDropdowns();
            }
        });
        // Close on Escape key
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape') closeAllDropdowns();
        });

        function closeAllDropdowns() {
            document.querySelectorAll('.cs-dropdown.cs-show').forEach(function(dd) {
                dd.classList.remove('cs-show');
                dd.classList.remove('cs-drop-up');
                dd.style.pointerEvents = 'none';
                dd.style.minWidth = '';
                dd.style.maxWidth = '';
                dd.style.width = '';
                var trigger = dd._csTrigger;
                if (trigger) trigger.classList.remove('cs-open');
            });
        }

        // Map: select element → current optgroup hint for its options
        // Used for selects with optgroups (e.g. buoy_signal_type) where
        // optgroup data is shown inline (Task 372: temp_rtd_type удалён)
        function getOptgroupHints(select) {
            var hints = {};
            var currentGroup = '';
            var options = select.querySelectorAll('option, optgroup');
            options.forEach(function(opt) {
                if (opt.tagName === 'OPTGROUP') {
                    currentGroup = opt.getAttribute('label') || '';
                } else if (opt.tagName === 'OPTION') {
                    hints[opt.value] = currentGroup;
                }
            });
            return hints;
        }

        function buildDropdown(select) {
            // Skip already-converted selects
            if (select.closest('.cs-wrapper')) return;

            var wrapper = document.createElement('div');
            wrapper.className = 'cs-wrapper';

            // Transfer layout-related inline styles from select to wrapper
            var inlineStyle = select.getAttribute('style') || '';
            var layoutProps = ['flex', 'width', 'min-width', 'max-width', 'margin-bottom'];
            var wrapperStyle = '';
            layoutProps.forEach(function(prop) {
                var re = new RegExp(prop + '\\s*:\\s*([^;]+)', 'i');
                var m = inlineStyle.match(re);
                if (m) wrapperStyle += prop + ':' + m[1] + ';';
            });
            if (wrapperStyle) wrapper.setAttribute('style', wrapperStyle);

            // Mark wrapper as being inside kit-dev-form context (for CSS descendant selectors)
            // Do NOT add 'kit-dev-form' class directly — it carries unwanted margin/padding

            // Build trigger
            var trigger = document.createElement('div');
            trigger.className = 'cs-trigger';
            trigger.setAttribute('tabindex', '0');
            trigger.setAttribute('role', 'combobox');
            trigger.setAttribute('aria-expanded', 'false');
            var selectedOpt = select.options[select.selectedIndex];
            var triggerText = document.createElement('span');
            triggerText.className = 'cs-trigger-text';
            triggerText.textContent = selectedOpt ? selectedOpt.textContent : '';
            trigger.appendChild(triggerText);

            // Build dropdown panel (appended to body container for z-index fix)
            var dropdown = document.createElement('div');
            dropdown.className = 'cs-dropdown';
            dropdown._csTrigger = trigger;

            // Get optgroup hints if this select uses optgroups with meaningful data
            var hints = getOptgroupHints(select);

            buildDropdownOptions(select, dropdown, hints);

            dropdownContainer.appendChild(dropdown);

            // Toggle dropdown on trigger click
            trigger.addEventListener('click', function(ev) {
                ev.stopPropagation();
                var isOpen = dropdown.classList.contains('cs-show');
                closeAllDropdowns();
                if (!isOpen) {
                    // Position dropdown relative to trigger using fixed positioning
                    var triggerRect = trigger.getBoundingClientRect();
                    var spaceBelow = window.innerHeight - triggerRect.bottom;
                    var spaceAbove = triggerRect.top;
                    // Measure dropdown: auto-size width to fit content, min = trigger width
                    var vpWidth = window.innerWidth;
                    dropdown.style.visibility = 'hidden';
                    dropdown.style.display = 'block';
                    dropdown.style.minWidth = triggerRect.width + 'px';
                    dropdown.style.maxWidth = (vpWidth - 16) + 'px';
                    dropdown.style.width = 'auto';
                    var dropHeight = Math.min(dropdown.scrollHeight, 220);
                    var dropWidth = dropdown.offsetWidth;
                    dropdown.style.display = '';
                    dropdown.style.visibility = '';

                    // Calculate left position: align to trigger, but keep within viewport
                    var dropLeft = triggerRect.left;
                    if (dropLeft + dropWidth > vpWidth - 8) {
                        dropLeft = Math.max(8, vpWidth - dropWidth - 8);
                    }

                    if (spaceBelow < dropHeight && spaceAbove > spaceBelow) {
                        dropdown.style.top = 'auto';
                        dropdown.style.bottom = (window.innerHeight - triggerRect.top + 4) + 'px';
                        dropdown.style.left = dropLeft + 'px';
                        dropdown.classList.add('cs-drop-up');
                    } else {
                        dropdown.style.top = (triggerRect.bottom + 4) + 'px';
                        dropdown.style.bottom = 'auto';
                        dropdown.style.left = dropLeft + 'px';
                        dropdown.classList.remove('cs-drop-up');
                    }
                    dropdown.classList.add('cs-show');
                    dropdown.style.pointerEvents = 'auto';
                    trigger.classList.add('cs-open');
                    trigger.setAttribute('aria-expanded', 'true');
                    scrollToSelected(dropdown);
                } else {
                    trigger.setAttribute('aria-expanded', 'false');
                }
            });
            // Keyboard support
            trigger.addEventListener('keydown', function(ev) {
                if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); trigger.click(); }
                else if (ev.key === 'Escape') closeAllDropdowns();
            });

            // Hide the native select visually but keep in DOM for JS compatibility
            select.style.position = 'absolute';
            select.style.width = '0';
            select.style.height = '0';
            select.style.opacity = '0';
            select.style.pointerEvents = 'none';
            select.style.overflow = 'hidden';
            select.style.margin = '0';
            select.style.padding = '0';
            select.style.border = 'none';

            // Insert wrapper
            select.parentNode.insertBefore(wrapper, select);
            wrapper.appendChild(trigger);
            wrapper.appendChild(select);

            // Store references
            select._csWrapper = wrapper;
            select._csTrigger = trigger;
            select._csTriggerText = triggerText;
            select._csDropdown = dropdown;
            select._csHints = hints;
        }

        function buildDropdownOptions(select, dropdown, hints) {
            dropdown.innerHTML = '';
            var options = select.querySelectorAll('option, optgroup');
            options.forEach(function(opt) {
                if (opt.tagName === 'OPTGROUP') {
                    // Skip optgroup labels — they are shown as hints inline
                    return;
                } else if (opt.tagName === 'OPTION') {
                    var optDiv = document.createElement('div');
                    optDiv.className = 'cs-option';
                    if (opt.selected) optDiv.classList.add('cs-selected');
                    if (opt.disabled) optDiv.classList.add('cs-disabled');
                    optDiv.setAttribute('data-value', opt.value);

                    var mainText = document.createElement('span');
                    mainText.textContent = opt.textContent;
                    optDiv.appendChild(mainText);

                    // If there's an optgroup hint or data-hint attribute for this option, show it inline on the right
                    var hintText = hints[opt.value] || opt.getAttribute('data-hint') || '';
                    if (hintText) {
                        var hintSpan = document.createElement('span');
                        hintSpan.className = 'cs-option-hint';
                        hintSpan.textContent = hintText;
                        optDiv.appendChild(hintSpan);
                    }

                    optDiv.addEventListener('click', function(ev) {
                        ev.stopPropagation();
                        if (optDiv.classList.contains('cs-disabled')) return;
                        selectOption(select, optDiv);
                    });
                    dropdown.appendChild(optDiv);
                }
            });
        }

        function selectOption(select, optDiv) {
            var trigger = select._csTrigger;
            var dropdown = select._csDropdown;
            var value = optDiv.getAttribute('data-value');
            // Set value (triggers syncFromNative via overridden setter)
            select.value = value;

            // Update selected visual
            dropdown.querySelectorAll('.cs-option.cs-selected').forEach(function(o) { o.classList.remove('cs-selected'); });
            optDiv.classList.add('cs-selected');

            // Close dropdown
            dropdown.classList.remove('cs-show');
            dropdown.classList.remove('cs-drop-up');
            dropdown.style.pointerEvents = 'none';
            dropdown.style.minWidth = '';
            dropdown.style.maxWidth = '';
            dropdown.style.width = '';
            trigger.classList.remove('cs-open');
            trigger.setAttribute('aria-expanded', 'false');

            // Fire native change event
            var event = new Event('change', { bubbles: true });
            select.dispatchEvent(event);

            // Haptic feedback
            if (navigator.vibrate) navigator.vibrate(10);
        }

        function scrollToSelected(dropdown) {
            var selected = dropdown.querySelector('.cs-option.cs-selected');
            if (selected) {
                setTimeout(function() {
                    selected.scrollIntoView({ block: 'nearest', inline: 'nearest' });
                }, 10);
            }
        }

        // Sync custom dropdown when native select value changes programmatically
        function syncFromNative(select) {
            var trigger = select._csTrigger;
            var triggerText = select._csTriggerText;
            var dropdown = select._csDropdown;
            if (!trigger || !triggerText || !dropdown) return;

            var selectedOpt = select.options[select.selectedIndex];
            triggerText.textContent = selectedOpt ? selectedOpt.textContent : '';

            dropdown.querySelectorAll('.cs-option').forEach(function(o) {
                if (o.getAttribute('data-value') === select.value) {
                    o.classList.add('cs-selected');
                } else {
                    o.classList.remove('cs-selected');
                }
            });
        }

        // Override value setter on HTMLSelectElement
        var origValueDesc = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value');
        var origValueGetter = origValueDesc.get;
        var origValueSetter = origValueDesc.set;
        Object.defineProperty(HTMLSelectElement.prototype, 'value', {
            set: function(val) {
                origValueSetter.call(this, val);
                if (this._csWrapper) syncFromNative(this);
            },
            get: function() { return origValueGetter.call(this); }
        });

        // Override selected setter on HTMLOptionElement
        var origOptionSelectedDesc = Object.getOwnPropertyDescriptor(HTMLOptionElement.prototype, 'selected');
        var origOptionSelectedGetter = origOptionSelectedDesc.get;
        var origOptionSelectedSetter = origOptionSelectedDesc.set;
        Object.defineProperty(HTMLOptionElement.prototype, 'selected', {
            set: function(val) {
                origOptionSelectedSetter.call(this, val);
                var select = this.closest('select');
                if (select && select._csWrapper) syncFromNative(select);
            },
            get: function() { return origOptionSelectedGetter.call(this); }
        });

        // Override disabled setter on HTMLOptionElement
        var origOptionDisabledDesc = Object.getOwnPropertyDescriptor(HTMLOptionElement.prototype, 'disabled');
        var origOptionDisabledGetter = origOptionDisabledDesc.get;
        var origOptionDisabledSetter = origOptionDisabledDesc.set;
        Object.defineProperty(HTMLOptionElement.prototype, 'disabled', {
            set: function(val) {
                origOptionDisabledSetter.call(this, val);
                var select = this.closest('select');
                if (select && select._csDropdown) {
                    var val_ = this.value;
                    var optEl = select._csDropdown.querySelector('.cs-option[data-value="' + CSS.escape(val_) + '"]');
                    if (optEl) {
                        if (val) optEl.classList.add('cs-disabled');
                        else optEl.classList.remove('cs-disabled');
                    }
                }
            },
            get: function() { return origOptionDisabledGetter.call(this); }
        });

        // Override innerHTML setter for <select> to auto-rebuild custom dropdown
        var origInnerHTMLDesc = Object.getOwnPropertyDescriptor(Element.prototype, 'innerHTML');
        Object.defineProperty(HTMLSelectElement.prototype, 'innerHTML', {
            set: function(html) {
                origInnerHTMLDesc.set.call(this, html);
                if (this._csWrapper && typeof window.rebuildCustomSelect === 'function') {
                    window.rebuildCustomSelect(this);
                }
            },
            get: function() { return origInnerHTMLDesc.get.call(this); }
        });

        // Initialize all existing selects
        function initCustomSelects(root) {
            root = root || document;
            var selects = root.querySelectorAll('select.scale-field, select.form-field');
            selects.forEach(function(sel) { buildDropdown(sel); });
        }

        // Refresh custom selects for dynamically added content
        window.refreshCustomSelects = function(container) {
            container = container || document;
            var selects = container.querySelectorAll('select.scale-field, select.form-field');
            selects.forEach(function(sel) {
                if (!sel._csWrapper) buildDropdown(sel);
            });
        };

        // Rebuild a specific select's custom dropdown (when options change)
        window.rebuildCustomSelect = function(selectEl) {
            if (!selectEl || !selectEl._csWrapper) return;
            var dropdown = selectEl._csDropdown;
            var hints = getOptgroupHints(selectEl);
            selectEl._csHints = hints;
            buildDropdownOptions(selectEl, dropdown, hints);
            syncFromNative(selectEl);
        };

        // Initialize on DOMContentLoaded
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', function() { initCustomSelects(); });
        } else {
            initCustomSelects();
        }

        // MutationObserver for dynamically added selects
        var csObserver = new MutationObserver(function(mutations) {
            mutations.forEach(function(m) {
                m.addedNodes.forEach(function(node) {
                    if (node.nodeType !== 1) return;
                    if (node.tagName === 'SELECT' && (node.classList.contains('scale-field') || node.classList.contains('form-field'))) {
                        if (!node._csWrapper) buildDropdown(node);
                    }
                    var selects = node.querySelectorAll ? node.querySelectorAll('select.scale-field, select.form-field') : [];
                    selects.forEach(function(sel) {
                        if (!sel._csWrapper) buildDropdown(sel);
                    });
                });
            });
        });
        csObserver.observe(document.body, { childList: true, subtree: true });

        // Reposition open dropdown on scroll/resize
        window.addEventListener('scroll', function() {
            document.querySelectorAll('.cs-dropdown.cs-show').forEach(function(dd) {
                var trigger = dd._csTrigger;
                if (!trigger) return;
                var rect = trigger.getBoundingClientRect();
                var vpW = window.innerWidth;
                dd.style.minWidth = rect.width + 'px';
                dd.style.maxWidth = (vpW - 16) + 'px';
                dd.style.width = 'auto';
                var dw = dd.offsetWidth;
                var dl = rect.left;
                if (dl + dw > vpW - 8) dl = Math.max(8, vpW - dw - 8);
                dd.style.left = dl + 'px';
                if (dd.classList.contains('cs-drop-up')) {
                    dd.style.bottom = (window.innerHeight - rect.top + 4) + 'px';
                    dd.style.top = 'auto';
                } else {
                    dd.style.top = (rect.bottom + 4) + 'px';
                    dd.style.bottom = 'auto';
                }
            });
        }, true);
        window.addEventListener('resize', function() {
            document.querySelectorAll('.cs-dropdown.cs-show').forEach(function(dd) {
                var trigger = dd._csTrigger;
                if (!trigger) return;
                var rect = trigger.getBoundingClientRect();
                var vpW = window.innerWidth;
                dd.style.minWidth = rect.width + 'px';
                dd.style.maxWidth = (vpW - 16) + 'px';
                dd.style.width = 'auto';
                var dw = dd.offsetWidth;
                var dl = rect.left;
                if (dl + dw > vpW - 8) dl = Math.max(8, vpW - dw - 8);
                dd.style.left = dl + 'px';
            });
        });
    })();

